#[derive(Clone)]
enum SceneLightDispatch {
    On(LightingCommand),
    Off(Option<u32>),
}

#[derive(Clone)]
struct SceneLightCommand {
    public_node_id: String,
    dispatch_node_id: String,
    dispatch: SceneLightDispatch,
}

struct SceneApplicationPlan {
    commands: Vec<SceneLightCommand>,
    affected_node_ids: Vec<String>,
    unresolved_node_ids: Vec<String>,
}

#[derive(Clone)]
struct RenderedSceneLight {
    node_id: String,
    output: LightSceneOutput,
}

struct ManagedSceneDispatch {
    discovery: Arc<dyn HubDiscovery>,
    projection: ManagedSceneProjection,
    transition_ms: Option<u32>,
    projected_states: Vec<(String, bool)>,
}

enum SceneApplySource {
    Stored(String),
    Definition(SceneDefinition),
}

fn light_scene_target_scope_node_ids(
    s: &AppState,
    runtime: &Arc<dyn RuntimeHandle>,
    target_id: &str,
) -> BTreeSet<String> {
    let mut node_ids = BTreeSet::new();

    if s.topology.get(target_id).is_some() {
        for node in s.topology.device_nodes() {
            if node.parent_id.as_deref() != Some(target_id) {
                continue;
            }
            let Some(device) = s.canonical_registry.get(&node.canonical_device_id) else {
                continue;
            };
            if device.device_type == DeviceType::Light {
                node_ids.insert(node.id.clone());
            }
        }
        if !node_ids.is_empty() {
            return node_ids;
        }
    }

    if let Some(node) = s.topology.get_device_node(target_id) {
        if s.canonical_registry
            .get(&node.canonical_device_id)
            .is_some_and(|device| device.device_type == DeviceType::Light)
        {
            node_ids.insert(node.id.clone());
            return node_ids;
        }
    }

    let Some(target) = runtime.engine_effective_node_snapshot(target_id) else {
        return node_ids;
    };
    if target.kind.is_room() {
        for node in runtime.engine_all_effective_node_snapshots() {
            if node.parent_id.as_deref() == Some(target.id.as_str())
                && node.kind.is_light_addressable()
            {
                node_ids.insert(node.id);
            }
        }
        if node_ids.is_empty() {
            node_ids.insert(target.id);
        }
    } else if target.kind.is_light_addressable() {
        node_ids.insert(target.id);
    }

    node_ids
}

fn light_scene_dispatch_node_id(s: &AppState, node_id: &str) -> Option<String> {
    if s.composite_controller.is_none()
        || s.topology.get(node_id).is_some()
        || s.topology.get_device_node(node_id).is_some()
    {
        Some(node_id.to_string())
    } else {
        None
    }
}

fn push_scene_light_command(
    s: &AppState,
    layer_transition_ms: Option<u32>,
    request_transition_ms: Option<u32>,
    node_id: &str,
    output: &crate::scenes::LightSceneOutput,
    commands: &mut Vec<SceneLightCommand>,
    unresolved_node_ids: &mut Vec<String>,
) -> Result<()> {
    let Some(dispatch_node_id) = light_scene_dispatch_node_id(s, node_id) else {
        unresolved_node_ids.push(node_id.to_string());
        return Ok(());
    };
    let mut output = output.clone();
    if let Some(transition_ms) = request_transition_ms {
        output.transition_ms = Some(transition_ms);
    }
    let dispatch = match output
        .to_command(layer_transition_ms)
        .map_err(|e| anyhow::anyhow!("Invalid light scene output for '{}': {}", node_id, e))?
    {
        Some(command) => SceneLightDispatch::On(command),
        None => SceneLightDispatch::Off(output.transition_ms(layer_transition_ms)),
    };
    commands.push(SceneLightCommand {
        public_node_id: node_id.to_string(),
        dispatch_node_id,
        dispatch,
    });
    Ok(())
}

fn build_scene_application_plan_locked(
    s: &AppState,
    runtime: &Arc<dyn RuntimeHandle>,
    scene: &SceneDefinition,
    target_id: &str,
    transition_ms: Option<u32>,
) -> Result<SceneApplicationPlan> {
    let layer = scene
        .light
        .as_ref()
        .ok_or_else(|| anyhow::anyhow!("Scene '{}' has no light layer", scene.id))?;
    let scope_node_ids = light_scene_target_scope_node_ids(s, runtime, target_id);
    if scope_node_ids.is_empty() {
        return Err(anyhow::anyhow!(
            "Target '{}' has no light scene-addressable nodes",
            target_id
        ));
    }

    let mut commands = Vec::new();
    let mut unresolved_node_ids = Vec::new();
    let mut explicit_node_ids = BTreeSet::new();
    for entry in &layer.entries {
        let node_id = match &entry.target {
            LightSceneTargetRef::Node { node_id } => node_id,
        };
        if !scope_node_ids.contains(node_id) {
            continue;
        }
        explicit_node_ids.insert(node_id.clone());
        push_scene_light_command(
            s,
            layer.default_transition_ms,
            transition_ms,
            node_id,
            &entry.output,
            &mut commands,
            &mut unresolved_node_ids,
        )?;
    }

    let implicit_node_ids: Vec<_> = scope_node_ids
        .iter()
        .filter(|node_id| !explicit_node_ids.contains(*node_id))
        .collect();
    let direct_palette_room = s.topology.get(target_id).is_some()
        && explicit_node_ids.is_empty()
        && !layer.palette.is_empty()
        && !implicit_node_ids.is_empty()
        && implicit_node_ids.iter().all(|node_id| {
            s.topology
                .light_node_uses_device_dispatch(node_id, &s.canonical_registry)
        });
    let room_default_dispatched = if s.topology.get(target_id).is_some()
        && explicit_node_ids.is_empty()
        && !direct_palette_room
    {
        if let Some(room_output) = layer.palette.first().or(layer.default_output.as_ref()) {
            push_scene_light_command(
                s,
                layer.default_transition_ms,
                transition_ms,
                target_id,
                room_output,
                &mut commands,
                &mut unresolved_node_ids,
            )?;
            true
        } else {
            false
        }
    } else {
        false
    };

    if !room_default_dispatched {
        if !layer.palette.is_empty() {
            for (index, node_id) in implicit_node_ids.iter().enumerate() {
                let output = &layer.palette[index % layer.palette.len()];
                push_scene_light_command(
                    s,
                    layer.default_transition_ms,
                    transition_ms,
                    node_id,
                    output,
                    &mut commands,
                    &mut unresolved_node_ids,
                )?;
            }
        } else if let Some(default_output) = &layer.default_output {
            for node_id in implicit_node_ids {
                push_scene_light_command(
                    s,
                    layer.default_transition_ms,
                    transition_ms,
                    node_id,
                    default_output,
                    &mut commands,
                    &mut unresolved_node_ids,
                )?;
            }
        }
    }
    commands.sort_by(|left, right| left.public_node_id.cmp(&right.public_node_id));
    unresolved_node_ids.sort();
    unresolved_node_ids.dedup();

    let affected_node_ids: Vec<_> = commands
        .iter()
        .map(|command| command.public_node_id.clone())
        .collect();
    if affected_node_ids.is_empty() {
        return Err(anyhow::anyhow!(
            "Scene '{}' has no routable light entries for target '{}'",
            scene.id,
            target_id
        ));
    }

    Ok(SceneApplicationPlan {
        commands,
        affected_node_ids,
        unresolved_node_ids,
    })
}

fn render_scene_lights_locked(
    s: &AppState,
    runtime: &Arc<dyn RuntimeHandle>,
    scene: &SceneDefinition,
    target_id: &str,
    transition_ms: Option<u32>,
) -> Result<(BTreeSet<String>, Vec<RenderedSceneLight>)> {
    let layer = scene
        .light
        .as_ref()
        .ok_or_else(|| anyhow::anyhow!("Scene '{}' has no light layer", scene.id))?;
    let scope_node_ids = light_scene_target_scope_node_ids(s, runtime, target_id);
    let mut outputs = BTreeMap::<String, LightSceneOutput>::new();
    for entry in &layer.entries {
        let node_id = entry.target.node_id();
        if scope_node_ids.contains(node_id) {
            outputs.insert(node_id.to_string(), entry.output.clone());
        }
    }

    let implicit_node_ids = scope_node_ids
        .iter()
        .filter(|node_id| !outputs.contains_key(*node_id))
        .cloned()
        .collect::<Vec<_>>();
    if !layer.palette.is_empty() {
        for (index, node_id) in implicit_node_ids.into_iter().enumerate() {
            outputs.insert(node_id, layer.palette[index % layer.palette.len()].clone());
        }
    } else if let Some(default_output) = &layer.default_output {
        for node_id in implicit_node_ids {
            outputs.insert(node_id, default_output.clone());
        }
    }

    let mut rendered = Vec::with_capacity(outputs.len());
    for (node_id, mut output) in outputs {
        if let Some(transition_ms) = transition_ms {
            output.transition_ms = Some(transition_ms);
        } else if output.transition_ms.is_none() {
            output.transition_ms = layer.default_transition_ms;
        }
        output
            .to_command(None)
            .map_err(|error| anyhow::anyhow!("Invalid light scene output: {error}"))?;
        rendered.push(RenderedSceneLight { node_id, output });
    }
    Ok((scope_node_ids, rendered))
}

fn authoritative_endpoint_for_scene_node(
    s: &AppState,
    node_id: &str,
) -> Result<Option<(String, HubKey, String)>> {
    let Some(node) = s.topology.get_device_node(node_id) else {
        return Ok(None);
    };
    let Some(rhythm_room_id) = node.parent_id.clone() else {
        // Truly roomless lights retain direct device control.
        return Ok(None);
    };
    let Some(device) = s.canonical_registry.get(&node.canonical_device_id) else {
        return Ok(None);
    };
    let mut endpoints = device
        .active_endpoints()
        .filter(|endpoint| {
            s.topology
                .grouped_room_control_is_required(&endpoint.hub_key)
        })
        .map(|endpoint| (endpoint.hub_key.clone(), endpoint.native_id.clone()))
        .collect::<Vec<_>>();
    endpoints.sort_by(|left, right| {
        left.0
            .to_string()
            .cmp(&right.0.to_string())
            .then_with(|| left.1.cmp(&right.1))
    });
    match endpoints.as_slice() {
        [] => Ok(None),
        [(hub_key, native_id)] => Ok(Some((rhythm_room_id, hub_key.clone(), native_id.clone()))),
        _ => anyhow::bail!("A room light has multiple authoritative grouped controllers"),
    }
}

fn managed_scene_dispatches_locked(
    s: &AppState,
    scene: &SceneDefinition,
    scope_node_ids: &BTreeSet<String>,
    rendered: &[RenderedSceneLight],
) -> Result<Vec<ManagedSceneDispatch>> {
    struct Builder {
        hub_key: HubKey,
        rhythm_room_id: String,
        hub_room_id: String,
        discovery: Arc<dyn HubDiscovery>,
        targets: Vec<ManagedSceneProjectionTarget>,
        projected_states: Vec<(String, bool)>,
        transitions: BTreeSet<u32>,
        has_no_transition: bool,
    }

    let rendered_by_node = rendered
        .iter()
        .map(|light| (light.node_id.as_str(), light))
        .collect::<HashMap<_, _>>();
    let mut builders = Vec::<Builder>::new();

    // Visit the full scope, not only rendered entries. A durable scene update
    // that stops targeting Hue must retire its previous native projection.
    for node_id in scope_node_ids {
        let Some((rhythm_room_id, hub_key, native_device_id)) =
            authoritative_endpoint_for_scene_node(s, node_id)?
        else {
            continue;
        };
        if !s.external_controller_authority_is_ready(&hub_key) {
            anyhow::bail!("An authoritative grouped controller is not ready");
        }
        let binding = s
            .topology
            .exact_managed_group_binding(&rhythm_room_id, &hub_key, &s.canonical_registry)
            .ok_or_else(|| {
                anyhow::anyhow!("An authoritative room binding is missing, stale, or ambiguous")
            })?;
        if !binding
            .light_device_ids
            .iter()
            .any(|device_id| device_id == &native_device_id)
        {
            anyhow::bail!("An authoritative room binding has stale membership");
        }
        let discovery = s
            .hubs
            .get(&hub_key)
            .and_then(|hub| hub.discovery.clone())
            .ok_or_else(|| anyhow::anyhow!("An authoritative controller is unavailable"))?;
        let builder_index = builders
            .iter()
            .position(|builder| {
                builder.hub_key == hub_key && builder.rhythm_room_id == rhythm_room_id
            })
            .unwrap_or_else(|| {
                builders.push(Builder {
                    hub_key: hub_key.clone(),
                    rhythm_room_id: rhythm_room_id.clone(),
                    hub_room_id: binding.hub_room_id.clone(),
                    discovery,
                    targets: Vec::new(),
                    projected_states: Vec::new(),
                    transitions: BTreeSet::new(),
                    has_no_transition: false,
                });
                builders.len() - 1
            });
        let builder = &mut builders[builder_index];
        if builder.hub_room_id != binding.hub_room_id {
            anyhow::bail!("An authoritative room has conflicting native bindings");
        }
        let Some(light) = rendered_by_node.get(node_id.as_str()) else {
            continue;
        };
        match light.output.transition_ms {
            Some(transition_ms) => {
                builder.transitions.insert(transition_ms);
            }
            None => builder.has_no_transition = true,
        }
        builder.targets.push(ManagedSceneProjectionTarget {
            native_device_id,
            output: light.output.clone(),
        });
        builder
            .projected_states
            .push((node_id.clone(), light.output.power == LightScenePower::On));
    }

    let mut dispatches = Vec::with_capacity(builders.len());
    for mut builder in builders {
        if builder.transitions.len() > 1
            || (builder.has_no_transition && !builder.transitions.is_empty())
        {
            anyhow::bail!(
                "A managed room scene has per-light transitions that Hue cannot recall atomically"
            );
        }
        builder
            .targets
            .sort_by(|left, right| left.native_device_id.cmp(&right.native_device_id));
        builder
            .projected_states
            .sort_by(|left, right| left.0.cmp(&right.0));
        dispatches.push(ManagedSceneDispatch {
            discovery: builder.discovery,
            projection: ManagedSceneProjection {
                rhythm_room_id: builder.rhythm_room_id,
                hub_room_id: builder.hub_room_id,
                scene_id: scene.id.clone(),
                targets: builder.targets,
            },
            transition_ms: builder.transitions.into_iter().next(),
            projected_states: builder.projected_states,
        });
    }
    dispatches.sort_by(|left, right| {
        left.projection
            .rhythm_room_id
            .cmp(&right.projection.rhythm_room_id)
            .then_with(|| {
                left.projection
                    .hub_room_id
                    .cmp(&right.projection.hub_room_id)
            })
    });
    Ok(dispatches)
}

fn companion_scene_plan_locked(
    s: &AppState,
    rendered: &[RenderedSceneLight],
    managed: &[ManagedSceneDispatch],
) -> Result<SceneApplicationPlan> {
    let projected_node_ids = managed
        .iter()
        .flat_map(|dispatch| {
            dispatch
                .projected_states
                .iter()
                .map(|(node_id, _)| node_id.as_str())
        })
        .collect::<HashSet<_>>();
    let mut commands = Vec::new();
    let mut unresolved_node_ids = Vec::new();
    for light in rendered {
        if projected_node_ids.contains(light.node_id.as_str()) {
            continue;
        }
        push_scene_light_command(
            s,
            None,
            None,
            &light.node_id,
            &light.output,
            &mut commands,
            &mut unresolved_node_ids,
        )?;
    }
    commands.sort_by(|left, right| left.public_node_id.cmp(&right.public_node_id));
    unresolved_node_ids.sort();
    unresolved_node_ids.dedup();
    let mut affected_node_ids = managed
        .iter()
        .flat_map(|dispatch| {
            dispatch
                .projected_states
                .iter()
                .map(|(node_id, _)| node_id.clone())
        })
        .chain(
            commands
                .iter()
                .map(|command| command.public_node_id.clone()),
        )
        .collect::<Vec<_>>();
    affected_node_ids.sort();
    affected_node_ids.dedup();
    Ok(SceneApplicationPlan {
        commands,
        affected_node_ids,
        unresolved_node_ids,
    })
}

fn set_scene_committed_state(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    scene_id: &str,
    target_id: &str,
    affected_node_ids: &[String],
) {
    let mut state_node_ids: BTreeSet<String> = BTreeSet::new();
    if runtime
        .engine_effective_node_snapshot(target_id)
        .is_some_and(|snap| snap.kind.is_room())
    {
        state_node_ids.insert(target_id.to_string());
    } else {
        state_node_ids.extend(affected_node_ids.iter().cloned());
    }

    for node_id in state_node_ids {
        let Some(snap) = runtime.engine_node_snapshot(&node_id) else {
            continue;
        };
        let mut profile_settings = snap.profile_settings.clone();
        profile_settings.mood_scene_id = Some(scene_id.to_string());
        runtime.restore_node_state(
            &node_id,
            RestoredNodeState {
                rhythm_enabled: true,
                disabled: snap.disabled,
                time_offset_minutes: snap.time_offset_minutes,
                brightness_offset: snap.brightness_offset,
                soft_off: false,
                mood_active: true,
                standby_enabled: snap.standby_enabled,
                hard_off: false,
                profile_settings,
            },
        );
    }

    clear_room_mode_transition(state, target_id);
    queue_motion_timer_clear(state, target_id);
}

fn clear_scene_preview_sessions_locked(
    s: &mut AppState,
    target_id: &str,
    affected_node_ids: &[String],
) {
    s.light_scene_previews.retain(|_, preview| {
        preview.target_node_id != target_id
            && !preview
                .affected_node_ids
                .iter()
                .any(|node_id| affected_node_ids.iter().any(|affected| affected == node_id))
    });
}

fn dispatch_scene_plan(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    plan: &SceneApplicationPlan,
) -> Result<()> {
    for command in &plan.commands {
        let lights_on = match &command.dispatch {
            SceneLightDispatch::On(lighting_command) => {
                log_room_command_dispatch(
                    runtime.as_ref(),
                    &command.dispatch_node_id,
                    lighting_command,
                );
                runtime.apply_room_command(&command.dispatch_node_id, lighting_command.clone())?;
                true
            }
            SceneLightDispatch::Off(transition_ms) => {
                runtime.lights_off_room(&command.dispatch_node_id, *transition_ms)?;
                false
            }
        };
        update_lights_on_cache_for_runtime_node(state, runtime, &command.public_node_id, lights_on);
        emit_node_state_event_after_apply(state, runtime, &command.public_node_id);
    }
    Ok(())
}

fn do_scene_apply_definition_inner(
    state: &SharedState,
    source: SceneApplySource,
    request: SceneApplyRequest,
    commit_state: bool,
    persist_state: bool,
    preview_id: Option<String>,
    ephemeral_projection: bool,
) -> Result<SceneApplyResponse> {
    let scene_transaction_lock = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.scene_lifecycle_transaction_lock.clone()
    };
    let _scene_transaction = scene_transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("Failed to lock scene lifecycle transaction"))?;
    let mut scene = match source {
        SceneApplySource::Stored(scene_id) => {
            let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            s.scenes
                .get(&scene_id)
                .cloned()
                .ok_or_else(|| anyhow::anyhow!("Scene '{}' not found", scene_id))?
        }
        SceneApplySource::Definition(scene) => scene,
    };
    scene.normalize();
    let target_id = resolve_node_id(state, &request.target_id);
    let transaction_lock = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.external_topology_transaction_lock.clone()
    };
    let transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("Failed to lock external topology transaction"))?;
    let (runtime, plan, managed_dispatches) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let runtime = s
            .hub_runtime()
            .ok_or_else(|| anyhow::anyhow!("No runtime available"))?;
        let (scope_node_ids, rendered) =
            render_scene_lights_locked(&s, &runtime, &scene, &target_id, request.transition_ms)?;
        if scope_node_ids.is_empty() {
            anyhow::bail!(
                "Target '{}' has no light scene-addressable nodes",
                target_id
            );
        }
        let managed_dispatches =
            managed_scene_dispatches_locked(&s, &scene, &scope_node_ids, &rendered)?;
        let plan = if managed_dispatches.is_empty() {
            build_scene_application_plan_locked(
                &s,
                &runtime,
                &scene,
                &target_id,
                request.transition_ms,
            )?
        } else {
            companion_scene_plan_locked(&s, &rendered, &managed_dispatches)?
        };
        (runtime, plan, managed_dispatches)
    };

    for managed in &managed_dispatches {
        let handled = managed.discovery.apply_managed_scene_projection(
            &managed.projection,
            managed.transition_ms,
            ephemeral_projection,
        )?;
        if !handled {
            anyhow::bail!("An authoritative controller does not support managed room scenes");
        }
        for (node_id, lights_on) in &managed.projected_states {
            update_lights_on_cache_for_runtime_node(state, &runtime, node_id, *lights_on);
            emit_node_state_event_after_apply(state, &runtime, node_id);
        }
    }
    if plan.affected_node_ids.is_empty() {
        anyhow::bail!(
            "Scene '{}' has no routable light entries for target '{}'",
            scene.id,
            target_id
        );
    }
    // Planning and native scene projection must observe one serialized
    // topology snapshot. Ordinary dispatch is different: external
    // controllers acquire this same lock around their own operation, so
    // retaining the outer guard here would self-deadlock roomless Hue and the
    // companion leg of mixed Hue rooms. The scene lifecycle guard remains held
    // through dispatch and committed state so upsert/delete cannot interleave.
    drop(transaction);
    dispatch_scene_plan(state, &runtime, &plan)?;

    if commit_state {
        set_scene_committed_state(
            state,
            &runtime,
            &scene.id,
            &target_id,
            &plan.affected_node_ids,
        );
        if let Ok(mut s) = state.lock() {
            clear_scene_preview_sessions_locked(&mut s, &target_id, &plan.affected_node_ids);
        }
        if persist_state {
            persist_rooms(state);
        }
    }

    Ok(SceneApplyResponse {
        scene_id: scene.id,
        target_id,
        affected_node_ids: plan.affected_node_ids,
        unresolved_node_ids: plan.unresolved_node_ids,
        preview_id,
    })
}

fn do_scene_apply_inner(
    state: &SharedState,
    scene_id: &str,
    request: SceneApplyRequest,
    commit_state: bool,
    persist_state: bool,
    preview_id: Option<String>,
) -> Result<SceneApplyResponse> {
    do_scene_apply_definition_inner(
        state,
        SceneApplySource::Stored(scene_id.to_string()),
        request,
        commit_state,
        persist_state,
        preview_id,
        false,
    )
}

pub fn build_scenes(state: &SharedState) -> Result<String> {
    build_scenes_for_target(state, None)
}

fn scene_sources_for_target(
    s: &AppState,
    target_id: &str,
) -> Vec<(HubKey, String, Arc<dyn HubDiscovery>)> {
    let room_id = if s.topology.get(target_id).is_some() {
        Some(target_id)
    } else {
        s.topology.device_parent_room_id(target_id)
    };
    let Some(room) = room_id.and_then(|room_id| s.topology.get(room_id)) else {
        return Vec::new();
    };

    room.hub_room_bindings
        .iter()
        .filter_map(|binding| {
            let discovery = s
                .hubs
                .get(&binding.hub_key)
                .and_then(|hub| hub.discovery.clone())?;
            Some((
                binding.hub_key.clone(),
                binding.hub_room_id.clone(),
                discovery,
            ))
        })
        .collect()
}

pub fn build_scenes_for_target(state: &SharedState, target_id: Option<&str>) -> Result<String> {
    let (mut scenes, sources) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let scenes = s.scenes.values().cloned().collect::<Vec<_>>();
        let sources = target_id
            .map(|target_id| scene_sources_for_target(&s, target_id))
            .unwrap_or_default();
        (scenes, sources)
    };

    let mut known_ids: HashSet<String> = scenes.iter().map(|scene| scene.id.clone()).collect();
    let mut native_discovery_failed = false;
    for (hub_key, hub_room_id, discovery) in sources {
        match discovery.discover_scenes(&hub_room_id) {
            Ok(discovered) => {
                for scene in discovered {
                    if known_ids.insert(scene.id.clone()) {
                        scenes.push(scene);
                    }
                }
            }
            Err(error) => {
                native_discovery_failed = true;
                warn!(
                    target: "native_scenes",
                    "Failed to discover scenes for target={} hub={} room={}: {}",
                    target_id.unwrap_or_default(),
                    hub_key,
                    hub_room_id,
                    error
                );
            }
        }
    }

    serde_json::to_string(&serde_json::json!({
        "scenes": scenes,
        "native_discovery_failed": native_discovery_failed
    }))
    .map_err(|e| anyhow::anyhow!("serialize scenes: {}", e))
}

fn validate_persisted_scene_id(scene_id: &str) -> Result<()> {
    if is_native_scene_id(scene_id) {
        return Err(anyhow::anyhow!(
            "Scene id '{}' uses the reserved native scene namespace",
            scene_id
        ));
    }
    Ok(())
}

pub fn do_scene_upsert(state: &SharedState, mut scene: SceneDefinition) -> Result<String> {
    scene.normalize();
    validate_persisted_scene_id(&scene.id)?;
    let scene_transaction_lock = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.scene_lifecycle_transaction_lock.clone()
    };
    let _scene_transaction = scene_transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("Failed to lock scene lifecycle transaction"))?;
    let response_scene = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let previous = s.scenes.insert(scene.id.clone(), scene.clone());
        if let Err(error) = save_scenes_locked(&s) {
            match previous {
                Some(previous) => {
                    s.scenes.insert(scene.id.clone(), previous);
                }
                None => {
                    s.scenes.remove(&scene.id);
                }
            }
            return Err(error.context("Failed to durably save the scene"));
        }
        scene
    };
    crate::state::emit_server_event(state, crate::server_event::ServerEvent::ConfigChanged);
    serde_json::to_string(&response_scene).map_err(|e| anyhow::anyhow!("serialize scene: {}", e))
}

pub fn do_scene_delete(state: &SharedState, scene_id: &str) -> Result<String> {
    let scene_transaction_lock = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.scene_lifecycle_transaction_lock.clone()
    };
    let _scene_transaction = scene_transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("Failed to lock scene lifecycle transaction"))?;
    let transaction_lock = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.external_topology_transaction_lock.clone()
    };
    let transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("Failed to lock external topology transaction"))?;
    let discoveries = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if !s.scenes.contains_key(scene_id) {
            return Err(anyhow::anyhow!("Scene '{}' not found", scene_id));
        }
        let mut hubs = Vec::<HubKey>::new();
        for binding in s
            .topology
            .rooms()
            .flat_map(|room| room.hub_room_bindings.iter())
        {
            if !s
                .topology
                .grouped_room_control_is_required(&binding.hub_key)
                || hubs.iter().any(|hub_key| hub_key == &binding.hub_key)
            {
                continue;
            }
            hubs.push(binding.hub_key.clone());
        }
        let mut discoveries = Vec::with_capacity(hubs.len());
        for hub_key in hubs {
            if !s.external_controller_authority_is_ready(&hub_key) {
                anyhow::bail!("An authoritative grouped controller is not ready");
            }
            let discovery = s
                .hubs
                .get(&hub_key)
                .and_then(|hub| hub.discovery.clone())
                .ok_or_else(|| anyhow::anyhow!("An authoritative controller is unavailable"))?;
            discoveries.push(discovery);
        }
        discoveries
    };
    for discovery in discoveries {
        if !discovery.delete_managed_scene_projection(scene_id)? {
            anyhow::bail!("An authoritative controller does not support managed room scenes");
        }
    }

    let runtime = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let removed = s
            .scenes
            .remove(scene_id)
            .ok_or_else(|| anyhow::anyhow!("Scene '{}' not found", scene_id))?;
        let previews_before = s.light_scene_previews.clone();
        s.light_scene_previews
            .retain(|_, preview| preview.scene_id != scene_id);
        if let Err(error) = save_scenes_locked(&s) {
            s.scenes.insert(scene_id.to_string(), removed);
            s.light_scene_previews = previews_before;
            return Err(error.context("Failed to durably delete the scene"));
        }
        s.hub_runtime()
    };

    // Managed-scene deletion and the matching local definition update must be
    // serialized with topology changes. Runtime output is different: an
    // external light controller acquires this same non-reentrant lock around
    // its physical command, so release the outer transaction before restoring
    // nodes that had the deleted mood scene selected.
    drop(transaction);

    if let Some(runtime) = runtime {
        for snap in runtime.engine_all_node_snapshots() {
            if snap.profile_settings.mood_scene_id.as_deref() != Some(scene_id) {
                continue;
            }
            let mut profile_settings = snap.profile_settings.clone();
            profile_settings.mood_scene_id = None;
            runtime.restore_node_state(
                &snap.id,
                RestoredNodeState {
                    rhythm_enabled: snap.rhythm_enabled,
                    disabled: snap.disabled,
                    time_offset_minutes: snap.time_offset_minutes,
                    brightness_offset: snap.brightness_offset,
                    soft_off: false,
                    mood_active: false,
                    standby_enabled: snap.standby_enabled,
                    hard_off: false,
                    profile_settings,
                },
            );
            let _ = runtime.turn_on_room(&snap.id);
            update_lights_on_cache_for_runtime_node(state, &runtime, &snap.id, true);
            emit_node_state_event_after_apply(state, &runtime, &snap.id);
        }
        persist_rooms(state);
    }

    crate::state::emit_server_event(state, crate::server_event::ServerEvent::ConfigChanged);
    build_scenes(state)
}

pub fn do_scene_apply(
    state: &SharedState,
    scene_id: &str,
    request: SceneApplyRequest,
) -> Result<String> {
    let response = do_scene_apply_response(state, scene_id, request, true)?;
    serde_json::to_string(&response).map_err(|e| anyhow::anyhow!("serialize scene apply: {}", e))
}

fn do_scene_apply_response(
    state: &SharedState,
    scene_id: &str,
    request: SceneApplyRequest,
    persist_state: bool,
) -> Result<SceneApplyResponse> {
    let is_stored = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.scenes.contains_key(scene_id)
    };
    if is_stored {
        return do_scene_apply_inner(state, scene_id, request, true, persist_state, None);
    }
    if is_native_scene_id(scene_id) {
        return do_native_scene_apply(state, scene_id, request, persist_state);
    }
    Err(anyhow::anyhow!("Scene '{}' not found", scene_id))
}

fn do_native_scene_apply(
    state: &SharedState,
    scene_id: &str,
    request: SceneApplyRequest,
    persist_state: bool,
) -> Result<SceneApplyResponse> {
    let target_id = resolve_node_id(state, &request.target_id);
    let sources = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        scene_sources_for_target(&s, &target_id)
    };
    let mut discovery_errors = Vec::new();

    for (hub_key, hub_room_id, discovery) in sources {
        let scenes = match discovery.discover_scenes(&hub_room_id) {
            Ok(scenes) => scenes,
            Err(error) => {
                discovery_errors.push(format!("hub {} room {}: {}", hub_key, hub_room_id, error));
                continue;
            }
        };
        let Some(scene) = scenes.into_iter().find(|scene| scene.id == scene_id) else {
            continue;
        };
        let external_id = match &scene.source {
            SceneSource::Imported {
                external_id: Some(external_id),
                ..
            } => external_id.as_str(),
            _ => {
                return Err(anyhow::anyhow!(
                    "Native scene '{}' has no external scene identity",
                    scene_id
                ));
            }
        };

        let (runtime, mut affected_node_ids, companion_plan) = {
            let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            let runtime = s
                .hub_runtime()
                .ok_or_else(|| anyhow::anyhow!("No runtime available"))?;
            let affected: Vec<String> = light_scene_target_scope_node_ids(&s, &runtime, &target_id)
                .into_iter()
                .collect();
            let companion_plan = build_native_scene_companion_plan_locked(
                &s,
                &runtime,
                &scene,
                &target_id,
                request.transition_ms,
            )?;
            (runtime, affected, companion_plan)
        };
        if affected_node_ids.is_empty() {
            affected_node_ids.push(target_id.clone());
        }
        discovery
            .recall_scene(external_id, request.transition_ms)
            .map_err(|error| {
                anyhow::anyhow!(
                    "Failed to recall native scene '{}' on hub {}: {}",
                    scene_id,
                    hub_key,
                    error
                )
            })?;
        let mut unresolved_node_ids = Vec::new();
        if let Some(plan) = companion_plan {
            dispatch_scene_plan(state, &runtime, &plan)?;
            unresolved_node_ids = plan.unresolved_node_ids;
        }

        set_scene_committed_state(state, &runtime, scene_id, &target_id, &affected_node_ids);
        if let Ok(mut s) = state.lock() {
            clear_scene_preview_sessions_locked(&mut s, &target_id, &affected_node_ids);
        }
        if persist_state {
            persist_rooms(state);
        }
        emit_node_state_event_after_apply(state, &runtime, &target_id);
        info!(
            target: "native_scenes",
            "Recalled native scene target={} hub={} room={} scene={}",
            target_id,
            hub_key,
            hub_room_id,
            scene_id
        );
        return Ok(SceneApplyResponse {
            scene_id: scene_id.to_string(),
            target_id,
            affected_node_ids,
            unresolved_node_ids,
            preview_id: None,
        });
    }

    if !discovery_errors.is_empty() {
        return Err(anyhow::anyhow!(
            "Scene '{}' could not be resolved because native discovery failed: {}",
            scene_id,
            discovery_errors.join("; ")
        ));
    }
    Err(anyhow::anyhow!("Scene '{}' not found", scene_id))
}

/// Build individual companion commands for bulbs whose topology explicitly
/// supports device dispatch. Hue devices are intentionally excluded because
/// their attached route collapses to the grouped room recall above.
fn build_native_scene_companion_plan_locked(
    s: &AppState,
    runtime: &Arc<dyn RuntimeHandle>,
    scene: &SceneDefinition,
    target_id: &str,
    transition_ms: Option<u32>,
) -> Result<Option<SceneApplicationPlan>> {
    if !matches!(
        &scene.source,
        SceneSource::Imported { provider, .. } if provider.eq_ignore_ascii_case("hue")
    ) {
        return Ok(None);
    }
    let Some(layer) = scene.light.as_ref() else {
        return Ok(None);
    };
    let companion_node_ids: Vec<_> = light_scene_target_scope_node_ids(s, runtime, target_id)
        .into_iter()
        .filter(|node_id| {
            s.topology
                .light_node_uses_device_dispatch(node_id, &s.canonical_registry)
        })
        .collect();
    if companion_node_ids.is_empty() {
        return Ok(None);
    }

    let mut commands = Vec::new();
    let mut unresolved_node_ids = Vec::new();
    for (index, node_id) in companion_node_ids.iter().enumerate() {
        let output = if layer.palette.is_empty() {
            layer.default_output.as_ref()
        } else {
            Some(&layer.palette[index % layer.palette.len()])
        };
        let Some(output) = output else {
            continue;
        };
        push_scene_light_command(
            s,
            layer.default_transition_ms,
            transition_ms,
            node_id,
            output,
            &mut commands,
            &mut unresolved_node_ids,
        )?;
    }
    if commands.is_empty() {
        return Ok(None);
    }
    commands.sort_by(|left, right| left.public_node_id.cmp(&right.public_node_id));
    unresolved_node_ids.sort();
    unresolved_node_ids.dedup();

    Ok(Some(SceneApplicationPlan {
        affected_node_ids: commands
            .iter()
            .map(|command| command.public_node_id.clone())
            .collect(),
        commands,
        unresolved_node_ids,
    }))
}

fn record_scene_preview_session(
    state: &SharedState,
    preview_id: String,
    target_id: String,
    response: &SceneApplyResponse,
    duration_ms: Option<u64>,
    draft_scene: Option<SceneDefinition>,
) -> Result<()> {
    let previous_mood_scene_id = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.hub_runtime()
            .and_then(|runtime| runtime.engine_effective_node_snapshot(&target_id))
            .and_then(|snap| snap.profile_settings.mood_scene_id)
    };
    let now = current_epoch_ms();
    let duration_ms = duration_ms
        .unwrap_or(DEFAULT_LIGHT_SCENE_PREVIEW_MS)
        .clamp(1_000, 10 * 60_000);
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    clear_scene_preview_sessions_locked(&mut s, &target_id, &response.affected_node_ids);
    s.light_scene_previews.insert(
        preview_id.clone(),
        LightScenePreviewSession {
            id: preview_id,
            scene_id: response.scene_id.clone(),
            target_node_id: target_id,
            affected_node_ids: response.affected_node_ids.clone(),
            previous_mood_scene_id,
            draft_scene,
            started_at_epoch_ms: now,
            expires_at_epoch_ms: now.saturating_add(duration_ms),
        },
    );
    Ok(())
}

pub fn do_scene_preview(
    state: &SharedState,
    scene_id: &str,
    request: ScenePreviewRequest,
) -> Result<String> {
    let preview_id = crate::canonical::identity::generate_uuid_public();
    let target_id = resolve_node_id(state, &request.target_id);
    let apply_request = SceneApplyRequest {
        target_id: target_id.clone(),
        transition_ms: request.transition_ms,
    };
    let response = do_scene_apply_inner(
        state,
        scene_id,
        apply_request,
        false,
        false,
        Some(preview_id.clone()),
    )?;
    record_scene_preview_session(
        state,
        preview_id,
        target_id,
        &response,
        request.duration_ms,
        None,
    )?;

    serde_json::to_string(&response).map_err(|e| anyhow::anyhow!("serialize scene preview: {}", e))
}

pub fn do_scene_draft_preview(
    state: &SharedState,
    request: SceneDraftPreviewRequest,
) -> Result<String> {
    let preview_id = crate::canonical::identity::generate_uuid_public();
    let target_id = resolve_node_id(state, &request.target_id);
    let mut scene = request.scene;
    scene.normalize();
    let apply_request = SceneApplyRequest {
        target_id: target_id.clone(),
        transition_ms: request.transition_ms,
    };
    let response = do_scene_apply_definition_inner(
        state,
        SceneApplySource::Definition(scene.clone()),
        apply_request,
        false,
        false,
        Some(preview_id.clone()),
        true,
    )?;
    record_scene_preview_session(
        state,
        preview_id,
        target_id,
        &response,
        request.duration_ms,
        Some(scene),
    )?;

    serde_json::to_string(&response)
        .map_err(|e| anyhow::anyhow!("serialize scene draft preview: {}", e))
}

pub fn do_scene_preview_commit(state: &SharedState, preview_id: &str) -> Result<String> {
    let preview = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.light_scene_previews
            .get(preview_id)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("Scene preview '{}' not found", preview_id))?
    };
    if let Some(mut draft_scene) = preview.draft_scene.clone() {
        draft_scene.normalize();
        validate_persisted_scene_id(&draft_scene.id)?;
        do_scene_upsert(state, draft_scene)?;
    }
    do_scene_apply(
        state,
        &preview.scene_id,
        SceneApplyRequest {
            target_id: preview.target_node_id,
            transition_ms: None,
        },
    )
}

pub fn do_scene_preview_cancel(state: &SharedState, preview_id: &str) -> Result<String> {
    let preview = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.light_scene_previews
            .remove(preview_id)
            .ok_or_else(|| anyhow::anyhow!("Scene preview '{}' not found", preview_id))?
    };

    if let Some(previous_scene_id) = preview.previous_mood_scene_id.clone() {
        if state
            .lock()
            .ok()
            .is_some_and(|s| s.scenes.contains_key(&previous_scene_id))
        {
            let _ = do_scene_apply_inner(
                state,
                &previous_scene_id,
                SceneApplyRequest {
                    target_id: preview.target_node_id.clone(),
                    transition_ms: None,
                },
                false,
                false,
                None,
            );
        }
    } else if let Some(runtime) = state.lock().ok().and_then(|s| s.hub_runtime()) {
        if let Some(snap) = runtime.engine_effective_node_snapshot(&preview.target_node_id) {
            let result = if snap.hard_off {
                runtime.lights_off_room(&preview.target_node_id, None)
            } else if snap.soft_off {
                runtime.soft_off_tick_room(&preview.target_node_id)
            } else if snap.mood_active {
                apply_mood_scene_or_tick(
                    state,
                    &runtime,
                    &preview.target_node_id,
                    snap.profile_settings.mood_scene_id.as_deref(),
                    false,
                )
            } else {
                runtime.turn_on_room(&preview.target_node_id)
            };
            if let Err(e) = result {
                warn!(
                    target: "cmd",
                    "scene_preview_cancel: failed to restore '{}': {}",
                    preview.target_node_id,
                    e
                );
            }
            update_lights_on_cache_for_runtime_node(state, &runtime, &preview.target_node_id, true);
            emit_node_state_event_after_apply(state, &runtime, &preview.target_node_id);
        }
    }

    serde_json::to_string(&serde_json::json!({
        "preview_id": preview.id,
        "cancelled": true
    }))
    .map_err(|e| anyhow::anyhow!("serialize scene preview cancel: {}", e))
}

fn apply_mood_scene_or_tick(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    node_id: &str,
    mood_scene_id: Option<&str>,
    persist_state: bool,
) -> Result<()> {
    if let Some(scene_id) = mood_scene_id {
        do_scene_apply_response(
            state,
            scene_id,
            SceneApplyRequest {
                target_id: node_id.to_string(),
                transition_ms: None,
            },
            persist_state,
        )?;
        return Ok(());
    }

    runtime.mood_tick_room(node_id)
}

fn apply_parent_room_output_to_light(
    state: &SharedState,
    device_id: &str,
    room_id: &str,
) -> Result<()> {
    let Some(runtime) = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .hub_runtime()
    else {
        return Ok(());
    };
    let Some(room) = runtime.engine_effective_node_snapshot(room_id) else {
        warn!(
            target: "cmd",
            "Skipping moved-light output refresh because destination room '{}' is not in the runtime",
            room_id
        );
        return Ok(());
    };

    if room.hard_off {
        runtime.lights_off_room(device_id, None)
    } else if room.soft_off {
        runtime.soft_off_tick_room(device_id)
    } else if room.mood_active {
        apply_mood_scene_or_tick(
            state,
            &runtime,
            device_id,
            room.profile_settings.mood_scene_id.as_deref(),
            false,
        )
    } else {
        runtime.turn_on_room(device_id)
    }
}

fn source_room_manager_for_export(state: &SharedState) -> rhythm_core::RoomManager {
    let runtime = state.lock().ok().and_then(|s| s.hub_runtime());
    let source = if let Some(runtime) = runtime {
        rooms_from_engine(runtime.as_ref())
    } else {
        let Ok(s) = state.lock() else {
            return rhythm_core::RoomManager::default();
        };

        s.storage
            .as_ref()
            .and_then(|storage| storage.load_rooms().ok())
            .unwrap_or_default()
    };

    source
}

fn topology_node_snapshots_from_state(state: &SharedState) -> Vec<rhythm_core::NodeSnapshot> {
    let Ok(s) = state.lock() else {
        return Vec::new();
    };

    let mut nodes = Vec::new();

    let mut room_ids: Vec<_> = s.topology.rooms().map(|room| room.id.clone()).collect();
    room_ids.sort();
    for room_id in room_ids {
        let Some(room) = s.topology.get(&room_id) else {
            continue;
        };
        nodes.push(rhythm_core::NodeSnapshot {
            id: room.id.clone(),
            name: room.name.clone(),
            kind: LightNodeKind::Room,
            parent_id: None,
            rhythm_enabled: true,
            disabled: false,
            time_offset_minutes: 0.0,
            brightness_offset: 0.0,
            soft_off: false,
            mood_active: false,
            standby_enabled: false,
            hard_off: false,
            profile_settings: RoomProfileSettings::default(),
        });
    }

    let mut device_node_ids: Vec<_> = s
        .topology
        .device_nodes()
        .map(|node| node.id.clone())
        .collect();
    device_node_ids.sort();
    for node_id in device_node_ids {
        let Some(node) = s.topology.get_device_node(&node_id) else {
            continue;
        };
        if canonical_device_is_quarantined(&s, &node.canonical_device_id) {
            continue;
        }
        let (name, kind) = s
            .canonical_registry
            .get(&node.canonical_device_id)
            .map(|device| {
                (
                    device.name.clone(),
                    runtime_node_kind_for_device_type(device.device_type.clone()),
                )
            })
            .unwrap_or_else(|| (node.id.clone(), LightNodeKind::OtherDevice));

        nodes.push(rhythm_core::NodeSnapshot {
            id: node.id.clone(),
            name,
            kind,
            parent_id: node.parent_id.clone(),
            rhythm_enabled: kind.is_light_addressable(),
            disabled: false,
            time_offset_minutes: 0.0,
            brightness_offset: 0.0,
            soft_off: false,
            mood_active: false,
            standby_enabled: false,
            hard_off: false,
            profile_settings: RoomProfileSettings::default(),
        });
    }

    nodes
}

fn bootstrap_node_snapshots_from_state(state: &SharedState) -> Vec<rhythm_core::NodeSnapshot> {
    let mut snapshots = topology_node_snapshots_from_state(state);
    if snapshots.is_empty() {
        snapshots = registry_node_snapshots_from_state(state);
    }
    snapshots
}

fn registry_node_snapshots_from_state(state: &SharedState) -> Vec<rhythm_core::NodeSnapshot> {
    let (registries, topo_map) = {
        let Ok(s) = state.lock() else {
            return Vec::new();
        };
        let topo_map: HashMap<String, (String, String)> = s
            .topology
            .rooms()
            .flat_map(|room| {
                room.hub_room_bindings.iter().map(move |binding| {
                    (
                        binding.hub_room_id.clone(),
                        (room.id.clone(), room.name.clone()),
                    )
                })
            })
            .collect();
        (s.all_hub_registries(), topo_map)
    };

    let mut seen = HashSet::new();
    let mut nodes = Vec::new();
    for reg in registries {
        let Ok(reg) = reg.lock() else {
            continue;
        };
        for room in reg.rooms() {
            let (id, name) = topo_map
                .get(&room.id)
                .cloned()
                .unwrap_or_else(|| (room.id.clone(), room.name.clone()));
            if !seen.insert(id.clone()) {
                continue;
            }
            nodes.push(rhythm_core::NodeSnapshot {
                id,
                name,
                kind: LightNodeKind::Room,
                parent_id: None,
                rhythm_enabled: false,
                disabled: false,
                time_offset_minutes: 0.0,
                brightness_offset: 0.0,
                soft_off: false,
                mood_active: false,
                standby_enabled: false,
                hard_off: false,
                profile_settings: RoomProfileSettings::default(),
            });
        }
    }
    nodes.sort_by(|left, right| left.id.cmp(&right.id));
    nodes
}

fn room_manager_for_export(state: &SharedState) -> rhythm_core::RoomManager {
    let source = source_room_manager_for_export(state);
    let Ok(s) = state.lock() else {
        return source;
    };
    if s.topology.room_count() == 0 && s.topology.device_nodes().next().is_none() {
        return source;
    }

    let mut merged = rhythm_core::RoomManager::default();

    let mut topology_room_ids: Vec<_> = s.topology.rooms().map(|room| room.id.clone()).collect();
    topology_room_ids.sort();
    for room_id in topology_room_ids {
        let topology_room = s.topology.get(&room_id).unwrap();
        let mut room = source
            .get(&room_id)
            .cloned()
            .unwrap_or_else(|| rhythm_core::Room::new(&topology_room.id, &topology_room.name));
        room.name = topology_room.name.clone();
        room.kind = LightNodeKind::Room;
        room.parent_id = None;
        merged.add_room(room);
    }

    let mut device_node_ids: Vec<_> = s
        .topology
        .device_nodes()
        .map(|node| node.id.clone())
        .collect();
    device_node_ids.sort();
    for node_id in device_node_ids {
        let topology_node = s.topology.get_device_node(&node_id).unwrap();
        let mut room = source.get(&node_id).cloned().unwrap_or_else(|| {
            let (name, kind) = s
                .canonical_registry
                .get(&topology_node.canonical_device_id)
                .map(|device| {
                    (
                        device.name.clone(),
                        runtime_node_kind_for_device_type(device.device_type.clone()),
                    )
                })
                .unwrap_or_else(|| (topology_node.id.clone(), LightNodeKind::OtherDevice));
            let mut node = rhythm_core::Room::new_node(
                &topology_node.id,
                name,
                kind,
                topology_node.parent_id.clone(),
            );
            if !node.kind.is_room() {
                node.rhythm_enabled = true;
            }
            node
        });
        room.parent_id = topology_node.parent_id.clone();
        if let Some(device) = s.canonical_registry.get(&topology_node.canonical_device_id) {
            room.name = device.name.clone();
            room.kind = runtime_node_kind_for_device_type(device.device_type.clone());
        } else {
            room.name = topology_node.id.clone();
            room.kind = LightNodeKind::OtherDevice;
        }
        merged.add_room(room);
    }

    merged
}

fn profile_bundle_data_from_state(s: &AppState) -> ProfileBundleData {
    ProfileBundleData {
        power_save: s.power_save,
        profiles: s.light_profile_configs.values().cloned().collect(),
        scenes: s.scenes.values().cloned().collect(),
        mode_transitions: s.mode_transition_configs(),
    }
}

fn backup_configuration_from_parts(
    s: &AppState,
    room_manager: &rhythm_core::RoomManager,
) -> BackupConfiguration {
    let mut rooms: Vec<_> = room_manager
        .iter()
        .filter(|room| room.kind.is_room())
        .map(BackupConfigurationRoom::from)
        .collect();
    rooms.sort_by(|left, right| left.id.cmp(&right.id).then(left.name.cmp(&right.name)));

    BackupConfiguration {
        power_save: s.power_save,
        light_breaker_enabled: s.light_breaker_enabled,
        active_mode: s.active_mode,
        profiles: s.light_profile_configs.values().cloned().collect(),
        mode_configs: s.mode_configs(),
        mode_transitions: s.mode_transition_configs(),
        scenes: s.scenes.values().cloned().collect(),
        rooms,
    }
}

fn stored_location_from_state(s: &AppState) -> Option<StoredLocation> {
    let has_location = s.latitude.is_some()
        || s.longitude.is_some()
        || s.timezone_name.is_some()
        || s.utc_offset_hours.abs() > f32::EPSILON;
    has_location.then(|| StoredLocation {
        latitude: s.latitude,
        longitude: s.longitude,
        utc_offset_hours: s.utc_offset_hours,
        timezone_name: s.timezone_name.clone(),
    })
}

fn backup_hub_credentials_from_state(
    creds: &crate::hub::HubCredentials,
    include_secrets: bool,
) -> BackupHubCredentials {
    BackupHubCredentials {
        hub_type: creds.hub_type.clone(),
        address: creds.address.clone(),
        data: (include_secrets && !creds.secrets_redacted).then(|| creds.data.clone()),
    }
}

/// Appliance-local BLE associations cannot be restored safely on another
/// adapter, so portable backups omit their credentials, endpoints, and nodes.
/// A canonical device that also has another endpoint remains in the backup.
fn is_nonportable_local_ble(hub_type: &str) -> bool {
    matches!(hub_type, HubType::HUE_BLE | HubType::LOCAL_BLE)
}

fn strip_nonportable_local_ble_nodes(
    rooms: &mut rhythm_core::RoomManager,
    topology: &mut crate::topology::RoomTopologyStore,
    canonical_registry: &mut crate::canonical::registry::CanonicalRegistry,
) {
    let endpoints = canonical_registry
        .devices()
        .flat_map(|device| {
            device
                .endpoints
                .iter()
                .filter(|endpoint| is_nonportable_local_ble(endpoint.hub_key.hub_type.as_str()))
                .map(|endpoint| (endpoint.hub_key.clone(), endpoint.native_id.clone()))
        })
        .collect::<Vec<_>>();
    let mut removed_devices = Vec::new();
    for (hub_key, native_id) in endpoints {
        if let Some((canonical_id, true)) = canonical_registry.remove_endpoint(&hub_key, &native_id)
        {
            removed_devices.push(canonical_id);
        }
    }
    for canonical_id in removed_devices {
        topology.remove_input_bindings_for_source(&canonical_id);
        topology.remove_device_everywhere(&canonical_id);
        rooms.remove(&canonical_id);
    }
}

fn sanitize_nonportable_backup_installation(installation: &mut BackupInstallation) {
    strip_nonportable_local_ble_nodes(
        &mut installation.rooms,
        &mut installation.topology,
        &mut installation.canonical_registry,
    );
    installation.hub_credentials.retain(|credential| {
        credential
            .hub_type
            .as_ref()
            .is_none_or(|hub_type| !is_nonportable_local_ble(hub_type.as_str()))
    });
    installation
        .hub_registries
        .retain(|registry| !is_nonportable_local_ble(registry.hub_key.hub_type.as_str()));
    installation
        .integration_files
        .retain(|file| !file.path.starts_with("hue_ble/") && !file.path.starts_with("local_ble/"));
}

fn migrate_legacy_backup_external_room_automation_policy(installation: &mut BackupInstallation) {
    let configured_hub_keys = installation
        .hub_credentials
        .iter()
        .filter_map(|credential| {
            credential
                .hub_type
                .as_ref()
                .map(|hub_type| HubKey::new(hub_type.clone(), credential.address.clone()))
        })
        .collect::<Vec<_>>();
    let migration = installation
        .topology
        .migrate_legacy_external_room_automation_policy(&configured_hub_keys);
    if migration.changed() {
        info!(
            target: "cmd",
            "Migrated legacy backup Hue room automation policy: grandfathered_hue_rooms={}",
            migration.grandfathered_hue_rooms
        );
    }
}

pub fn build_profile_bundle_dto(state: &SharedState) -> Result<ProfileBundle> {
    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;

    Ok(ProfileBundle {
        schema_version: PROFILE_BUNDLE_SCHEMA_VERSION,
        kind: crate::bundle::BundleKind::ProfileBundle,
        name: None,
        description: None,
        profile: profile_bundle_data_from_state(&s),
    })
}

pub fn build_profile_bundle(state: &SharedState) -> Result<String> {
    let bundle = build_profile_bundle_dto(state)?;
    serialize_profile_bundle(&bundle)
}

fn serialize_profile_bundle(bundle: &ProfileBundle) -> Result<String> {
    serde_json::to_string_pretty(bundle)
        .map_err(|e| anyhow::anyhow!("serialize profile bundle: {}", e))
}

pub fn build_factory_default_profile_bundle_dto() -> ProfileBundle {
    factory_default_profile_bundle()
}

pub fn build_factory_default_profile_bundle() -> Result<String> {
    serialize_profile_bundle(&build_factory_default_profile_bundle_dto())
}

fn clear_factory_reset_storage(state: &SharedState) -> Result<()> {
    crate::pairing::clear_persisted_state_for_factory_reset(state)
}

fn clear_factory_reset_ephemeral_state(state: &SharedState) -> Result<()> {
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    s.hub_connection_status.clear();
    s.hub_seen_connected_once.clear();
    s.hub_sync_in_progress.clear();
    s.hub_reconnect_sync_at.clear();
    s.hub_pending_disconnect_at.clear();
    s.room_observed_power.clear();
    s.motion_snapshots.clear();
    s.room_mode_transitions.clear();
    s.last_check_hour = None;
    s.last_check_instant = None;
    s.last_check_utc_offset_hours = None;
    s.api_auth = crate::auth::StoredApiAuth::default();
    s.invalidate_queued_light_dispatches();
    s.pending_hub_event_rxs.clear();
    s.pending_motion_clear.clear();
    s.pending_motion_seed.clear();
    s.last_tick_epoch_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64;
    Ok(())
}

fn factory_default_backup_configuration() -> BackupConfiguration {
    BackupConfiguration {
        power_save: factory_default_power_save(),
        light_breaker_enabled: true,
        active_mode: factory_default_active_mode(),
        profiles: factory_default_light_profile_config_map()
            .into_values()
            .collect(),
        mode_configs: factory_default_mode_config_map().into_values().collect(),
        mode_transitions: factory_default_mode_transition_configs(),
        scenes: factory_default_scene_map().into_values().collect(),
        rooms: Vec::new(),
    }
}

#[derive(Debug)]
struct FactoryResetPostBarrierError {
    source: anyhow::Error,
}

impl fmt::Display for FactoryResetPostBarrierError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "factory reset failed after the safety barrier completed: {:#}",
            self.source
        )
    }
}

impl std::error::Error for FactoryResetPostBarrierError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(self.source.as_ref())
    }
}

pub(crate) fn factory_reset_error_is_post_barrier(error: &anyhow::Error) -> bool {
    error
        .downcast_ref::<FactoryResetPostBarrierError>()
        .is_some()
}

pub fn do_factory_reset(state: &SharedState) -> Result<String> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    // Releasing an authoritative external controller is itself a safety
    // prerequisite for reset. The platform barrier may scrub peripheral
    // trust or stage other irreversible local work, so Hue recovery preflight,
    // controller release, and the fail-closed policy tombstone must all
    // complete while credentials and controller recovery material are intact.
    preflight_current_hue_recovery_state(state, HueRecoveryPreflightMode::ControllerRelease)
        .context("factory reset Hue recovery preflight failed")?;
    let release_keys = configured_or_active_hub_keys(state)?;
    prepare_external_controller_release(
        state,
        &release_keys,
        crate::hub::ExternalControllerReleaseReason::FactoryReset,
    )
    .context("releasing external controller authority before factory reset")?;
    let policy_keys = external_room_automation_policy_keys_for_disconnect(state, &release_keys)?;
    durably_forget_external_room_automation_policy(
        state,
        &policy_keys,
        crate::hub::ExternalControllerReleaseReason::FactoryReset,
    )?;

    if let Some(callback) = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .before_factory_reset_fn
        .clone()
    {
        callback(state).context("preparing platform for factory reset")?;
    }
    // The platform safety barrier runs before credentials or hub state are
    // destroyed. In particular, an appliance may need live hub metadata and
    // credentials to release peripheral-held Bluetooth trust. A failed barrier
    // therefore remains retryable, with room automation intentionally kept
    // fail-closed after the external controller was restored.
    (|| {
        disconnect_hubs_after_external_controller_release(state)?;
        clear_factory_reset_storage(state)?;
        clear_factory_reset_ephemeral_state(state)?;

        let installation = BackupInstallation {
            location: None,
            rooms: rhythm_core::RoomManager::new(),
            topology: crate::topology::RoomTopologyStore::new(),
            canonical_registry: crate::canonical::registry::CanonicalRegistry::new(),
            hub_credentials: Vec::new(),
            hub_registries: Vec::new(),
            integration_files: Vec::new(),
        };
        restore_backup_installation_metadata(state, &installation)?;
        restore_backup_room_manager(state, &installation.rooms)?;
        restore_backup_location(state, None)?;

        apply_backup_configuration(state, factory_default_backup_configuration())?;
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::ConfigChanged);

        build_profile_bundle(state)
    })()
    .map_err(|source| anyhow::Error::new(FactoryResetPostBarrierError { source }))
}

pub fn do_profile_bundle_reset(state: &SharedState) -> Result<String> {
    do_profile_bundle_import(
        state,
        ProfileBundleImportPayload::Bundle(factory_default_profile_bundle()),
    )
}

pub fn build_backup_bundle_dto(state: &SharedState, include_secrets: bool) -> Result<BackupBundle> {
    // A secret export must observe credentials and integration recovery
    // material from one external-controller epoch. Holding this transaction
    // through the snapshot prevents acquisition/release from changing either
    // half after preflight has approved it. Redacted exports retain their
    // existing non-blocking behavior.
    let external_transaction_lock = include_secrets
        .then(|| {
            state
                .lock()
                .map_err(|_| anyhow::anyhow!("lock"))
                .map(|state| state.external_topology_transaction_lock.clone())
        })
        .transpose()?;
    let _external_transaction = external_transaction_lock
        .as_ref()
        .map(|lock| {
            lock.lock()
                .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))
        })
        .transpose()?;

    {
        let state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if state.authority_state_recovery_required {
            anyhow::bail!("Authoritative topology state requires recovery before backup export");
        }
        if include_secrets && !state.external_controller_authority_pending.is_empty() {
            anyhow::bail!(
                "External controller authority transition must complete before secret backup export"
            );
        }
    }

    let secret_integration_files = if include_secrets {
        // A crash between durable credential deletion and Hue manifest
        // finalization must not produce a backup that contains recovery state
        // with no credential capable of using it. A release-phase manifest is
        // also intentionally non-transferable: reconnect rejects it, so an
        // exported copy could never be restored safely.
        Some(
            preflight_current_hue_recovery_state(
                state,
                HueRecoveryPreflightMode::SecretBackupExport,
            )
            .context("Secret backup Hue recovery preflight failed")?,
        )
    } else {
        None
    };
    let mut room_manager = room_manager_for_export(state);
    let (
        configuration,
        location,
        topology,
        canonical_registry,
        runtime_state,
        hub_credentials,
        hub_registries,
        integration_files,
    ) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let mut topology = s.topology.clone();
        let mut canonical_registry = s.canonical_registry.clone();
        strip_nonportable_local_ble_nodes(
            &mut room_manager,
            &mut topology,
            &mut canonical_registry,
        );
        let configuration = backup_configuration_from_parts(&s, &room_manager);
        let mut hub_credentials: Vec<_> = s
            .hub_credentials
            .values()
            .filter(|creds| {
                creds
                    .hub_type
                    .as_ref()
                    .is_none_or(|hub_type| !is_nonportable_local_ble(hub_type.as_str()))
            })
            .map(|creds| backup_hub_credentials_from_state(creds, include_secrets))
            .collect();
        hub_credentials.sort_by(|left, right| {
            left.address.cmp(&right.address).then(
                left.hub_type
                    .as_ref()
                    .map(|t| t.as_str())
                    .cmp(&right.hub_type.as_ref().map(|t| t.as_str())),
            )
        });
        let hub_registries: Vec<_> = s
            .hubs
            .iter()
            .filter(|(hub_key, _)| !is_nonportable_local_ble(hub_key.hub_type.as_str()))
            .filter_map(|(hub_key, hub)| {
                hub.registry
                    .as_ref()
                    .map(|registry| (hub_key.clone(), registry.clone()))
            })
            .collect();
        let mut integration_files = match secret_integration_files {
            Some(files) => files,
            None => match s.storage.as_ref() {
                Some(storage) => storage.load_integration_backup_files(false)?,
                None => Vec::new(),
            },
        };
        integration_files.retain(|file| {
            !file.path.starts_with("hue_ble/") && !file.path.starts_with("local_ble/")
        });

        (
            configuration,
            stored_location_from_state(&s),
            topology,
            canonical_registry,
            BackupRuntimeState {
                active_mode: s.active_mode,
                last_change_cause: s.last_active_mode_cause,
                last_change_transition_id: s.last_active_mode_transition_id.clone(),
                last_change_epoch_ms: s.last_active_mode_change_utc_ms,
            },
            hub_credentials,
            hub_registries,
            integration_files,
        )
    };

    let mut hub_registry_snapshots: Vec<_> = hub_registries
        .into_iter()
        .filter_map(|(hub_key, registry)| {
            registry.lock().ok().map(|registry| BackupHubRegistry {
                hub_key,
                snapshot: registry.snapshot_json(),
            })
        })
        .collect();
    hub_registry_snapshots
        .sort_by(|left, right| left.hub_key.to_string().cmp(&right.hub_key.to_string()));

    Ok(BackupBundle {
        schema_version: BACKUP_BUNDLE_SCHEMA_VERSION,
        kind: crate::bundle::BundleKind::BackupBundle,
        created_at: chrono::Utc::now().to_rfc3339(),
        secrets_included: include_secrets,
        configuration,
        installation: BackupInstallation {
            location,
            rooms: room_manager,
            topology,
            canonical_registry,
            hub_credentials,
            hub_registries: hub_registry_snapshots,
            integration_files,
        },
        runtime_state,
    })
}

pub fn build_backup_bundle(state: &SharedState, include_secrets: bool) -> Result<String> {
    let bundle = build_backup_bundle_dto(state, include_secrets)?;
    serde_json::to_string_pretty(&bundle)
        .map_err(|e| anyhow::anyhow!("serialize backup bundle: {}", e))
}

fn restore_backup_location(state: &SharedState, location: Option<StoredLocation>) -> Result<()> {
    let cleared_location = StoredLocation {
        latitude: None,
        longitude: None,
        utc_offset_hours: 0.0,
        timezone_name: None,
    };
    let location_to_apply = location.unwrap_or(cleared_location);

    let (runtime, solar_noon, latitude, longitude, utc_offset_hours, timezone_name) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let mut latitude = s.latitude;
        let mut longitude = s.longitude;
        let mut utc_offset_hours = s.utc_offset_hours;
        let mut runtime_config = s.runtime_config.clone();
        let mut timezone_name = s.timezone_name.clone();
        location_to_apply.apply_to_state(
            &mut latitude,
            &mut longitude,
            &mut utc_offset_hours,
            &mut runtime_config,
            &mut timezone_name,
        );
        if latitude.is_none() && longitude.is_none() && timezone_name.is_none() {
            runtime_config.solar_noon_hour = rhythm_core::RuntimeConfig::default().solar_noon_hour;
        }
        s.latitude = latitude;
        s.longitude = longitude;
        s.utc_offset_hours = utc_offset_hours;
        s.runtime_config = runtime_config;
        s.timezone_name = timezone_name;
        if let Some(storage) = s.storage.as_ref() {
            if let Err(e) = storage.save_location(&location_to_apply) {
                warn!(target: "cmd", "Failed to save restored location: {}", e);
            }
        }
        (
            s.hub_runtime(),
            s.runtime_config.solar_noon_hour,
            s.latitude,
            s.longitude,
            s.utc_offset_hours,
            s.timezone_name.clone(),
        )
    };

    if let Some(runtime) = runtime {
        let local_now = if let Some(ref tz_name) = timezone_name {
            rhythm_core::Timezone::new(tz_name)
                .local_datetime_from_utc(chrono::Utc::now().naive_utc())
        } else {
            current_local_datetime(utc_offset_hours)
        };
        let day_of_year = rhythm_core::timezone::day_of_year(
            local_now.date().year(),
            local_now.date().month(),
            local_now.date().day(),
        );
        if let Err(e) = runtime.set_solar(rhythm_core::SolarTime::new(
            solar_noon,
            latitude.unwrap_or(0.0),
            day_of_year,
        )) {
            warn!(target: "cmd", "Failed to apply restored solar location: {}", e);
        }
        if let (Some(lat), Some(lon), Some(tz_name)) =
            (latitude, longitude, timezone_name.as_deref())
        {
            let tz = rhythm_core::Timezone::new(tz_name);
            let sun_times = rhythm_core::calculate_sun_times(
                lat,
                lon,
                local_now.date().year(),
                local_now.date().month(),
                local_now.date().day(),
                &tz,
            );
            if let Err(e) = runtime.set_sun_times(sun_times) {
                warn!(target: "cmd", "Failed to apply restored sun times: {}", e);
            }
        } else if let Err(e) = runtime.clear_sun_times() {
            warn!(target: "cmd", "Failed to clear restored sun times: {}", e);
        }
    }

    Ok(())
}

fn restore_backup_installation_metadata(
    state: &SharedState,
    installation: &BackupInstallation,
) -> Result<()> {
    let mut topology = installation.topology.clone();
    topology.rebuild_indices();
    let mut canonical_registry = installation.canonical_registry.clone();
    canonical_registry.rebuild_indices();
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    canonical_registry.backfill_unassigned_triage(now);

    {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let topology_before = s.topology.clone();
        let canonical_before = s.canonical_registry.clone();
        s.topology = topology;
        s.canonical_registry = canonical_registry;
        if let Err(error) = save_authority_state_unchecked(&s) {
            s.topology = topology_before;
            s.canonical_registry = canonical_before;
            // The explicit replacement snapshot did not cross its durability
            // barrier. Even if the caller began from an otherwise healthy
            // runtime, no external controller may act on the transient graph
            // until recovery commits a complete combined snapshot.
            s.authority_state_recovery_required = true;
            return Err(error.context("Failed to durably restore installation topology"));
        }
        // A validated backup restore or post-barrier factory reset is the
        // explicit recovery path for a corrupt combined authority snapshot.
        // An in-progress Hue backup handoff keeps the fence closed until the
        // imported credentials and manifest have both reached their final
        // durable state.
        s.authority_state_recovery_required = s
            .hub_credentials
            .values()
            .any(|credentials| credentials.backup_restore_pending);
    }

    rebuild_composite_routing(state);

    Ok(())
}

fn restore_backup_room_manager(
    state: &SharedState,
    rooms: &rhythm_core::RoomManager,
) -> Result<()> {
    let mut normalized_rooms = rhythm_core::RoomManager::new();
    for room in rooms.iter().cloned().map(normalize_legacy_soft_off_room) {
        if crate::topology::is_internal_light_node_id(&room.id) {
            continue;
        }
        normalized_rooms.add_room(room);
    }
    let needs_runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let has_runtime = s.hubs.values().any(|hub| hub.runtime.is_some());
        !has_runtime && s.has_any_hub()
    };
    if needs_runtime {
        try_ensure_runtime(state)?;
    }

    let runtime = state.lock().ok().and_then(|s| s.hub_runtime());
    let desired_ids: HashSet<String> = normalized_rooms
        .iter()
        .map(|room| room.id.clone())
        .collect();

    {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.room_observed_power
            .retain(|room_id, _| desired_ids.contains(room_id));
        s.motion_snapshots
            .retain(|room_id, _| desired_ids.contains(room_id));
        s.room_mode_transitions
            .retain(|room_id, _| desired_ids.contains(room_id));
        s.pending_motion_clear
            .retain(|room_id| desired_ids.contains(room_id));
    }

    if let Some(runtime) = runtime {
        for snapshot in runtime.engine_all_node_snapshots() {
            if !desired_ids.contains(&snapshot.id) {
                runtime.remove_node(&snapshot.id);
            }
        }

        for room in normalized_rooms.iter() {
            runtime.add_node(&room.id, &room.name, room.kind, room.parent_id.clone());
            runtime.restore_node_state(&room.id, restored_node_state_from_room(room));
        }

        let rooms = rooms_from_engine(runtime.as_ref());
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if let Some(storage) = s.storage.as_ref() {
            storage
                .save_rooms(&rooms)
                .context("Failed to durably restore room state")?;
        }
    } else {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if let Some(storage) = s.storage.as_ref() {
            storage
                .save_rooms(&normalized_rooms)
                .context("Failed to durably restore room state")?;
        }
    }

    crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);

    Ok(())
}

fn restore_backup_runtime_state(
    state: &SharedState,
    runtime_state: &BackupRuntimeState,
) -> Result<()> {
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    s.active_mode = runtime_state.active_mode;
    s.last_active_mode_cause = runtime_state.last_change_cause;
    s.last_active_mode_transition_id = runtime_state.last_change_transition_id.clone();
    s.last_active_mode_change_utc_ms = runtime_state.last_change_epoch_ms;
    // Backup restore is authoritative for room state, so discard any deferred
    // mode-output apply that `apply_backup_configuration` may have flagged
    // while restoring with no runtime attached. Otherwise a late hub
    // reconnect would re-apply mode defaults over the restored room state.
    s.pending_mode_output_apply = false;
    s.sync_active_mode_runtime_overrides();
    s.invalidate_queued_light_dispatches();
    persist_settings_locked(&s);
    Ok(())
}

fn save_backup_hub_registries_to_storage(
    state: &SharedState,
    registries: &[BackupHubRegistry],
) -> Result<()> {
    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let Some(storage) = s.storage.as_ref() else {
        return Ok(());
    };
    storage
        .clear_hub_registries()
        .map_err(|e| anyhow::anyhow!("Failed to clear persisted hub registries: {}", e))?;

    for registry in registries {
        if let Err(e) = storage.save_hub_registry_for(&registry.hub_key, &registry.snapshot) {
            warn!(
                target: "cmd",
                "Failed to save restored hub registry for {}: {}",
                registry.hub_key,
                e
            );
        }
    }

    Ok(())
}

fn restore_backup_integration_files(
    state: &SharedState,
    files: &[BackupIntegrationFile],
) -> Result<()> {
    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let Some(storage) = s.storage.as_ref() else {
        return Ok(());
    };
    storage
        .restore_integration_backup_files(files)
        .map_err(|e| anyhow::anyhow!("Failed to restore integration files: {}", e))
}

fn hue_ownership_manifest_bridge_ids(
    files: &[BackupIntegrationFile],
    source: &str,
) -> Result<Vec<String>> {
    let bridge_ids = files
        .iter()
        .filter(|file| {
            file.path.starts_with("hue/controller-ownership/by-bridge/")
                && file.path.ends_with(".json")
        })
        .map(|file| {
            serde_json::from_str::<serde_json::Value>(&file.content)
                .ok()
                .and_then(|value| {
                    value
                        .pointer("/baseline/bridge_id")
                        .and_then(serde_json::Value::as_str)
                        .filter(|bridge_id| !bridge_id.trim().is_empty())
                        .map(str::to_string)
                })
                .ok_or_else(|| anyhow::anyhow!("{source} contains invalid Hue recovery identity"))
        })
        .collect::<Result<Vec<_>>>()?;
    let unique_bridge_ids = bridge_ids.iter().cloned().collect::<BTreeSet<_>>();
    if unique_bridge_ids.len() != bridge_ids.len() {
        anyhow::bail!("{source} contains duplicate Hue recovery identities");
    }
    Ok(bridge_ids)
}

fn hue_ownership_manifest_phase(file: &BackupIntegrationFile, source: &str) -> Result<String> {
    serde_json::from_str::<serde_json::Value>(&file.content)
        .ok()
        .and_then(|value| {
            value
                .get("phase")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string)
        })
        .filter(|phase| !phase.trim().is_empty())
        .ok_or_else(|| anyhow::anyhow!("{source} contains invalid Hue recovery phase"))
}

fn hue_ownership_phase_blocks_backup(phase: &str) -> bool {
    matches!(
        phase,
        "restoring" | "restore_incomplete" | "release_pending"
    )
}

fn hue_ownership_phase_is_archival(phase: &str) -> bool {
    matches!(phase, "snapshot_retained" | "restored")
}

fn reject_backup_unsafe_hue_ownership_phases(
    files: &[BackupIntegrationFile],
    source: &str,
) -> Result<()> {
    for file in files.iter().filter(|file| {
        file.path.starts_with("hue/controller-ownership/by-bridge/") && file.path.ends_with(".json")
    }) {
        if hue_ownership_phase_blocks_backup(&hue_ownership_manifest_phase(file, source)?) {
            anyhow::bail!(
                "{source} contains Hue controller recovery state that cannot be transferred during controller release"
            );
        }
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HueRecoveryPreflightMode {
    ControllerRelease,
    SecretBackupExport,
}

/// Refuse to cross a destructive local-state boundary if persisted Hue
/// recovery material has become orphaned from the one credential that can
/// restore its physical bridge, or when the runtime cannot execute the full
/// release/finalization lifecycle. This check intentionally runs before the
/// integration release callback, platform reset barrier, or backup
/// replacement writes anything.
fn preflight_current_hue_recovery_state(
    state: &SharedState,
    mode: HueRecoveryPreflightMode,
) -> Result<Vec<BackupIntegrationFile>> {
    let (storage, credentials, release_callback_available, finalize_callback_available) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (
            s.storage.clone(),
            s.hub_credentials.values().cloned().collect::<Vec<_>>(),
            s.release_external_controller_authority_fn.is_some(),
            s.finalize_external_controller_release_fn.is_some(),
        )
    };
    let Some(storage) = storage else {
        return Ok(Vec::new());
    };
    let files = storage
        .load_integration_backup_files(true)
        .context("Failed to inspect persisted Hue controller recovery state")?;
    let bridge_ids = hue_ownership_manifest_bridge_ids(&files, "Persisted state")?;
    if !bridge_ids.is_empty() {
        storage
            .validate_integration_backup_files(&files)
            .context("Persisted Hue controller recovery state is invalid")?;
    }
    for bridge_id in bridge_ids {
        let manifest = files
            .iter()
            .find(|file| {
                serde_json::from_str::<serde_json::Value>(&file.content)
                    .ok()
                    .and_then(|value| {
                        value
                            .pointer("/baseline/bridge_id")
                            .and_then(serde_json::Value::as_str)
                            .map(|candidate| candidate == bridge_id)
                    })
                    .unwrap_or(false)
            })
            .expect("Hue recovery identity was collected from this file set");
        let phase = hue_ownership_manifest_phase(manifest, "Persisted state")?;
        let matching_credentials = credentials
            .iter()
            .filter(|credential| {
                credential
                    .hub_type
                    .as_ref()
                    .is_some_and(|hub_type| hub_type.as_str() == crate::hub::HubType::HUE)
                    && credential.get_str("bridge_id") == Some(bridge_id.as_str())
            })
            .collect::<Vec<_>>();
        let matching_usable_credentials = matching_credentials
            .iter()
            .filter(|credential| {
                credential.can_restore_external_controller()
                    && credential
                        .get_str("username")
                        .is_some_and(|username| !username.trim().is_empty())
            })
            .count();
        if mode == HueRecoveryPreflightMode::SecretBackupExport
            && hue_ownership_phase_blocks_backup(&phase)
        {
            anyhow::bail!(
                "Persisted state contains Hue controller recovery state that cannot be transferred during controller release"
            );
        }
        if hue_ownership_phase_is_archival(&phase) && matching_credentials.is_empty() {
            continue;
        }
        if matching_credentials.len() == 1 && matching_usable_credentials == 1 {
            if mode == HueRecoveryPreflightMode::ControllerRelease
                && (!release_callback_available || !finalize_callback_available)
            {
                anyhow::bail!(
                    "Persisted Hue controller recovery cannot be released because its lifecycle callbacks are unavailable"
                );
            }
            continue;
        }
        anyhow::bail!(
            "Persisted Hue recovery state requires exactly one usable bridge-bound credential"
        );
    }
    Ok(files)
}

fn preflight_backup_integration_files(
    state: &SharedState,
    installation: &BackupInstallation,
) -> Result<bool> {
    if let Some(storage) = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .storage
        .clone()
    {
        storage
            .validate_integration_backup_files(&installation.integration_files)
            .context("Backup integration-state preflight failed")?;
    }

    reject_backup_unsafe_hue_ownership_phases(&installation.integration_files, "Backup")?;

    let hue_manifest_bridge_ids =
        hue_ownership_manifest_bridge_ids(&installation.integration_files, "Backup")?
            .into_iter()
            .collect::<BTreeSet<_>>();
    if hue_manifest_bridge_ids.is_empty() {
        return Ok(false);
    }
    let active_hue_manifest_bridge_ids = installation
        .integration_files
        .iter()
        .filter(|file| {
            file.path.starts_with("hue/controller-ownership/by-bridge/")
                && file.path.ends_with(".json")
        })
        .filter_map(|file| {
            let phase = hue_ownership_manifest_phase(file, "Backup").ok()?;
            if hue_ownership_phase_is_archival(&phase) {
                return None;
            }
            serde_json::from_str::<serde_json::Value>(&file.content)
                .ok()?
                .pointer("/baseline/bridge_id")?
                .as_str()
                .map(str::to_string)
        })
        .collect::<BTreeSet<_>>();
    let hue_credentials = installation
        .hub_credentials
        .iter()
        .filter(|credential| {
            credential
                .hub_type
                .as_ref()
                .is_some_and(|hub_type| hub_type.as_str() == crate::hub::HubType::HUE)
        })
        .collect::<Vec<_>>();
    let mut usable_hue_credential_bridge_ids = Vec::with_capacity(hue_credentials.len());
    for credential in &hue_credentials {
        let data = credential
            .data
            .as_ref()
            .ok_or_else(|| anyhow::anyhow!("Backup Hue credentials contain no secrets"))?;
        if !data
            .get("username")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|username| !username.trim().is_empty())
        {
            anyhow::bail!("Backup Hue credentials contain no usable username");
        }
        let bridge_id = data
            .get("bridge_id")
            .and_then(serde_json::Value::as_str)
            .filter(|bridge_id| !bridge_id.trim().is_empty())
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "Backup Hue credentials are not bound to a physical bridge identity"
                )
            })?;
        usable_hue_credential_bridge_ids.push(bridge_id.to_string());
    }
    let unique_credential_bridge_ids = usable_hue_credential_bridge_ids
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    if unique_credential_bridge_ids.len() != usable_hue_credential_bridge_ids.len()
        || !active_hue_manifest_bridge_ids.is_subset(&unique_credential_bridge_ids)
        || !unique_credential_bridge_ids.is_subset(&hue_manifest_bridge_ids)
    {
        anyhow::bail!(
            "Backup Hue active recovery manifests and bridge-bound credentials do not match"
        );
    }

    if !hue_credentials.is_empty() {
        let get_provider = {
            let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            if !s
                .hub_capabilities
                .iter()
                .any(|capability| capability.hub_type == crate::hub::HubType::HUE)
            {
                anyhow::bail!("Hue backup credential validator is unavailable");
            }
            s.get_hub_provider_fn
                .clone()
                .ok_or_else(|| anyhow::anyhow!("Hue backup credential validator is unavailable"))?
        };
        let provider = get_provider(crate::hub::HubType::new(crate::hub::HubType::HUE));
        for credential in hue_credentials {
            provider
                .validate_backup_credentials(
                    &credential.address,
                    credential
                        .data
                        .as_ref()
                        .expect("Hue credential data was validated above"),
                )
                .context("Backup Hue credentials failed live bridge validation")?;
        }
    }
    Ok(!active_hue_manifest_bridge_ids.is_empty())
}

/// Commit every credential from a validated backup as disconnected state.
///
/// Backup restore holds the external-topology transaction while calling this
/// helper. Connecting a hub here would recursively acquire that transaction
/// during discovery/authority reconciliation and could expose a partially
/// imported installation. Instead, persist the complete credential set in one
/// write, update memory, and let the ordinary stored-hub bootstrap run after
/// the restore transaction is released.
fn restored_hub_credentials(
    credentials: &[BackupHubCredentials],
) -> Vec<crate::hub::HubCredentials> {
    let mut restored = Vec::new();
    for credential in credentials {
        let Some(hub_type) = credential.hub_type.as_ref() else {
            continue;
        };
        let restored_credential = match credential.data.as_ref() {
            Some(data) => crate::hub::HubCredentials::new(
                hub_type.as_str(),
                &credential.address,
                data.clone(),
            ),
            None => {
                info!(
                    target: "cmd",
                    "Restored redacted hub placeholder {} at {}; awaiting fresh credentials",
                    hub_type.as_str(),
                    credential.address
                );
                crate::hub::HubCredentials::redacted_placeholder(
                    hub_type.as_str(),
                    &credential.address,
                )
            }
        };
        restored.push(restored_credential);
    }
    restored
}

/// Durably publish recovery-capable but connection-fenced Hue credentials
/// before replacing integration files with an imported ownership manifest.
/// A crash or later restore error can therefore retry release/finalization,
/// while stored-hub bootstrap cannot acquire authority from a partial graph.
fn stage_pending_hue_backup_credentials(
    state: &SharedState,
    credentials: &[BackupHubCredentials],
    require_hue_authority: bool,
) -> Result<()> {
    if !require_hue_authority {
        return Ok(());
    }

    let mut pending = restored_hub_credentials(credentials)
        .into_iter()
        .filter(|credential| {
            credential
                .hub_type
                .as_ref()
                .is_some_and(|hub_type| hub_type.as_str() == crate::hub::HubType::HUE)
                && credential.can_restore_external_controller()
        })
        .collect::<Vec<_>>();
    if pending.is_empty() {
        anyhow::bail!("Validated Hue backup has no recovery-capable credentials");
    }
    for credential in &mut pending {
        credential.backup_restore_pending = true;
    }

    let storage = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .storage
        .clone();
    if let Some(storage) = storage {
        storage
            .save_all_hub_credentials(&pending)
            .context("Failed to durably stage pending Hue backup recovery credentials")?;
    }

    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    s.hub_credentials.clear();
    s.external_controller_authority_required.clear();
    s.authority_state_recovery_required = true;
    for credential in pending {
        let Some(key) = credential.hub_key() else {
            continue;
        };
        s.clear_hub_connected(&key);
        s.clear_hub_startup_retry(&key);
        s.set_external_controller_authority_required(&key, true);
        s.mark_external_controller_authority_pending(&key);
        s.hub_credentials.insert(key, credential);
    }
    Ok(())
}

fn stage_backup_hub_credentials(
    state: &SharedState,
    credentials: &[BackupHubCredentials],
    require_hue_authority: bool,
) -> Result<bool> {
    let restored = restored_hub_credentials(credentials);

    let has_connectable_credentials = restored.iter().any(crate::hub::HubCredentials::can_connect);
    let storage = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .storage
        .clone();
    if let Some(storage) = storage {
        storage
            .save_all_hub_credentials(&restored)
            .context("Failed to durably stage restored hub credentials")?;
    }

    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    s.hub_credentials.clear();
    s.external_controller_authority_required.clear();
    for credential in restored {
        let Some(key) = credential.hub_key() else {
            continue;
        };
        s.clear_hub_connected(&key);
        s.clear_hub_startup_retry(&key);
        let requires_authority = s.topology.grouped_room_control_is_required(&key)
            || (require_hue_authority && key.hub_type.as_str() == crate::hub::HubType::HUE);
        s.set_external_controller_authority_required(&key, requires_authority);
        if requires_authority && credential.can_connect() {
            s.mark_external_controller_authority_pending(&key);
        }
        s.hub_credentials.insert(key, credential);
    }
    // The complete imported installation and its final credential set are now
    // durable. This is the commit point that reopens authority bootstrap.
    s.authority_state_recovery_required = false;

    Ok(has_connectable_credentials)
}

fn request_restored_hub_bootstrap(state: &SharedState, should_bootstrap: bool) -> Result<()> {
    if !should_bootstrap {
        return Ok(());
    }
    let request_bootstrap = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .request_hub_bootstrap_fn
        .clone();
    if let Some(request_bootstrap) = request_bootstrap {
        request_bootstrap(state);
    } else {
        warn!(
                target: "cmd",
                "Restored connectable hub credentials; no stored-hub bootstrap callback is registered"
        );
    }
    Ok(())
}

fn current_local_datetime(utc_offset: f32) -> chrono::NaiveDateTime {
    let now = chrono::Utc::now().naive_utc();
    let offset_secs = (utc_offset * 3600.0) as i64;
    now + chrono::Duration::seconds(offset_secs)
}

fn local_time_string_from_decimal_hour(hour: f32) -> String {
    let total_seconds = ((hour.rem_euclid(24.0)) * 3600.0).round() as i64;
    let wrapped_seconds = total_seconds.rem_euclid(24 * 3600);
    let hours = wrapped_seconds / 3600;
    let minutes = (wrapped_seconds % 3600) / 60;
    let seconds = wrapped_seconds % 60;
    format!("{hours:02}:{minutes:02}:{seconds:02}")
}

fn optional_local_time_string_from_decimal_hour(hour: Option<f32>) -> Option<String> {
    hour.map(local_time_string_from_decimal_hour)
}

fn mode_apply_cycle_duration(
    lighting: RoomLightingContext<'_>,
    room_snapshots: &[rhythm_core::RoomSnapshot],
    update_interval: Duration,
    power_save: bool,
    room_commands: &[(String, LightingCommand)],
) -> Duration {
    let sample_at = current_local_datetime(lighting.utc_offset);
    let ctx = rhythm_core::curve_context_for_local_datetime(
        lighting.solar_noon,
        lighting.latitude,
        lighting.longitude,
        lighting.timezone_name,
        sample_at,
    );
    let registry = light_profile_registry_from_parts(
        lighting.light_profile_configs,
        lighting.mode_configs,
        lighting.mode,
    );

    let room_node_snapshots: Vec<rhythm_core::NodeSnapshot> = room_snapshots
        .iter()
        .cloned()
        .map(rhythm_core::NodeSnapshot::from_room_snapshot)
        .collect();
    let periodic_cycle = crate::periodic::effective_cycle_duration(
        &registry,
        &ctx,
        &room_node_snapshots,
        update_interval,
        power_save,
    );

    let fade_window_ms = room_commands
        .iter()
        .filter_map(|(_, command)| command.transition_ms)
        .max()
        .unwrap_or(0)
        .max(1_000);

    periodic_cycle.min(Duration::from_millis(u64::from(fade_window_ms)))
}

fn node_state_events_after_apply(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    node_id: &str,
) -> Vec<crate::server_event::NodeStateEvent> {
    let Some(snap) = runtime.engine_effective_node_snapshot(node_id) else {
        return Vec::new();
    };

    let mut events = vec![build_node_state_event(state, &snap)];
    let mut emitted_node_ids = HashSet::from([snap.id.clone()]);
    if snap.kind == LightNodeKind::LightDevice {
        if let Some(parent_id) = snap
            .parent_id
            .as_deref()
            .filter(|parent_id| *parent_id != snap.id)
        {
            if let Some(parent_snap) = runtime.engine_effective_node_snapshot(parent_id) {
                if emitted_node_ids.insert(parent_snap.id.clone()) {
                    events.push(build_node_state_event(state, &parent_snap));
                }
            }
        }
    } else if snap.kind.is_room() {
        let mut child_snaps: Vec<_> = runtime
            .engine_all_effective_node_snapshots()
            .into_iter()
            .filter(|child| {
                child.parent_id.as_deref() == Some(snap.id.as_str())
                    && child.kind.is_light_addressable()
            })
            .collect();
        child_snaps.sort_by(|left, right| left.id.cmp(&right.id));
        for child_snap in child_snaps {
            if emitted_node_ids.insert(child_snap.id.clone()) {
                events.push(build_node_state_event(state, &child_snap));
            }
        }
    }

    events
}

pub(crate) fn emit_node_state_event_after_apply(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    node_id: &str,
) {
    {
        let events = node_state_events_after_apply(state, runtime, node_id);
        if !events.is_empty() {
            crate::state::emit_server_event(
                state,
                crate::server_event::ServerEvent::NodeState { nodes: events },
            );
        }
    }
}

fn emit_node_state_event_for_dispatch_pending_change(state: &SharedState, node_id: &str) {
    let runtime = {
        let Ok(s) = state.lock() else { return };
        s.hub_runtime()
    };
    if let Some(runtime) = runtime {
        emit_node_state_event_after_apply(state, &runtime, node_id);
    }
}

/// Whether this node (or its topology parent room) currently has
/// user-initiated pending work.
///
/// Gates hub-mailbox pending marks: user commands enqueue while their work
/// item still holds the node's pending count, so this distinguishes them from
/// periodic-tick dispatches, which must never surface as a card spinner.
/// Group/device jobs enqueue under device ids while the user's work item
/// marks the room, hence the parent check.
pub(crate) fn node_has_user_pending_dispatch(state: &SharedState, node_id: &str) -> bool {
    let Ok(s) = state.lock() else { return false };
    if s.pending_node_dispatches.contains_key(node_id) {
        return true;
    }
    parent_node_id_for_pending_dispatch(&s, node_id)
        .is_some_and(|parent| s.pending_node_dispatches.contains_key(&parent))
}

pub(crate) fn mark_node_dispatch_pending(state: &SharedState, node_id: &str) {
    let became_pending = {
        let Ok(mut s) = state.lock() else { return };
        let count = s
            .pending_node_dispatches
            .entry(node_id.to_string())
            .or_insert(0);
        let became_pending = *count == 0;
        *count += 1;
        became_pending
    };
    if became_pending {
        emit_node_state_event_for_dispatch_pending_change(state, node_id);
    }
}

pub(crate) fn clear_node_dispatch_pending(state: &SharedState, node_id: &str) {
    let cleared = {
        let Ok(mut s) = state.lock() else { return };
        let Some(count) = s.pending_node_dispatches.get_mut(node_id) else {
            return;
        };
        if *count > 1 {
            *count -= 1;
            false
        } else {
            s.pending_node_dispatches.remove(node_id);
            true
        }
    };
    if cleared {
        emit_node_state_event_for_dispatch_pending_change(state, node_id);
    }
}

/// Register one composite outcome that was accepted by an asynchronous hub
/// controller. The composite's pending mark remains held until every command
/// id resolves.
#[derive(Debug)]
pub(crate) struct IntegrationDispatchRegistration {
    pub early_outcomes: Vec<crate::state::EarlyIntegrationOutcome>,
    pub complete: bool,
}

#[derive(Debug, PartialEq, Eq)]
pub(crate) enum IntegrationOutcomeDisposition {
    Deferred,
    Resolved {
        node_id: String,
        dispatch_complete: bool,
    },
}

const EARLY_INTEGRATION_OUTCOME_CAPACITY: usize = 2_048;

pub(crate) fn register_integration_dispatch(
    state: &SharedState,
    hub_key: &str,
    node_id: &str,
    controller_stream_id: &str,
    command_ids: &[u64],
) -> Result<IntegrationDispatchRegistration, String> {
    if command_ids.is_empty() {
        return Err("controller accepted a dispatch without command ids".to_string());
    }
    if controller_stream_id.is_empty() {
        return Err("controller accepted a dispatch without a stream identity".to_string());
    }
    let mut unique = std::collections::HashSet::new();
    if command_ids.iter().any(|id| *id == 0 || !unique.insert(*id)) {
        return Err("controller returned invalid or duplicate command ids".to_string());
    }

    let mut s = state
        .lock()
        .map_err(|_| "application state lock poisoned".to_string())?;
    for command_id in command_ids {
        if s.pending_integration_commands.contains_key(&(
            hub_key.to_string(),
            controller_stream_id.to_string(),
            *command_id,
        )) {
            return Err(format!(
                "controller command id {command_id} is already pending for {hub_key}"
            ));
        }
    }

    let mut early_outcomes = Vec::new();
    for command_id in command_ids {
        if let Some(outcome) = s.early_integration_outcomes.remove(&(
            hub_key.to_string(),
            controller_stream_id.to_string(),
            *command_id,
        )) {
            unique.remove(command_id);
            early_outcomes.push(outcome);
        }
    }
    if unique.is_empty() {
        return Ok(IntegrationDispatchRegistration {
            early_outcomes,
            complete: true,
        });
    }

    let dispatch_id = s.next_integration_dispatch_id.max(1);
    s.next_integration_dispatch_id = dispatch_id.saturating_add(1).max(1);
    for command_id in &unique {
        s.pending_integration_commands.insert(
            (
                hub_key.to_string(),
                controller_stream_id.to_string(),
                *command_id,
            ),
            dispatch_id,
        );
    }
    s.pending_integration_dispatches.insert(
        dispatch_id,
        crate::state::PendingIntegrationDispatch {
            node_id: node_id.to_string(),
            hub_key: hub_key.to_string(),
            controller_stream_id: controller_stream_id.to_string(),
            remaining_command_ids: unique,
        },
    );
    Ok(IntegrationDispatchRegistration {
        early_outcomes,
        complete: false,
    })
}

/// Reconcile a terminal controller event with its acceptance receipt. The two
/// arrive on independent channels, so an event that arrives first is retained
/// and consumed atomically when registration follows.
pub(crate) fn reconcile_integration_outcome(
    state: &SharedState,
    hub_key: &str,
    controller_stream_id: &str,
    command_id: u64,
    outcome: crate::state::EarlyIntegrationOutcome,
) -> Result<IntegrationOutcomeDisposition, String> {
    let mut s = state
        .lock()
        .map_err(|_| "application state lock poisoned".to_string())?;
    let command_key = (
        hub_key.to_string(),
        controller_stream_id.to_string(),
        command_id,
    );
    let Some(dispatch_id) = s.pending_integration_commands.remove(&command_key) else {
        if s.early_integration_outcomes.len() >= EARLY_INTEGRATION_OUTCOME_CAPACITY
            && !s.early_integration_outcomes.contains_key(&command_key)
        {
            if let Some(oldest_available) = s.early_integration_outcomes.keys().next().cloned() {
                s.early_integration_outcomes.remove(&oldest_available);
            }
        }
        s.early_integration_outcomes.insert(command_key, outcome);
        return Ok(IntegrationOutcomeDisposition::Deferred);
    };
    let dispatch = s
        .pending_integration_dispatches
        .get_mut(&dispatch_id)
        .ok_or_else(|| format!("controller dispatch {dispatch_id} is missing"))?;
    dispatch.remaining_command_ids.remove(&command_id);
    let node_id = dispatch.node_id.clone();
    if !dispatch.remaining_command_ids.is_empty() {
        return Ok(IntegrationOutcomeDisposition::Resolved {
            node_id,
            dispatch_complete: false,
        });
    }
    let node_id = s
        .pending_integration_dispatches
        .remove(&dispatch_id)
        .map(|dispatch| dispatch.node_id)
        .ok_or_else(|| format!("controller dispatch {dispatch_id} disappeared"))?;
    Ok(IntegrationOutcomeDisposition::Resolved {
        node_id,
        dispatch_complete: true,
    })
}

/// Fail every accepted dispatch for a controller whose event stream restarted
/// or lost retained events. Returns one node per held composite pending mark.
pub(crate) fn reset_integration_dispatches_for_hub(
    state: &SharedState,
    hub_key: &str,
    current_stream_id: &str,
    include_current_stream: bool,
) -> Vec<String> {
    let Ok(mut s) = state.lock() else {
        return Vec::new();
    };
    let dispatch_ids: Vec<u64> = s
        .pending_integration_dispatches
        .iter()
        .filter_map(|(dispatch_id, dispatch)| {
            (dispatch.hub_key == hub_key
                && (include_current_stream || dispatch.controller_stream_id != current_stream_id))
                .then_some(*dispatch_id)
        })
        .collect();
    let mut nodes = Vec::with_capacity(dispatch_ids.len());
    for dispatch_id in dispatch_ids {
        if let Some(dispatch) = s.pending_integration_dispatches.remove(&dispatch_id) {
            for command_id in dispatch.remaining_command_ids {
                s.pending_integration_commands.remove(&(
                    hub_key.to_string(),
                    dispatch.controller_stream_id.clone(),
                    command_id,
                ));
            }
            nodes.push(dispatch.node_id);
        }
    }
    s.early_integration_outcomes
        .retain(|(event_hub, event_stream, _), _| {
            event_hub != hub_key || (!include_current_stream && event_stream == current_stream_id)
        });
    nodes
}

pub(crate) fn try_send_work_item_with_pending(
    state: &SharedState,
    tx: &std::sync::mpsc::SyncSender<WorkItem>,
    item: WorkItem,
) -> std::result::Result<(), std::sync::mpsc::TrySendError<WorkItem>> {
    let pending_node_id = item.pending_node_id().map(str::to_string);
    if let Some(node_id) = pending_node_id.as_deref() {
        mark_node_dispatch_pending(state, node_id);
    }
    match tx.try_send(item) {
        Ok(()) => Ok(()),
        Err(err) => {
            if let Some(node_id) = pending_node_id.as_deref() {
                clear_node_dispatch_pending(state, node_id);
            }
            Err(err)
        }
    }
}

/// Upper bound on how long a dispatcher thread waits for space on the
/// bounded work channel. If the cmd-worker is dead or wedged, an unbounded
/// `send()` would park this thread forever, leave the node flagged
/// `pending_dispatch`, and leak one blocked thread per subsequent dispatch.
const WORK_ITEM_SEND_TIMEOUT: Duration = Duration::from_secs(30);

fn send_work_item_with_pending(
    state: &SharedState,
    tx: &std::sync::mpsc::SyncSender<WorkItem>,
    item: WorkItem,
) -> std::result::Result<(), std::sync::mpsc::TrySendError<WorkItem>> {
    let pending_node_id = item.pending_node_id().map(str::to_string);
    if let Some(node_id) = pending_node_id.as_deref() {
        mark_node_dispatch_pending(state, node_id);
    }
    // Bounded retry instead of a blocking send(): std::sync::mpsc has no
    // send_timeout, and an unbounded send here parks the dispatcher thread
    // forever if the cmd-worker dies or wedges.
    let deadline = std::time::Instant::now() + WORK_ITEM_SEND_TIMEOUT;
    let mut item = item;
    loop {
        match tx.try_send(item) {
            Ok(()) => return Ok(()),
            Err(std::sync::mpsc::TrySendError::Full(returned)) => {
                if std::time::Instant::now() >= deadline {
                    warn!(
                        target: "cmd",
                        "Work queue full for {:?} — worker wedged? Dropping item",
                        WORK_ITEM_SEND_TIMEOUT
                    );
                    if let Some(node_id) = pending_node_id.as_deref() {
                        clear_node_dispatch_pending(state, node_id);
                    }
                    return Err(std::sync::mpsc::TrySendError::Full(returned));
                }
                item = returned;
                std::thread::sleep(Duration::from_millis(50));
            }
            Err(err @ std::sync::mpsc::TrySendError::Disconnected(_)) => {
                warn!(target: "cmd", "Work queue receiver gone: dropping item");
                if let Some(node_id) = pending_node_id.as_deref() {
                    clear_node_dispatch_pending(state, node_id);
                }
                return Err(err);
            }
        }
    }
}

/// Persisted user-managed rooms that definitively have no physical target.
///
/// Missing routes alone are not enough to skip work: an integration/controller
/// failure must remain visible, and empty bootstrap rooms may still be backed by
/// a legacy runtime route. A user-customized room with neither device membership
/// nor a source-room binding is a semantic settings container with nothing to
/// dispatch.
#[derive(Default)]
struct EmptyTopologyRooms {
    room_ids: HashSet<String>,
}

impl EmptyTopologyRooms {
    fn from_state(state: &SharedState) -> Self {
        let Ok(s) = state.lock() else {
            return Self::default();
        };
        let room_ids = s
            .topology
            .rooms()
            .filter(|room| room.user_customized && !room.has_devices() && !room.has_bindings())
            .map(|room| room.id.clone())
            .collect();
        Self { room_ids }
    }

    fn contains(&self, node_id: &str) -> bool {
        self.room_ids.contains(node_id)
    }
}

fn apply_room_mode_defaults(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    empty_topology_rooms: &EmptyTopologyRooms,
    ctx: ModeDefaultApplyContext<'_>,
    snapshots: &[rhythm_core::RoomSnapshot],
) -> bool {
    let Some(mode_config) = mode_config_for_mode(ctx.lighting.mode_configs, ctx.lighting.mode)
    else {
        return false;
    };
    if mode_config.room_defaults.is_empty() && !ctx.reset_all_room_defaults {
        return false;
    }

    let snapshots_by_id: HashMap<&str, &rhythm_core::RoomSnapshot> = snapshots
        .iter()
        .map(|snap| (snap.id.as_str(), snap))
        .collect();
    let defaults_by_room: HashMap<&str, RoomModeState> = mode_config
        .room_defaults
        .iter()
        .map(|default| (default.room_id.as_str(), default.state))
        .collect();
    let mut target_rooms = Vec::new();
    let mut changed_room_ids = Vec::new();
    let mut non_hard_off_changed_room_ids = Vec::new();
    let mut hard_off_rooms = Vec::new();
    let mut attached_hard_off_node_ids = Vec::new();
    let mut empty_hard_off_room_ids = Vec::new();
    let mut lights_on_updates = Vec::new();
    let mut missing_rooms = 0usize;

    if ctx.reset_all_room_defaults {
        for room_default in &mode_config.room_defaults {
            if !snapshots_by_id.contains_key(room_default.room_id.as_str()) {
                missing_rooms += 1;
            }
        }
        for snap in snapshots {
            let target_state = defaults_by_room
                .get(snap.id.as_str())
                .copied()
                .or_else(|| {
                    snap.parent_id
                        .as_deref()
                        .and_then(|parent_id| defaults_by_room.get(parent_id).copied())
                })
                .unwrap_or(RoomModeState::Active);
            target_rooms.push((snap, target_state));
        }
    } else {
        for room_default in &mode_config.room_defaults {
            if !snapshots_by_id.contains_key(room_default.room_id.as_str()) {
                missing_rooms += 1;
            }
        }
        for snap in snapshots {
            let target_state = defaults_by_room.get(snap.id.as_str()).copied().or_else(|| {
                snap.parent_id
                    .as_deref()
                    .and_then(|parent_id| defaults_by_room.get(parent_id).copied())
            });
            if let Some(target_state) = target_state {
                target_rooms.push((snap, target_state));
            }
        }
    }

    for (snap, configured_target_state) in target_rooms {
        let target_state = room_state_for_mood_setting(
            ctx.power_save,
            &snap.profile_settings,
            configured_target_state,
        );
        let current_state = persistent_room_state_for_settings(
            ctx.power_save,
            &snap.profile_settings,
            snap.hard_off,
            snap.mood_active,
            snap.soft_off,
        );
        let reset_offsets = ctx.reset_all_room_defaults
            && (snap.time_offset_minutes.abs() > f32::EPSILON
                || snap.brightness_offset.abs() > f32::EPSILON);
        let reassert_hard_off = ctx.reassert_hard_off_defaults
            && target_state == RoomModeState::HardOff
            && current_state == RoomModeState::HardOff;
        if current_state == target_state && !reset_offsets && !reassert_hard_off {
            continue;
        }

        let Ok((soft_off, mood_active, hard_off)) = room_flags_for_target_state(target_state)
        else {
            warn!(
                target: "cmd",
                "active_mode_apply: ignoring invalid room default state for room '{}'",
                snap.id
            );
            continue;
        };

        runtime.restore_room_state(
            &snap.id,
            RestoredRoomState {
                rhythm_enabled: if soft_off || mood_active {
                    true
                } else {
                    snap.rhythm_enabled
                },
                disabled: snap.disabled,
                time_offset_minutes: if ctx.reset_all_room_defaults {
                    0.0
                } else {
                    snap.time_offset_minutes
                },
                brightness_offset: if ctx.reset_all_room_defaults {
                    0.0
                } else {
                    snap.brightness_offset
                },
                soft_off,
                mood_active,
                standby_enabled: snap.standby_enabled,
                hard_off,
                profile_settings: snap.profile_settings.clone(),
            },
        );

        match target_state {
            RoomModeState::Active | RoomModeState::Mood | RoomModeState::Standby => {
                lights_on_updates.push((snap.id.clone(), true));
                non_hard_off_changed_room_ids.push(snap.id.clone());
            }
            RoomModeState::HardOff => {
                lights_on_updates.push((snap.id.clone(), false));
                if snap.parent_id.is_some() {
                    attached_hard_off_node_ids.push(snap.id.clone());
                    changed_room_ids.push(snap.id.clone());
                    continue;
                }
                let transition_ms = ctx
                    .transition
                    .and_then(|config| {
                        resolve_mode_transition_duration_ms_for_room_from_parts(
                            config,
                            ctx.lighting,
                            RoomLightingInput::from_snapshot(snap, RoomModeState::HardOff),
                            ctx.transition_started_at,
                        )
                    })
                    .filter(|ms| *ms > 0);
                if empty_topology_rooms.contains(&snap.id) {
                    empty_hard_off_room_ids.push(snap.id.clone());
                } else {
                    hard_off_rooms.push((snap.id.clone(), transition_ms));
                }
            }
            RoomModeState::Wake | RoomModeState::Warning => {}
        }

        changed_room_ids.push(snap.id.clone());
    }

    if let Ok(mut s) = state.lock() {
        for (room_id, lights_on) in lights_on_updates {
            let cache_key = room_id.clone();
            s.room_observed_power.insert(
                cache_key,
                ObservedPowerState::new(lights_on, ObservedPowerSource::SemanticOverride),
            );
        }
    }

    // Broadcast the engine-state change immediately for non-HardOff targets.
    // The HardOff branch below emits its own event after queueing the off
    // dispatch. For Active/Mood targets the lighting command is queued
    // asynchronously via dispatch_room_commands and only emits its own event
    // when the worker runs, which can be many seconds later (production logs
    // show ~9s on a busy mode change). Without this synchronous emit, every
    // SSE consumer keeps showing the previous state — typically `HardOff` —
    // until that worker finally fires.
    for room_id in &non_hard_off_changed_room_ids {
        emit_node_state_event_after_apply(state, runtime, room_id);
    }

    for node_id in &attached_hard_off_node_ids {
        queue_motion_timer_clear(state, node_id);
        emit_node_state_event_after_apply(state, runtime, node_id);
    }

    for room_id in &empty_hard_off_room_ids {
        queue_motion_timer_clear(state, room_id);
        emit_node_state_event_after_apply(state, runtime, room_id);
    }
    if !empty_hard_off_room_ids.is_empty() {
        debug!(
            target: "cmd",
            "active_mode_apply: skipped physical hard-off for {} empty topology rooms",
            empty_hard_off_room_ids.len()
        );
    }

    if !hard_off_rooms.is_empty() {
        let work_items: Vec<_> = hard_off_rooms
            .iter()
            .map(|(room_id, transition_ms)| WorkItem::LightsOffRoom {
                command_id: crate::logging::next_command_id("mode-hard-off"),
                node_id: room_id.clone(),
                transition_ms: *transition_ms,
                dispatch_spacing: default_http_batch_dispatch_spacing(),
                dispatch_generation: ctx.dispatch_generation,
            })
            .collect();
        let queued = match queue_node_dispatch_work_items(
            state,
            "active_mode_apply",
            work_items,
            default_http_batch_dispatch_spacing(),
        ) {
            Ok(queued) => queued,
            Err(e) => {
                warn!(
                    target: "cmd",
                    "active_mode_apply: failed to queue hard-off dispatches: {}",
                    e
                );
                false
            }
        };

        for (room_id, transition_ms) in &hard_off_rooms {
            queue_motion_timer_clear(state, room_id);
            if queued {
                update_lights_on_cache_for_runtime_node(state, runtime, room_id, false);
            } else if let Err(e) = runtime.lights_off_room(room_id, *transition_ms) {
                warn!(
                    target: "cmd",
                    "active_mode_apply: lights_off for '{}' failed after room default apply: {}",
                    room_id,
                    e
                );
            }
            emit_node_state_event_after_apply(state, runtime, room_id);
        }
    }

    if !changed_room_ids.is_empty() || missing_rooms > 0 {
        debug!(
            target: "cmd",
            "active_mode_apply: applied {} room defaults for {:?}, {} missing room ids",
            changed_room_ids.len(),
            ctx.lighting.mode,
            missing_rooms
        );
    }

    !changed_room_ids.is_empty()
}

fn apply_room_commands_inline(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    room_commands: Vec<(String, LightingCommand)>,
    phase_gap: Duration,
    dispatch_generation: u64,
) {
    let room_count = room_commands.len();

    for (idx, (room_id, command)) in room_commands.into_iter().enumerate() {
        if !crate::periodic::light_dispatch_generation_current(state, dispatch_generation) {
            tracing::debug!(
                target: "cmd",
                event = "apply_node_command_skipped",
                node_id = %room_id,
                dispatch_generation,
                reason = "stale_dispatch_generation",
                "Skipping stale inline room command"
            );
            return;
        }
        log_room_command_dispatch(runtime.as_ref(), &room_id, &command);
        if let Err(e) = runtime.apply_room_command(&room_id, command) {
            warn!(target: "cmd", "active_mode_apply: room '{}' failed: {}", room_id, e);
            continue;
        }
        update_lights_on_cache_for_runtime_node(state, runtime, &room_id, true);
        emit_node_state_event_after_apply(state, runtime, &room_id);
        if idx + 1 < room_count && !phase_gap.is_zero() {
            std::thread::sleep(phase_gap);
        }
    }
}

fn room_command_log_label(runtime: &dyn RuntimeHandle, room_id: &str) -> String {
    runtime
        .engine_room_snapshot(room_id)
        .map(|room| {
            if room.name != room.id {
                format!("{} ({})", room.name, room.id)
            } else {
                room.id
            }
        })
        .unwrap_or_else(|| room_id.to_string())
}

fn room_command_log_payload(command: &LightingCommand) -> String {
    command.diagnostic_payload()
}

pub(crate) fn log_room_command_dispatch(
    runtime: &dyn RuntimeHandle,
    room_id: &str,
    command: &LightingCommand,
) {
    info!(
        target: "cmd",
        "room_command_dispatch: room={} {}",
        room_command_log_label(runtime, room_id),
        room_command_log_payload(command),
    );
}

fn queue_node_dispatch_work_items(
    state: &SharedState,
    dispatch_label: &str,
    work_items: Vec<WorkItem>,
    dispatch_spacing: Duration,
) -> Result<bool> {
    if work_items.is_empty() {
        return Ok(true);
    }

    let tx = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.work_tx.clone()
    };

    let Some(tx) = tx else {
        return Ok(false);
    };

    let item_count = work_items.len();
    let error_label = dispatch_label.to_string();
    let thread_label = error_label.clone();
    let dispatcher_state = state.clone();
    std::thread::Builder::new()
        .name("node-dispatch".to_string())
        .spawn(move || {
            for item in work_items {
                if send_work_item_with_pending(&dispatcher_state, &tx, item).is_err() {
                    warn!(
                        target: "cmd",
                        "{}: node dispatch worker disconnected",
                        thread_label
                    );
                    return;
                }
            }
            debug!(
                target: "cmd",
                "{}: queued {} node dispatch work items spacing_ms={}",
                thread_label,
                item_count,
                dispatch_spacing.as_millis()
            );
        })
        .map_err(|e| anyhow::anyhow!("{}: failed to spawn node dispatcher: {}", error_label, e))?;

    Ok(true)
}

fn queue_node_dispatch_batch(
    state: &SharedState,
    dispatch_label: &str,
    mut work_items: Vec<WorkItem>,
    persist_after: bool,
    dispatch_spacing: Duration,
) -> Result<()> {
    if persist_after && !work_items.is_empty() {
        work_items.push(WorkItem::DeferredPersist {
            node_id: dispatch_label.to_string(),
        });
    }

    let queued =
        queue_node_dispatch_work_items(state, dispatch_label, work_items, dispatch_spacing)?;
    if queued {
        Ok(())
    } else {
        Err(anyhow::anyhow!("Node dispatch queue unavailable"))
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum NodeColorScope {
    #[default]
    Auto,
    Preview,
    Mood,
}

#[derive(Debug, Clone, Copy)]
pub struct NodeColorUpdate {
    pub rgb: Rgb,
    pub xy: Option<XyColor>,
    pub brightness: Option<u8>,
    pub transition_ms: Option<u32>,
    pub scope: NodeColorScope,
}

fn node_mood_profile_id(node_id: &str) -> String {
    let mut safe_id = String::with_capacity(node_id.len());
    for byte in node_id.bytes() {
        let ch = byte as char;
        if ch.is_ascii_alphanumeric() || ch == '-' {
            safe_id.push(ch);
        } else {
            safe_id.push_str(&format!("_{byte:02x}"));
        }
    }
    format!("node_mood_{}", safe_id)
}

fn node_mood_profile_name(snapshot: &rhythm_core::NodeSnapshot) -> String {
    if snapshot.name.trim().is_empty() || snapshot.name == snapshot.id {
        "Mood".to_string()
    } else {
        format!("{} Mood", snapshot.name)
    }
}

fn node_mood_scene_id(node_id: &str) -> String {
    let mut safe_id = String::with_capacity(node_id.len());
    for byte in node_id.bytes() {
        let ch = byte as char;
        if ch.is_ascii_alphanumeric() || ch == '-' {
            safe_id.push(ch);
        } else {
            safe_id.push_str(&format!("-{byte:02x}"));
        }
    }
    format!("node-mood-scene-{}", safe_id)
}

fn node_mood_scene_name(snapshot: &rhythm_core::NodeSnapshot) -> String {
    if snapshot.name.trim().is_empty() || snapshot.name == snapshot.id {
        "Mood".to_string()
    } else {
        format!("{} Mood", snapshot.name)
    }
}

fn set_fixed_profile_brightness(config: &mut LightProfileConfig, brightness: u8) {
    let brightness = brightness.clamp(1, 100);
    config.min_brightness = brightness;
    config.max_brightness = brightness;
    config.max_dim_steps = 1;
    if let rhythm_core::LightCurveShape::Constant { brightness, .. } = &mut config.curve {
        *brightness = 1.0;
    }
}

fn base_mood_profile_config_locked(
    s: &AppState,
    snapshot: &rhythm_core::NodeSnapshot,
    profile_id: &str,
) -> LightProfileConfig {
    if let Some(config) = s.light_profile_config(profile_id).cloned() {
        return config;
    }

    let mode_configs = s.mode_configs();
    resolved_profile_config_for_room_state_from_parts(
        RoomLightingContext {
            light_profile_configs: &s.light_profile_configs,
            mode_configs: &mode_configs,
            mode: s.active_mode,
            solar_noon: s.solar_noon_hour(),
            latitude: s.latitude,
            longitude: s.longitude,
            timezone_name: s.timezone_name.as_deref(),
            utc_offset: s.utc_offset_hours,
        },
        &snapshot.profile_settings,
        RoomModeState::Mood,
    )
}

fn update_node_mood_profile<F>(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    node_id: &str,
    snapshot: &rhythm_core::NodeSnapshot,
    persist: bool,
    mut update: F,
) -> Result<()>
where
    F: FnMut(&mut LightProfileConfig),
{
    let (profile, profile_settings) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let profile_id = node_mood_profile_id(node_id);
        let mut profile = base_mood_profile_config_locked(&s, snapshot, &profile_id);
        profile.id = profile_id.clone();
        profile.name = node_mood_profile_name(snapshot);
        update(&mut profile);
        profile.normalize_float_precision();
        s.set_light_profile_config(profile.clone());
        if persist {
            persist_light_profiles_locked(&s);
        }

        let mut profile_settings = snapshot.profile_settings.clone();
        profile_settings.mood_enabled = Some(true);
        profile_settings.mood_profile_id = Some(profile_id);
        (profile, profile_settings)
    };

    runtime.set_light_profile_config(profile)?;

    let mut restored = RestoredNodeState::from(snapshot);
    restored.rhythm_enabled = true;
    restored.soft_off = false;
    restored.mood_active = true;
    restored.hard_off = false;
    restored.profile_settings = profile_settings;
    runtime.restore_node_state(node_id, restored);
    clear_room_mode_transition(state, node_id);
    queue_motion_timer_clear(state, node_id);
    runtime.mood_tick_room(node_id)?;
    update_lights_on_cache_for_runtime_node(state, runtime, node_id, true);
    emit_node_state_event_after_apply(state, runtime, node_id);

    if persist {
        persist_rooms(state);
    }

    Ok(())
}

fn do_set_node_mood_brightness(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    node_id: &str,
    snapshot: &rhythm_core::NodeSnapshot,
    brightness: u8,
    persist: bool,
) -> Result<String> {
    update_node_mood_profile(state, runtime, node_id, snapshot, persist, |profile| {
        set_fixed_profile_brightness(profile, brightness)
    })?;

    build_node_state(state, node_id).and_then(|node_state| {
        serde_json::to_string(&node_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
    })
}

fn first_scene_output_for_node(scene: &SceneDefinition, node_id: &str) -> Option<LightSceneOutput> {
    let layer = scene.light.as_ref()?;
    layer
        .entries
        .iter()
        .find(|entry| entry.target.node_id() == node_id)
        .map(|entry| entry.output.clone())
        .or_else(|| layer.palette.first().cloned())
        .or_else(|| layer.default_output.clone())
}

fn first_scene_output_for_room_scope(
    scene: &SceneDefinition,
    scope_node_ids: &BTreeSet<String>,
) -> Option<LightSceneOutput> {
    let layer = scene.light.as_ref()?;
    layer
        .default_output
        .clone()
        .or_else(|| layer.palette.first().cloned())
        .or_else(|| {
            layer
                .entries
                .iter()
                .find(|entry| scope_node_ids.contains(entry.target.node_id()))
                .map(|entry| entry.output.clone())
        })
}

fn mood_scene_color_output(
    existing: Option<LightSceneOutput>,
    rgb: Rgb,
    xy: XyColor,
    brightness: Option<u8>,
    transition_ms: Option<u32>,
) -> LightSceneOutput {
    LightSceneOutput {
        power: LightScenePower::On,
        brightness: brightness
            .or_else(|| existing.as_ref().map(|output| output.brightness))
            .unwrap_or(1)
            .clamp(1, 100),
        color: Some(LightSceneColor::RgbXy { rgb, xy }),
        transition_ms: transition_ms.or_else(|| existing.and_then(|output| output.transition_ms)),
    }
}

fn update_scene_brightness_for_target(
    scene: &mut SceneDefinition,
    scope_node_ids: &BTreeSet<String>,
    snapshot: &rhythm_core::NodeSnapshot,
    node_id: &str,
    brightness: u8,
) -> Result<()> {
    let layer = scene
        .light
        .as_mut()
        .ok_or_else(|| anyhow::anyhow!("Scene '{}' has no light layer", scene.id))?;
    let mut updated = false;
    if snapshot.kind.is_room() {
        if let Some(default_output) = &mut layer.default_output {
            default_output.power = LightScenePower::On;
            default_output.brightness = brightness;
            updated = true;
        }
        for output in &mut layer.palette {
            output.power = LightScenePower::On;
            output.brightness = brightness;
            updated = true;
        }
        for entry in &mut layer.entries {
            if scope_node_ids.contains(entry.target.node_id()) {
                entry.output.power = LightScenePower::On;
                entry.output.brightness = brightness;
                updated = true;
            }
        }
    } else if let Some(entry) = layer
        .entries
        .iter_mut()
        .find(|entry| entry.target.node_id() == node_id)
    {
        entry.output.power = LightScenePower::On;
        entry.output.brightness = brightness;
        updated = true;
    } else if let Some(mut output) = layer
        .palette
        .first()
        .cloned()
        .or_else(|| layer.default_output.clone())
    {
        output.power = LightScenePower::On;
        output.brightness = brightness;
        layer.entries.push(LightSceneEntry {
            target: LightSceneTargetRef::Node {
                node_id: node_id.to_string(),
            },
            output,
        });
        updated = true;
    }

    if !updated {
        return Err(anyhow::anyhow!(
            "Scene '{}' has no light output to update for '{}'",
            scene.id,
            node_id
        ));
    }
    scene.normalize();
    Ok(())
}

struct MoodSceneColorUpdate {
    rgb: Rgb,
    xy: XyColor,
    brightness: Option<u8>,
    transition_ms: Option<u32>,
    persist: bool,
}

fn update_node_mood_scene_color(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    node_id: &str,
    snapshot: &rhythm_core::NodeSnapshot,
    update: MoodSceneColorUpdate,
) -> Result<()> {
    let node_scene_id = node_mood_scene_id(node_id);
    let (scene_id, seed_scene, current_scene_is_node_scene) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let current_scene_id = snapshot
            .profile_settings
            .mood_scene_id
            .as_ref()
            .filter(|scene_id| s.scenes.contains_key(*scene_id))
            .cloned();
        let current_scene_is_node_scene = current_scene_id
            .as_deref()
            .is_some_and(|scene_id| scene_id == node_scene_id);
        let seed_scene = current_scene_id
            .as_ref()
            .and_then(|scene_id| s.scenes.get(scene_id).cloned());
        let scene_id = current_scene_id
            .filter(|scene_id| scene_id == &node_scene_id)
            .unwrap_or_else(|| node_scene_id.clone());
        (scene_id, seed_scene, current_scene_is_node_scene)
    };

    let mut scene = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.scenes.get(&scene_id).cloned().unwrap_or(SceneDefinition {
            id: scene_id.clone(),
            name: node_mood_scene_name(snapshot),
            description: None,
            source: SceneSource::User,
            light: Some(LightSceneLayer {
                default_transition_ms: update.transition_ms,
                default_output: None,
                palette: Vec::new(),
                entries: Vec::new(),
            }),
            extensions: BTreeMap::new(),
        })
    };
    let scope_node_ids = if snapshot.kind.is_room() {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        light_scene_target_scope_node_ids(&s, runtime, node_id)
    } else {
        BTreeSet::new()
    };
    let existing_output = if snapshot.kind.is_room() {
        let node_output = first_scene_output_for_room_scope(&scene, &scope_node_ids);
        let seed_output = seed_scene
            .as_ref()
            .and_then(|scene| first_scene_output_for_room_scope(scene, &scope_node_ids));
        if current_scene_is_node_scene {
            node_output.or(seed_output)
        } else {
            seed_output.or(node_output)
        }
    } else {
        let node_output = first_scene_output_for_node(&scene, node_id);
        let seed_output = seed_scene
            .as_ref()
            .and_then(|scene| first_scene_output_for_node(scene, node_id));
        if current_scene_is_node_scene {
            node_output.or(seed_output)
        } else {
            seed_output.or(node_output)
        }
    };
    let output = mood_scene_color_output(
        existing_output,
        update.rgb,
        update.xy,
        update.brightness,
        update.transition_ms,
    );
    let layer = scene.light.get_or_insert_with(|| LightSceneLayer {
        default_transition_ms: update.transition_ms,
        default_output: None,
        palette: Vec::new(),
        entries: Vec::new(),
    });
    if snapshot.kind.is_room() {
        layer.palette.clear();
        layer.default_output = Some(output.clone());
        for entry in &mut layer.entries {
            if scope_node_ids.contains(entry.target.node_id()) {
                entry.output = mood_scene_color_output(
                    Some(entry.output.clone()),
                    update.rgb,
                    update.xy,
                    update.brightness,
                    update.transition_ms,
                );
            }
        }
    } else if let Some(entry) = layer
        .entries
        .iter_mut()
        .find(|entry| entry.target.node_id() == node_id)
    {
        entry.output = output;
    } else {
        layer.entries.push(LightSceneEntry {
            target: LightSceneTargetRef::Node {
                node_id: node_id.to_string(),
            },
            output,
        });
    }
    scene.normalize();
    let normalized_scene_id = scene.id.clone();

    {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.scenes.insert(scene.id.clone(), scene);
        if update.persist {
            persist_scenes_locked(&s);
        }
    }

    let mut profile_settings = snapshot.profile_settings.clone();
    profile_settings.mood_enabled = Some(true);
    profile_settings.mood_profile_id = None;
    profile_settings.mood_scene_id = Some(normalized_scene_id.clone());
    runtime.restore_node_state(
        node_id,
        RestoredNodeState {
            rhythm_enabled: true,
            disabled: snapshot.disabled,
            time_offset_minutes: snapshot.time_offset_minutes,
            brightness_offset: snapshot.brightness_offset,
            soft_off: false,
            mood_active: true,
            standby_enabled: snapshot.standby_enabled,
            hard_off: false,
            profile_settings,
        },
    );
    clear_room_mode_transition(state, node_id);
    queue_motion_timer_clear(state, node_id);
    do_scene_apply_inner(
        state,
        &normalized_scene_id,
        SceneApplyRequest {
            target_id: node_id.to_string(),
            transition_ms: None,
        },
        true,
        false,
        None,
    )?;
    update_lights_on_cache_for_runtime_node(state, runtime, node_id, true);
    emit_node_state_event_after_apply(state, runtime, node_id);

    if update.persist {
        persist_rooms(state);
    }

    Ok(())
}

fn update_node_mood_scene_brightness(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    node_id: &str,
    snapshot: &rhythm_core::NodeSnapshot,
    brightness: u8,
    persist: bool,
) -> Result<()> {
    let bound_scene_id = snapshot
        .profile_settings
        .mood_scene_id
        .clone()
        .ok_or_else(|| anyhow::anyhow!("Node '{}' has no mood scene", node_id))?;
    let node_scene_id = node_mood_scene_id(node_id);
    let updates_generated_scene = bound_scene_id == node_scene_id;
    let scope_node_ids = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        light_scene_target_scope_node_ids(&s, runtime, node_id)
    };
    let scene_id = if updates_generated_scene {
        bound_scene_id.clone()
    } else {
        node_scene_id
    };

    {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let mut scene = s
            .scenes
            .get(&bound_scene_id)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("Scene '{}' not found", bound_scene_id))?;
        if !updates_generated_scene {
            scene.id = scene_id.clone();
            scene.name = node_mood_scene_name(snapshot);
            scene.description = None;
            scene.source = SceneSource::User;
        }
        update_scene_brightness_for_target(
            &mut scene,
            &scope_node_ids,
            snapshot,
            node_id,
            brightness,
        )?;
        s.scenes.insert(scene_id.clone(), scene);
        if persist {
            persist_scenes_locked(&s);
        }
    }

    if !updates_generated_scene {
        let mut profile_settings = snapshot.profile_settings.clone();
        profile_settings.mood_enabled = Some(true);
        profile_settings.mood_profile_id = None;
        profile_settings.mood_scene_id = Some(scene_id.clone());
        runtime.restore_node_state(
            node_id,
            RestoredNodeState {
                rhythm_enabled: true,
                disabled: snapshot.disabled,
                time_offset_minutes: snapshot.time_offset_minutes,
                brightness_offset: snapshot.brightness_offset,
                soft_off: false,
                mood_active: true,
                standby_enabled: snapshot.standby_enabled,
                hard_off: false,
                profile_settings,
            },
        );
    }

    do_scene_apply_inner(
        state,
        &scene_id,
        SceneApplyRequest {
            target_id: node_id.to_string(),
            transition_ms: None,
        },
        true,
        false,
        None,
    )?;
    update_lights_on_cache_for_runtime_node(state, runtime, node_id, true);
    emit_node_state_event_after_apply(state, runtime, node_id);

    if persist {
        persist_rooms(state);
    }

    Ok(())
}

pub fn do_set_node_color(
    state: &SharedState,
    node_id: &str,
    update: NodeColorUpdate,
    persist: bool,
) -> Result<String> {
    let xy = update
        .xy
        .unwrap_or_else(|| rhythm_core::rgb_to_xy(update.rgb));
    let brightness = update.brightness.map(|brightness| brightness.clamp(1, 100));

    let runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.hub_runtime()
    };
    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;
    let snap = runtime
        .engine_node_snapshot(node_id)
        .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;

    let persist_as_mood = match update.scope {
        NodeColorScope::Mood => true,
        NodeColorScope::Preview => false,
        NodeColorScope::Auto => room_mood_active(
            false,
            &snap.profile_settings,
            snap.hard_off,
            snap.mood_active,
            snap.soft_off,
        ),
    };

    if persist_as_mood {
        update_node_mood_scene_color(
            state,
            &runtime,
            node_id,
            &snap,
            MoodSceneColorUpdate {
                rgb: update.rgb,
                xy,
                brightness,
                transition_ms: update.transition_ms,
                persist,
            },
        )?;
        return build_node_state(state, node_id).and_then(|node_state| {
            serde_json::to_string(&node_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
        });
    }

    let command = LightingCommand::from_color(
        brightness.unwrap_or(100),
        update.rgb,
        xy,
        update.transition_ms,
    );
    log_room_command_dispatch(runtime.as_ref(), node_id, &command);
    runtime.apply_room_command(node_id, command)?;
    clear_room_mode_transition(state, node_id);
    update_lights_on_cache_for_runtime_node(state, &runtime, node_id, true);
    emit_node_state_event_after_apply(state, &runtime, node_id);
    if persist {
        persist_rooms(state);
    }

    build_node_state(state, node_id).and_then(|node_state| {
        serde_json::to_string(&node_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
    })
}

fn dispatch_room_commands(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    mut room_commands: Vec<(String, LightingCommand)>,
    cycle_duration: Duration,
    dispatch_generation: u64,
) {
    if room_commands.is_empty() {
        return;
    }

    room_commands.sort_by_key(|(room_id, _)| crate::periodic::stable_room_phase_key(room_id));
    let phase_gap = crate::periodic::dispatch_spacing(cycle_duration, room_commands.len());

    let dispatch_tx = state
        .lock()
        .ok()
        .and_then(|s| s.work_tx.clone().or_else(|| s.periodic_work_tx.clone()));

    let Some(tx) = dispatch_tx else {
        apply_room_commands_inline(
            state,
            runtime,
            room_commands,
            phase_gap,
            dispatch_generation,
        );
        return;
    };

    let room_count = room_commands.len();
    let fallback_commands = room_commands.clone();
    let dispatcher_state = state.clone();
    if let Err(e) = std::thread::Builder::new()
        .name("room-dispatch".to_string())
        .spawn(move || {
            for (idx, (node_id, command)) in room_commands.into_iter().enumerate() {
                if !crate::periodic::light_dispatch_generation_current(
                    &dispatcher_state,
                    dispatch_generation,
                ) {
                    tracing::debug!(
                        target: "cmd",
                        event = "apply_node_command_skipped",
                        node_id = %node_id,
                        dispatch_generation,
                        reason = "stale_dispatch_generation",
                        "Stopping stale room dispatcher"
                    );
                    return;
                }
                if send_work_item_with_pending(
                    &dispatcher_state,
                    &tx,
                    crate::state::WorkItem::ApplyNodeCommand {
                        command_id: crate::logging::next_command_id("apply-node-command"),
                        node_id,
                        command,
                        dispatch_spacing: phase_gap,
                        dispatch_generation,
                    },
                )
                .is_err()
                {
                    warn!(target: "cmd", "active_mode_apply: room dispatcher disconnected");
                    return;
                }
                if idx + 1 < room_count && !phase_gap.is_zero() {
                    std::thread::sleep(phase_gap);
                }
            }
        })
    {
        warn!(
            target: "cmd",
            "active_mode_apply: failed to spawn room dispatcher thread: {}",
            e
        );
        apply_room_commands_inline(
            state,
            runtime,
            fallback_commands,
            phase_gap,
            dispatch_generation,
        );
    }
}

fn build_room_command_from_values(
    values: &rhythm_core::LightingValues,
    brightness: u8,
    transition_ms: u32,
) -> LightingCommand {
    if values.is_direct_color {
        LightingCommand::from_color(brightness, values.rgb, values.xy, Some(transition_ms))
    } else {
        LightingCommand::with_transition(brightness, values.kelvin, transition_ms)
    }
}

fn resolve_room_output_for_state_at_from_parts(
    lighting: RoomLightingContext<'_>,
    room: RoomLightingInput<'_>,
    sample_at: chrono::NaiveDateTime,
) -> Option<(rhythm_core::LightingValues, u8)> {
    if room.room_state == RoomModeState::HardOff {
        return None;
    }

    let ctx = rhythm_core::curve_context_for_local_datetime(
        lighting.solar_noon,
        lighting.latitude,
        lighting.longitude,
        lighting.timezone_name,
        sample_at,
    );
    let registry = light_profile_registry_from_parts(
        lighting.light_profile_configs,
        lighting.mode_configs,
        lighting.mode,
    );
    let render_state = render_state_for_display(room.room_state);
    let values = registry.calculate_room_values(
        lighting.mode,
        render_state,
        Some(room.settings),
        &ctx,
        room.time_offset_minutes,
    );
    let adjusted_brightness =
        (values.brightness as f32 + room.brightness_offset).clamp(1.0, 100.0) as u8;
    let brightness = match render_state {
        RoomModeState::Mood | RoomModeState::Standby => values.brightness,
        RoomModeState::Warning
            if !warning_uses_custom_profile(lighting.mode_configs, lighting.mode) =>
        {
            ((adjusted_brightness as f32) * crate::event_loop::WARNING_DIM_FACTOR).clamp(1.0, 100.0)
                as u8
        }
        RoomModeState::Active | RoomModeState::Wake | RoomModeState::Warning => adjusted_brightness,
        RoomModeState::HardOff => return None,
    };

    Some((values, brightness))
}

fn resolved_profile_config_for_room_state_from_parts(
    lighting: RoomLightingContext<'_>,
    settings: &RoomProfileSettings,
    room_state: RoomModeState,
) -> LightProfileConfig {
    let active_profile_id = resolved_active_profile_id_for_mode_from_parts(
        lighting.light_profile_configs,
        lighting.mode_configs,
        lighting.mode,
    );
    let base_id = resolved_active_profile_id_for_settings_from_parts(lighting, settings);

    let mut active_config = lighting
        .light_profile_configs
        .get(base_id.as_str())
        .cloned()
        .or_else(|| {
            lighting
                .light_profile_configs
                .get(active_profile_id.as_str())
                .cloned()
        })
        .unwrap_or_else(|| factory_default_active_profile_config_for_mode(lighting.mode));
    settings.apply_to_config_for_profile(base_id.as_str(), &mut active_config);

    if room_state == RoomModeState::Active {
        return active_config;
    }

    let mode_config = mode_config_for_mode(lighting.mode_configs, lighting.mode)
        .cloned()
        .unwrap_or_else(|| ModeConfig::default_for_mode(lighting.mode));

    let room_mood_config = if room_state == RoomModeState::Mood {
        settings
            .mood_profile_id
            .as_deref()
            .and_then(|target_id| lighting.light_profile_configs.get(target_id).cloned())
    } else {
        None
    };

    room_mood_config
        .or_else(|| {
            mode_config
                .resolve_state_profile_id(room_state, active_profile_id.as_str())
                .and_then(|target_id| lighting.light_profile_configs.get(target_id).cloned())
        })
        .unwrap_or_else(|| {
            if matches!(
                room_state,
                RoomModeState::Mood | RoomModeState::Standby | RoomModeState::HardOff
            ) {
                factory_default_idle_profile_config_for_mode(lighting.mode)
            } else {
                active_config.clone()
            }
        })
}

fn resolve_mode_transition_duration_ms_for_room_from_parts(
    transition: &ModeTransitionConfig,
    lighting: RoomLightingContext<'_>,
    room: RoomLightingInput<'_>,
    transition_started_at: chrono::NaiveDateTime,
) -> Option<u32> {
    let started_at_time = transition_started_at.time();
    let started_at_hour = started_at_time.hour() as f32
        + started_at_time.minute() as f32 / 60.0
        + started_at_time.second() as f32 / 3600.0;

    if let Some(duration_ms) = transition.duration_ms.resolve(started_at_hour) {
        return Some(duration_ms);
    }

    resolved_profile_config_for_room_state_from_parts(lighting, room.settings, room.room_state)
        .fade_ms
        .resolve(started_at_hour)
        .or(Some(rhythm_core::DEFAULT_MODE_TRANSITION_DURATION_MS))
}

fn resolve_room_command_for_state_at_from_parts(
    lighting: RoomLightingContext<'_>,
    room: RoomLightingInput<'_>,
    sample_at: chrono::NaiveDateTime,
    transition_ms_override: Option<u32>,
) -> Option<LightingCommand> {
    let (values, brightness) =
        resolve_room_output_for_state_at_from_parts(lighting, room, sample_at)?;
    let transition_ms = transition_ms_override.unwrap_or(values.transition_ms);
    Some(build_room_command_from_values(
        &values,
        brightness,
        transition_ms,
    ))
}

/// Snapshots every addressable settings node: rooms plus standalone light
/// devices (e.g. a roomless Matter bulb). The mode-apply path used to consult
/// `engine_all_room_snapshots`, which filters to `kind.is_room()` in production
/// and therefore silently skipped standalone devices, so manual transitions and
/// mode-config edits only reached them on the next periodic tick.
fn addressable_root_snapshots(runtime: &Arc<dyn RuntimeHandle>) -> Vec<rhythm_core::RoomSnapshot> {
    runtime
        .engine_all_effective_node_snapshots()
        .into_iter()
        .filter(|node| node.kind.is_light_addressable() && node.parent_id.is_none())
        .map(|node| rhythm_core::RoomSnapshot {
            id: node.id,
            name: node.name,
            kind: node.kind,
            parent_id: node.parent_id,
            rhythm_enabled: node.rhythm_enabled,
            disabled: node.disabled,
            time_offset_minutes: node.time_offset_minutes,
            brightness_offset: node.brightness_offset,
            soft_off: node.soft_off,
            mood_active: node.mood_active,
            standby_enabled: node.standby_enabled,
            hard_off: node.hard_off,
            profile_settings: node.profile_settings,
        })
        .collect()
}

fn addressable_node_snapshots(runtime: &Arc<dyn RuntimeHandle>) -> Vec<rhythm_core::RoomSnapshot> {
    runtime
        .engine_all_node_snapshots()
        .into_iter()
        .filter(|node| node.kind.is_light_addressable())
        .map(|node| rhythm_core::RoomSnapshot {
            id: node.id,
            name: node.name,
            kind: node.kind,
            parent_id: node.parent_id,
            rhythm_enabled: node.rhythm_enabled,
            disabled: node.disabled,
            time_offset_minutes: node.time_offset_minutes,
            brightness_offset: node.brightness_offset,
            soft_off: node.soft_off,
            mood_active: node.mood_active,
            standby_enabled: node.standby_enabled,
            hard_off: node.hard_off,
            profile_settings: node.profile_settings,
        })
        .collect()
}

struct ActiveModeOutputApply {
    previous_mode: RhythmMode,
    target_mode: RhythmMode,
    transition: Option<ModeTransitionConfig>,
    apply_scope: ModeOutputApplyScope,
    dispatch_generation: u64,
    force_observed_off_outputs: bool,
    reset_all_room_defaults: bool,
    reassert_hard_off_defaults: bool,
}

fn apply_active_mode_outputs(state: &SharedState, request: ActiveModeOutputApply) {
    let ActiveModeOutputApply {
        previous_mode,
        target_mode,
        transition,
        apply_scope,
        dispatch_generation,
        force_observed_off_outputs,
        reset_all_room_defaults,
        reassert_hard_off_defaults,
    } = request;

    let (
        runtime,
        light_profile_configs,
        mode_configs,
        solar_noon,
        latitude,
        longitude,
        utc_offset,
        timezone_name,
        mut room_observed_power,
        motion_snapshots,
        update_interval,
        power_save,
    ) = {
        let Ok(s) = state.lock() else { return };
        (
            s.hub_runtime(),
            s.light_profile_configs.clone(),
            s.mode_configs(),
            s.solar_noon_hour(),
            s.latitude,
            s.longitude,
            s.utc_offset_hours,
            s.timezone_name.clone(),
            s.room_observed_power.clone(),
            s.motion_snapshots.clone(),
            Duration::from_secs(s.runtime_config.update_interval_secs),
            s.power_save,
        )
    };

    debug!(
        target: "cmd",
        "active_mode_apply: {:?} -> {:?} transition_id={:?}",
        previous_mode,
        target_mode,
        transition.as_ref().map(|config| config.id.as_str())
    );
    let reset_motion_timers_for_outputs = previous_mode != target_mode || transition.is_some();

    let Some(runtime) = runtime else {
        if let Ok(mut s) = state.lock() {
            s.room_mode_transitions.clear();
            s.pending_mode_output_apply = true;
        }
        debug!(
            target: "cmd",
            "active_mode_apply: no runtime available, deferring {:?} room-default apply until runtime ready",
            target_mode
        );
        return;
    };

    let transition_started_at = current_local_datetime(utc_offset);
    let empty_topology_rooms = EmptyTopologyRooms::from_state(state);
    let lighting = RoomLightingContext {
        light_profile_configs: &light_profile_configs,
        mode_configs: &mode_configs,
        mode: target_mode,
        solar_noon,
        latitude,
        longitude,
        timezone_name: timezone_name.as_deref(),
        utc_offset,
    };
    // Keep internal mode/default state current for every addressable settings
    // node so a later reviewed handoff starts from the active mode. Only the
    // physical-output pass below is authority-gated.
    let default_snapshots = addressable_node_snapshots(&runtime);
    let room_defaults_changed = apply_room_mode_defaults(
        state,
        &runtime,
        &empty_topology_rooms,
        ModeDefaultApplyContext {
            lighting,
            transition: transition.as_ref(),
            transition_started_at,
            dispatch_generation,
            power_save,
            reset_all_room_defaults,
            reassert_hard_off_defaults,
        },
        &default_snapshots,
    );
    if room_defaults_changed {
        if let Ok(s) = state.lock() {
            room_observed_power = s.room_observed_power.clone();
        }
    }
    let snapshots = addressable_root_snapshots(&runtime)
        .into_iter()
        .filter(|snapshot| rhythm_automation_allowed_for_node(state, &snapshot.id))
        .collect::<Vec<_>>();
    let mut room_commands = Vec::new();
    let mut dispatch_snapshots = Vec::new();
    let mut transitioned_rooms = Vec::new();
    let mut changed_room_ids = Vec::new();
    let mut preserved_hard_off = 0usize;
    let mut empty_rooms_skipped = 0usize;
    let mut hidden_rooms = 0usize;
    let mut unresolved_rooms = 0usize;

    for snap in &snapshots {
        let room_state = room_mode_state_for_settings(
            power_save,
            &snap.profile_settings,
            snap.hard_off,
            snap.mood_active,
            snap.soft_off,
            motion_snapshots
                .get(&snap.id)
                .is_some_and(|motion| motion.warning_active),
        );

        if !apply_scope.includes(room_state) {
            continue;
        }

        // Empty user-managed rooms retain their semantic mode/default state,
        // but have no physical route. The defaults pass above already applies
        // and persists that state; do not enqueue the subsequent lighting
        // command for a controller that cannot exist.
        if empty_topology_rooms.contains(&snap.id) {
            empty_rooms_skipped += 1;
            continue;
        }

        if room_state == RoomModeState::HardOff
            && transition
                .as_ref()
                .is_some_and(|config| config.preserve_hard_off)
        {
            preserved_hard_off += 1;
            continue;
        }

        // Activating a mode makes its explicit Active room defaults
        // authoritative even when persisted semantic state already says
        // Active. That mismatch is legitimate after restart (persisted room
        // state outranks mode defaults), but observed-off filtering must not
        // then swallow the next configured Sleep -> Day wake-up. Rooms that
        // are merely Active and absent from the target mode defaults retain
        // the ordinary "do not turn on known-off lights" behavior.
        let explicitly_activated_by_mode_change = previous_mode != target_mode
            && room_state == RoomModeState::Active
            && mode_config_for_mode(&mode_configs, target_mode).is_some_and(|mode_config| {
                mode_config.room_defaults.iter().any(|room_default| {
                    room_default.room_id == snap.id && room_default.state == RoomModeState::Active
                })
            });
        let is_visible = match room_state {
            RoomModeState::Mood | RoomModeState::Standby => true,
            RoomModeState::HardOff => false,
            RoomModeState::Active | RoomModeState::Wake | RoomModeState::Warning
                if force_observed_off_outputs || explicitly_activated_by_mode_change =>
            {
                true
            }
            RoomModeState::Active | RoomModeState::Wake | RoomModeState::Warning => {
                state.lock().ok().is_some_and(|s| {
                    observed_lights_on_from_cache(
                        &s,
                        &room_observed_power,
                        &snap.id,
                        snap.kind,
                        snap.parent_id.as_deref(),
                        semantic_lights_on_override(
                            power_save,
                            &snap.profile_settings,
                            snap.hard_off,
                            snap.mood_active,
                            snap.soft_off,
                        ),
                    )
                    .unwrap_or(true)
                })
            }
        };
        if !is_visible {
            hidden_rooms += 1;
            continue;
        }

        let room_transition_ms = transition
            .as_ref()
            .and_then(|config| {
                resolve_mode_transition_duration_ms_for_room_from_parts(
                    config,
                    lighting,
                    RoomLightingInput::from_snapshot(snap, room_state),
                    transition_started_at,
                )
            })
            .unwrap_or(0);
        let sample_at =
            transition_started_at + chrono::Duration::milliseconds(i64::from(room_transition_ms));
        let Some(command) = resolve_room_command_for_state_at_from_parts(
            lighting,
            RoomLightingInput::from_snapshot(snap, room_state),
            sample_at,
            (room_transition_ms > 0).then_some(room_transition_ms),
        ) else {
            unresolved_rooms += 1;
            debug!(
                target: "cmd",
                "active_mode_apply: no command resolved for room '{}' state={:?}",
                snap.id,
                room_state
            );
            continue;
        };

        room_commands.push((snap.id.clone(), command));
        dispatch_snapshots.push(snap.clone());
        changed_room_ids.push(snap.id.clone());
        if room_transition_ms > 0 {
            transitioned_rooms.push((snap.id.clone(), room_transition_ms));
        }
    }

    let cycle_duration = (!room_commands.is_empty()).then(|| {
        mode_apply_cycle_duration(
            lighting,
            &dispatch_snapshots,
            update_interval,
            power_save,
            &room_commands,
        )
    });

    if let Ok(mut s) = state.lock() {
        s.room_mode_transitions.clear();
        if !transitioned_rooms.is_empty() {
            let now = std::time::Instant::now();
            let phase_gap = cycle_duration
                .map(|duration| crate::periodic::dispatch_spacing(duration, room_commands.len()))
                .unwrap_or(std::time::Duration::ZERO);
            let mut scheduled_room_ids: Vec<String> = room_commands
                .iter()
                .map(|(room_id, _)| room_id.clone())
                .collect();
            scheduled_room_ids
                .sort_by_key(|room_id| crate::periodic::stable_room_phase_key(room_id));
            let dispatch_offsets: HashMap<String, std::time::Duration> = scheduled_room_ids
                .into_iter()
                .enumerate()
                .map(|(idx, room_id)| {
                    let offset = phase_gap
                        .checked_mul(idx as u32)
                        .unwrap_or(std::time::Duration::ZERO);
                    (room_id, offset)
                })
                .collect();
            for (room_id, transition_ms) in &transitioned_rooms {
                let dispatch_offset = dispatch_offsets
                    .get(room_id)
                    .copied()
                    .unwrap_or(std::time::Duration::ZERO);
                let ends_at = now
                    + dispatch_offset
                    + std::time::Duration::from_millis(u64::from(*transition_ms));
                let periodic_resume_at = ends_at + update_interval;
                s.room_mode_transitions.insert(
                    room_id.clone(),
                    crate::state::RoomModeTransition {
                        ends_at,
                        periodic_resume_at,
                    },
                );
            }
        }
    }

    debug!(
        target: "cmd",
        "active_mode_apply: {} rooms scanned, {} changed, {} transitioning, {} empty, {} hidden, {} preserved hard-off, {} unresolved",
        snapshots.len(),
        changed_room_ids.len(),
        transitioned_rooms.len(),
        empty_rooms_skipped,
        hidden_rooms,
        preserved_hard_off,
        unresolved_rooms
    );
    if reset_motion_timers_for_outputs {
        for room_id in &changed_room_ids {
            queue_motion_timer_clear(state, room_id);
        }
    }
    if let Some(cycle_duration) = cycle_duration {
        dispatch_room_commands(
            state,
            &runtime,
            room_commands,
            cycle_duration,
            dispatch_generation,
        );
    }
    if let Ok(mut s) = state.lock() {
        s.pending_mode_output_apply = false;
    }
    if room_defaults_changed {
        persist_rooms(state);
    }
}

/// Apply the active mode's room defaults if a prior mode change deferred them
/// because no runtime was available. The deferral is set by
/// `apply_active_mode_outputs` when it sees no runtime (typically when the
/// periodic loop replayed a missed scheduled transition before hub bootstrap).
///
/// Callers must invoke this after a runtime becomes available and any
/// persisted room state has been restored. This is the only catch-up path
/// — routine restarts without a deferred apply leave restored room state
/// untouched.
fn apply_pending_mode_outputs_if_ready(state: &SharedState) {
    let (active_mode, transition, dispatch_generation) = {
        let Ok(mut s) = state.lock() else {
            return;
        };
        if !s.pending_mode_output_apply || s.hub_runtime().is_none() {
            return;
        }
        let active_mode = s.active_mode;
        let transition = s.last_active_mode_transition_id.as_ref().and_then(|id| {
            s.mode_transition_configs()
                .into_iter()
                .find(|config| config.id.as_str() == id.as_str())
        });
        let dispatch_generation = s.invalidate_queued_light_dispatches();
        (active_mode, transition, dispatch_generation)
    };

    info!(
        target: "cmd",
        "active_mode_apply_deferred: applying {:?} defaults transition_id={:?}",
        active_mode,
        transition.as_ref().map(|config| config.id.as_str())
    );
    apply_active_mode_outputs(
        state,
        ActiveModeOutputApply {
            previous_mode: active_mode,
            target_mode: active_mode,
            transition,
            apply_scope: ModeOutputApplyScope::all_visible(),
            dispatch_generation,
            force_observed_off_outputs: false,
            reset_all_room_defaults: false,
            reassert_hard_off_defaults: true,
        },
    );
    persist_state(state);
}

#[allow(clippy::too_many_arguments)]
fn do_settings_set_internal(
    state: &SharedState,
    power_save: Option<bool>,
    active_mode: Option<RhythmMode>,
    mode_configs: Option<Vec<ModeConfig>>,
    mode_transitions: Option<Vec<rhythm_core::ModeTransitionConfig>>,
    mode_change: Option<ModeChangeContext>,
    force_reapply_outputs: bool,
    auto_update: Option<bool>,
    update_channel: Option<UpdateChannel>,
) -> Result<String> {
    if let Some(configs) = mode_configs.as_ref() {
        validate_mode_configs(configs)?;
    }

    let requested_mode_config_count = mode_configs.as_ref().map(Vec::len);
    let requested_transition_count = mode_transitions.as_ref().map(Vec::len);
    let transition_for_apply = mode_change
        .as_ref()
        .and_then(|change| change.transition.clone());
    let (
        power_save_refresh_rooms,
        runtimes,
        active_profile_id,
        updated_mode_configs,
        previous_mode,
        selected_mode,
        mode_changed,
        reapply_scope,
        dispatch_generation,
        mode_change,
    ) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let previous_mode = s.active_mode;
        let previous_mode_config = s
            .mode_configs()
            .into_iter()
            .find(|config| config.mode == previous_mode)
            .unwrap_or_else(|| ModeConfig::default_for_mode(previous_mode));

        let mut power_save_refresh_rooms = Vec::new();
        if let Some(ps) = power_save {
            s.power_save = ps;
            info!(target: "cmd", "settings: power_save={}", ps);

            if let Some(runtime) = s.hub_runtime() {
                power_save_refresh_rooms = runtime.set_power_save(ps);
            }
        }

        if let Some(au) = auto_update {
            s.auto_update = au;
            info!(target: "cmd", "settings: auto_update={}", au);
        }

        if let Some(channel) = update_channel {
            s.update_channel = Some(channel);
            info!(target: "cmd", "settings: update_channel={}", channel.as_str());
        }

        let mut modes_updated = false;
        if let Some(configs) = mode_configs {
            s.set_mode_configs(configs);
            modes_updated = true;
        }
        if let Some(transitions) = mode_transitions {
            s.set_mode_transition_configs(transitions);
        }
        let mut mode_changed = false;
        if let Some(mode) = active_mode {
            mode_changed = s.active_mode != mode;
            if mode_changed || force_reapply_outputs {
                s.active_mode = mode;
                let change = mode_change
                    .clone()
                    .unwrap_or_else(|| ModeChangeContext::new(ModeChangeCause::Manual, None));
                s.last_active_mode_cause = change.cause;
                s.last_active_mode_transition_id = change.transition_id();
                s.last_active_mode_change_utc_ms = Some(chrono::Utc::now().timestamp_millis());
            }
        }
        let selected_mode = s.active_mode;
        let should_reapply_mode_outputs = modes_updated || mode_changed || force_reapply_outputs;
        let mut active_profile_id = None;
        let mut updated_mode_configs = None;
        let mut runtimes = Vec::new();
        let mut reapply_scope = ModeOutputApplyScope::default();
        let mut dispatch_generation = s.light_dispatch_generation;
        if should_reapply_mode_outputs {
            s.sync_active_mode_runtime_overrides();
            active_profile_id = Some(s.active_mode_profile_id());
            updated_mode_configs = Some(s.mode_configs());
            let updated_mode_config = updated_mode_configs
                .as_ref()
                .and_then(|configs| configs.iter().find(|config| config.mode == selected_mode))
                .cloned()
                .unwrap_or_else(|| ModeConfig::default_for_mode(selected_mode));
            reapply_scope = if force_reapply_outputs {
                ModeOutputApplyScope::all_visible()
            } else {
                mode_output_apply_scope(mode_changed, &previous_mode_config, &updated_mode_config)
            };
            runtimes = s
                .hubs
                .values()
                .filter_map(|hub| hub.runtime.clone())
                .collect();
        }
        if mode_changed || force_reapply_outputs || !reapply_scope.is_empty() {
            dispatch_generation = s.invalidate_queued_light_dispatches();
            tracing::debug!(
                target: "cmd",
                event = "queued_light_dispatches_invalidated",
                previous_mode = ?previous_mode,
                selected_mode = ?selected_mode,
                dispatch_generation,
                "Invalidated queued generated light dispatches"
            );
        }

        persist_settings_locked(&s);
        (
            power_save_refresh_rooms,
            runtimes,
            active_profile_id,
            updated_mode_configs,
            previous_mode,
            selected_mode,
            mode_changed,
            reapply_scope,
            dispatch_generation,
            mode_change,
        )
    };

    if let Some(count) = requested_mode_config_count {
        info!(target: "cmd", "settings: updated {} mode configs", count);
    }
    if let Some(count) = requested_transition_count {
        info!(target: "cmd", "settings: updated {} mode transitions", count);
    }
    if mode_changed || force_reapply_outputs {
        info!(
            target: "cmd",
            "settings: active_mode {:?} -> {:?} cause={:?} transition_id={:?}",
            previous_mode,
            selected_mode,
            mode_change
                .as_ref()
                .map(|change| change.cause)
                .unwrap_or(ModeChangeCause::Manual),
            mode_change.as_ref().and_then(|change| change.transition_id())
        );
    }

    if power_save == Some(true) && !power_save_refresh_rooms.is_empty() {
        let runtime = {
            let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            s.hub_runtime()
        };
        if let Some(runtime) = runtime {
            let work_items: Vec<_> = power_save_refresh_rooms
                .iter()
                .map(|room_id| WorkItem::QueuedNodeAction {
                    command_id: crate::logging::next_command_id("power-save-off"),
                    node_id: room_id.clone(),
                    action: ButtonAction::OffPress,
                    device_id: None,
                    dispatch_spacing: default_http_batch_dispatch_spacing(),
                    persist_after: false,
                })
                .collect();
            let queued = match queue_node_dispatch_work_items(
                state,
                "settings_power_save",
                work_items,
                default_http_batch_dispatch_spacing(),
            ) {
                Ok(queued) => queued,
                Err(e) => {
                    warn!(
                        target: "cmd",
                        "settings: failed to queue power-save off dispatches: {}",
                        e
                    );
                    false
                }
            };

            for room_id in &power_save_refresh_rooms {
                info!(target: "cmd", "Converting legacy soft_off room '{}' to hard_off (power_save compatibility)", room_id);
                if queued {
                    update_lights_on_cache_for_runtime_node(state, &runtime, room_id, false);
                    emit_node_state_event_after_apply(state, &runtime, room_id);
                } else {
                    let event = InputEvent::new(room_id, ButtonAction::OffPress);
                    match runtime.handle_event(&event) {
                        Ok(turned_on) => {
                            sync_active_mode_from_runtime(state, &runtime);
                            update_lights_on_cache_for_runtime_node(
                                state, &runtime, room_id, turned_on,
                            );
                            emit_node_state_event_after_apply(state, &runtime, room_id);
                        }
                        Err(e) => warn!(
                            target: "cmd",
                            "Failed to turn off room '{}': {}",
                            room_id, e
                        ),
                    }
                }
            }
        }
    }

    if let (Some(profile_id), Some(configs)) = (active_profile_id.as_deref(), updated_mode_configs)
    {
        let mut any_set = false;
        if runtimes.is_empty() {
            debug!(
                target: "cmd",
                "settings: deferred runtime mode update for profile '{}' because no runtimes are active",
                profile_id
            );
        }
        for runtime in &runtimes {
            if let Err(e) = runtime.set_mode_configs(configs.clone()) {
                warn!(target: "cmd", "Failed to update runtime mode configs: {}", e);
            }
            if runtime.set_light_profile(profile_id) {
                any_set = true;
            }
        }
        debug!(
            target: "cmd",
            "settings: propagated active mode profile '{}' to {} runtime(s)",
            profile_id,
            runtimes.len()
        );
        if !runtimes.is_empty() && !any_set {
            return Err(anyhow::anyhow!(
                "Failed to activate active mode profile '{}'",
                profile_id
            ));
        }
        if !reapply_scope.is_empty() {
            let force_observed_off_outputs =
                force_reapply_outputs && transition_for_apply.is_some();
            let reset_all_room_defaults =
                force_reapply_outputs && !mode_changed && transition_for_apply.is_some();
            apply_active_mode_outputs(
                state,
                ActiveModeOutputApply {
                    previous_mode,
                    target_mode: selected_mode,
                    transition: transition_for_apply,
                    apply_scope: reapply_scope,
                    dispatch_generation,
                    force_observed_off_outputs,
                    reset_all_room_defaults,
                    reassert_hard_off_defaults: mode_changed || force_reapply_outputs,
                },
            );
        } else {
            debug!(
                target: "cmd",
                "settings: mode config update did not affect visible room states"
            );
        }
    }

    if mode_changed || force_reapply_outputs {
        let epoch_ms = state
            .lock()
            .ok()
            .and_then(|s| s.last_active_mode_change_utc_ms)
            .unwrap_or_else(|| chrono::Utc::now().timestamp_millis());
        let (cause, transition_id) = mode_change
            .as_ref()
            .map(|change| (change.cause, change.transition_id()))
            .unwrap_or((ModeChangeCause::Manual, None));
        crate::state::emit_server_event(
            state,
            crate::server_event::ServerEvent::ModeChanged {
                active: selected_mode,
                cause,
                transition_id,
                epoch_ms,
            },
        );
    }

    let settings = build_settings_dto(state)?;
    crate::state::emit_server_event(
        state,
        crate::server_event::ServerEvent::SettingsChanged {
            settings: settings.clone(),
        },
    );

    serde_json::to_string(&settings).map_err(|e| anyhow::anyhow!("serialize: {}", e))
}

/// Enable or disable Rhythm's autonomous light breaker.
pub fn do_light_breaker_set(state: &SharedState, enabled: bool) -> Result<String> {
    let (dto, changed, dispatch_generation) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let changed = s.light_breaker_enabled != enabled;
        s.light_breaker_enabled = enabled;
        let dispatch_generation = if changed {
            Some(s.invalidate_queued_light_dispatches())
        } else {
            None
        };
        persist_settings_locked(&s);
        (
            build_light_breaker_dto_inner(&s),
            changed,
            dispatch_generation,
        )
    };

    if changed {
        info!(
            target: "cmd",
            "light_breaker: enabled={} dispatch_generation={:?}",
            enabled, dispatch_generation
        );
        crate::state::emit_server_event(
            state,
            crate::server_event::ServerEvent::LightBreakerChanged {
                light_breaker: dto.clone(),
            },
        );
    }

    serde_json::to_string(&dto).map_err(|e| anyhow::anyhow!("serialize: {}", e))
}

/// Select the plan-based light runtime.
pub fn do_light_runtime_settings_set(
    state: &SharedState,
    runtime_kind: LightRuntimeKind,
) -> Result<String> {
    let (settings, changed, dispatch_generation) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let runtime_kind = s
            .light_runtime_registry
            .parse_runtime_kind(runtime_kind.as_str())?;
        let changed = s.light_runtime_kind != runtime_kind;
        let dispatch_generation = if changed {
            crate::light_runtime::reset_light_runtime_for_kind(&mut s, runtime_kind.clone());
            Some(s.invalidate_queued_light_dispatches())
        } else {
            None
        };
        persist_settings_locked(&s);
        (build_settings_dto_inner(&s), changed, dispatch_generation)
    };

    if changed {
        info!(
            target: "cmd",
            "light_runtime: selected={} dispatch_generation={:?}",
            runtime_kind.as_str(),
            dispatch_generation
        );
    }

    crate::state::emit_server_event(
        state,
        crate::server_event::ServerEvent::SettingsChanged {
            settings: settings.clone(),
        },
    );

    serde_json::to_string(&settings).map_err(|e| anyhow::anyhow!("serialize: {}", e))
}

/// Select the active light runtime and return the runtime selector resource.
pub fn do_light_runtime_set(state: &SharedState, runtime_kind: LightRuntimeKind) -> Result<String> {
    let (resolved_kind, changed) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let resolved_kind = s
            .light_runtime_registry
            .parse_runtime_kind(runtime_kind.as_str())?;
        let changed = s.light_runtime_kind != resolved_kind;
        (resolved_kind, changed)
    };

    do_light_runtime_settings_set(state, resolved_kind)?;
    let initial_apply = changed.then(|| queue_light_runtime_initial_apply(state));

    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let mut dto = build_light_runtime_dto_inner(&s);
    dto.initial_apply = initial_apply;
    serde_json::to_string(&dto).map_err(|e| anyhow::anyhow!("serialize light runtime: {}", e))
}

fn queue_light_runtime_initial_apply(state: &SharedState) -> LightRuntimeInitialApplyDto {
    match try_queue_light_runtime_initial_apply(state, default_http_batch_dispatch_spacing()) {
        Ok(apply) => apply,
        Err(error) => {
            warn!(
                target: "cmd",
                "light_runtime: initial apply was not queued: {}",
                error
            );
            LightRuntimeInitialApplyDto {
                queued: false,
                dispatch_count: 0,
                dispatch_spacing_ms: 0,
                estimated_dispatch_ms: 0,
                error: Some(error.to_string()),
            }
        }
    }
}

fn try_queue_light_runtime_initial_apply(
    state: &SharedState,
    dispatch_spacing: Duration,
) -> Result<LightRuntimeInitialApplyDto> {
    let runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.hub_runtime()
            .ok_or_else(|| anyhow::anyhow!("no runtime is available"))?
    };
    let mut node_snapshots = runtime.engine_all_effective_node_snapshots();
    node_snapshots.retain(|snap| !crate::topology::is_internal_light_node_id(&snap.id));
    let (dispatch_tx, dispatch_generation, dispatch_nodes) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (
            s.periodic_work_tx.clone().or_else(|| s.work_tx.clone()),
            s.light_dispatch_generation,
            crate::periodic::periodic_dispatch_nodes_from_state(&s, &node_snapshots),
        )
    };
    let dispatch_count = dispatch_nodes.len();
    let dispatch_spacing_ms = dispatch_spacing.as_millis() as u64;
    let estimated_dispatch_ms =
        estimated_dispatch_duration(dispatch_count, dispatch_spacing).as_millis() as u64;
    if dispatch_count == 0 {
        return Ok(LightRuntimeInitialApplyDto {
            queued: false,
            dispatch_count,
            dispatch_spacing_ms,
            estimated_dispatch_ms,
            error: None,
        });
    }

    let command_id = crate::logging::next_command_id("runtime-initial-apply");
    let current_hour = runtime.current_hour();
    let mut last_node_index_by_emit_target = HashMap::new();
    for (idx, node) in dispatch_nodes.iter().enumerate() {
        last_node_index_by_emit_target.insert(node.emit_node_id.clone(), idx);
    }

    if let Some(tx) = dispatch_tx {
        for (idx, node) in dispatch_nodes.iter().enumerate() {
            let emit_parent_node_id = last_node_index_by_emit_target
                .get(&node.emit_node_id)
                .is_some_and(|last_idx| *last_idx == idx)
                .then_some(node.emit_node_id.as_str())
                .filter(|emit_id| *emit_id != node.settings_node_id);
            if !crate::periodic::enqueue_periodic_tick(
                state,
                &tx,
                crate::periodic::PeriodicTickEnqueue {
                    command_id: &command_id,
                    node_id: &node.node_id,
                    settings_node_id: &node.settings_node_id,
                    dispatch_generation,
                    current_hour,
                    emit_parent_node_id,
                    dispatch_spacing,
                },
            ) {
                return Err(anyhow::anyhow!("Node dispatch queue full"));
            }
        }
        return Ok(LightRuntimeInitialApplyDto {
            queued: true,
            dispatch_count,
            dispatch_spacing_ms,
            estimated_dispatch_ms,
            error: None,
        });
    }

    for (idx, node) in dispatch_nodes.iter().enumerate() {
        crate::light_runtime::run_selected_light_runtime_event(
            state,
            runtime_event_for_light_runtime_initial_apply(
                &node.node_id,
                &node.settings_node_id,
                current_hour,
                &command_id,
            ),
        )?;
        crate::periodic::post_tick_node(state, &runtime, &node.settings_node_id);
        let emit_parent_node_id = last_node_index_by_emit_target
            .get(&node.emit_node_id)
            .is_some_and(|last_idx| *last_idx == idx)
            .then_some(node.emit_node_id.as_str())
            .filter(|emit_id| *emit_id != node.settings_node_id);
        if let Some(emit_parent_node_id) = emit_parent_node_id {
            crate::periodic::post_tick_node(state, &runtime, emit_parent_node_id);
        }
    }

    Ok(LightRuntimeInitialApplyDto {
        queued: false,
        dispatch_count,
        dispatch_spacing_ms,
        estimated_dispatch_ms,
        error: None,
    })
}

fn runtime_event_for_light_runtime_initial_apply(
    node_id: &str,
    settings_node_id: &str,
    current_hour: f32,
    command_id: &str,
) -> RuntimeEvent {
    RuntimeEvent::PeriodicTick(TickContext {
        node_id: node_id.to_string(),
        hour: current_hour as f64,
        epoch_ms: Some(current_epoch_ms().min(i64::MAX as u64) as i64),
        metadata: [
            (
                "source_node_id".to_string(),
                serde_json::json!(settings_node_id),
            ),
            ("command_id".to_string(), serde_json::json!(command_id)),
            (
                "reason".to_string(),
                serde_json::json!("light_runtime_initial_apply"),
            ),
        ]
        .into_iter()
        .collect(),
    })
}

/// Update global settings (partial: only provided fields are changed).
pub fn do_settings_set(
    state: &SharedState,
    power_save: Option<bool>,
    active_mode: Option<RhythmMode>,
    mode_configs: Option<Vec<ModeConfig>>,
    mode_transitions: Option<Vec<rhythm_core::ModeTransitionConfig>>,
    auto_update: Option<bool>,
    update_channel: Option<UpdateChannel>,
) -> Result<String> {
    do_settings_set_internal(
        state,
        power_save,
        active_mode,
        mode_configs,
        mode_transitions,
        active_mode.map(|mode| {
            let previous_mode = state.lock().ok().map(|s| s.active_mode).unwrap_or(mode);
            ModeChangeContext::new(
                ModeChangeCause::Manual,
                matching_mode_transition(state, previous_mode, mode, ModeTransitionTrigger::Manual),
            )
        }),
        false,
        auto_update,
        update_channel,
    )
}

/// Update mode state and policy (partial: only provided fields are changed).
pub fn do_mode_set(
    state: &SharedState,
    active_mode: Option<RhythmMode>,
    mode_configs: Option<Vec<ModeConfig>>,
) -> Result<String> {
    let mode_change = active_mode.map(|mode| {
        let previous_mode = state.lock().ok().map(|s| s.active_mode).unwrap_or(mode);
        ModeChangeContext::new(
            ModeChangeCause::Manual,
            matching_mode_transition(state, previous_mode, mode, ModeTransitionTrigger::Manual),
        )
    });
    do_settings_set_internal(
        state,
        None,
        active_mode,
        mode_configs,
        None,
        mode_change,
        false,
        None,
        None,
    )?;
    build_mode(state)
}

/// Update mode transition policy (partial: only provided fields are changed).
pub fn do_transitions_set(
    state: &SharedState,
    mode_transitions: Option<Vec<rhythm_core::ModeTransitionConfig>>,
) -> Result<String> {
    do_settings_set_internal(
        state,
        None,
        None,
        None,
        mode_transitions,
        None,
        false,
        None,
        None,
    )?;
    build_transitions(state)
}

fn validate_imported_backup_configuration(configuration: &BackupConfiguration) -> Result<()> {
    validate_mode_configs(&configuration.mode_configs)?;

    let valid_profile_ids = valid_import_profile_ids(&configuration.profiles);
    let scenes = normalized_scene_map(configuration.scenes.clone())?;
    let valid_scene_ids = valid_scene_ids_from_map(&scenes);

    for room in &configuration.rooms {
        room_flags_for_target_state(room.state)?;
        validate_room_profile_settings(
            &room.id,
            &room.room_profile,
            &valid_profile_ids,
            Some(&valid_scene_ids),
        )?;
    }

    Ok(())
}

fn valid_import_profile_ids(profiles: &[LightProfileConfig]) -> HashSet<String> {
    factory_default_light_profile_config_map()
        .into_keys()
        .chain(profiles.iter().map(|config| config.id.clone()))
        .collect()
}

fn normalized_scene_map(scenes: Vec<SceneDefinition>) -> Result<BTreeMap<String, SceneDefinition>> {
    let mut out = BTreeMap::new();
    for mut scene in scenes {
        scene.normalize();
        if scene.id.trim().is_empty() {
            return Err(anyhow::anyhow!("Scene id cannot be empty"));
        }
        validate_persisted_scene_id(&scene.id)?;
        if out.insert(scene.id.clone(), scene).is_some() {
            return Err(anyhow::anyhow!("Duplicate scene id"));
        }
    }
    Ok(out)
}

fn valid_scene_ids_from_map(scenes: &BTreeMap<String, SceneDefinition>) -> HashSet<String> {
    scenes.keys().cloned().collect()
}

fn validate_room_profile_settings(
    room_id: &str,
    room_profile: &RoomProfileSettings,
    valid_profile_ids: &HashSet<String>,
    valid_scene_ids: Option<&HashSet<String>>,
) -> Result<()> {
    if let Some(profile_id) = room_profile.profile_id.as_deref() {
        if rhythm_core::is_builtin_state_profile_id(profile_id) {
            return Err(anyhow::anyhow!(
                "Room '{}' cannot select built-in state profile '{}'",
                room_id,
                profile_id
            ));
        }
        if !valid_profile_ids.contains(profile_id) {
            return Err(anyhow::anyhow!(
                "Room '{}' references unknown light profile '{}'",
                room_id,
                profile_id
            ));
        }
    }
    if let Some(profile_id) = room_profile.mood_profile_id.as_deref() {
        if !valid_profile_ids.contains(profile_id) {
            return Err(anyhow::anyhow!(
                "Room '{}' references unknown mood light profile '{}'",
                room_id,
                profile_id
            ));
        }
    }
    for profile_id in room_profile.profile_overrides.keys() {
        if rhythm_core::is_builtin_state_profile_id(profile_id) {
            return Err(anyhow::anyhow!(
                "Room '{}' cannot override built-in state profile '{}'",
                room_id,
                profile_id
            ));
        }
        if !valid_profile_ids.contains(profile_id) {
            return Err(anyhow::anyhow!(
                "Room '{}' references unknown overridden light profile '{}'",
                room_id,
                profile_id
            ));
        }
    }
    if let Some(scene_id) = room_profile.mood_scene_id.as_deref() {
        if scene_id.trim().is_empty() {
            return Err(anyhow::anyhow!(
                "Room '{}' references an empty mood scene id",
                room_id
            ));
        }
        if let Some(valid_scene_ids) = valid_scene_ids {
            if !valid_scene_ids.contains(scene_id) && !is_native_scene_id(scene_id) {
                return Err(anyhow::anyhow!(
                    "Room '{}' references unknown mood scene '{}'",
                    room_id,
                    scene_id
                ));
            }
        }
    }

    Ok(())
}

fn imported_room_profile_patch(room: &BackupConfigurationRoom) -> RoomProfileSettingsPatch {
    RoomProfileSettingsPatch {
        clear_all: false,
        profile_id: Some(room.room_profile.profile_id.clone()),
        mood_enabled: Some(room.room_profile.mood_enabled),
        mood_profile_id: Some(room.room_profile.mood_profile_id.clone()),
        mood_scene_id: Some(room.room_profile.mood_scene_id.clone()),
        fade_ms: Some(room.room_profile.fade_ms.clone()),
        motion_timeout_secs: Some(room.room_profile.motion_timeout_secs.clone()),
        motion_activation_enabled: Some(room.room_profile.motion_activation_enabled),
        profile_overrides: Some(Some(
            room.room_profile
                .profile_overrides
                .iter()
                .map(|(profile_id, profile_override)| {
                    (profile_id.clone(), Some(profile_override.clone()))
                })
                .collect(),
        )),
        expected_effective_profile_overrides: None,
        replace_profile_overrides: true,
    }
}

fn backup_configuration_room_target_id(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    imported: &BackupConfigurationRoom,
) -> Option<String> {
    let resolved_id = resolve_node_id(state, &imported.id);
    if runtime.engine_room_snapshot(&resolved_id).is_some() {
        return Some(resolved_id);
    }

    runtime
        .engine_all_room_snapshots()
        .into_iter()
        .find(|snapshot| {
            snapshot.name == imported.name
                || snapshot.name.eq_ignore_ascii_case(imported.name.as_str())
        })
        .map(|snapshot| snapshot.id)
}

fn apply_backup_configuration_room_preferences(
    state: &SharedState,
    imported_rooms: &[BackupConfigurationRoom],
) -> (usize, usize) {
    let runtime = state.lock().ok().and_then(|s| s.hub_runtime());
    let mut applied_rooms = 0usize;
    let mut skipped_rooms = 0usize;

    if let Some(runtime) = runtime {
        for imported_room in imported_rooms {
            let Some(room_id) = backup_configuration_room_target_id(state, &runtime, imported_room)
            else {
                skipped_rooms += 1;
                info!(
                    target: "cmd",
                    "backup_configuration_import: skipped room '{}' ({}) because no local match was found",
                    imported_room.name,
                    imported_room.id
                );
                continue;
            };

            let patch = imported_room_profile_patch(imported_room);
            if let Err(e) = do_node_preferences_set(
                state,
                &room_id,
                Some(imported_room.rhythm_enabled),
                Some(imported_room.disabled),
                None,
                Some(imported_room.state),
                Some(&patch),
                false,
            ) {
                skipped_rooms += 1;
                warn!(
                    target: "cmd",
                    "backup_configuration_import: failed to apply room '{}' to '{}': {}",
                    imported_room.id,
                    room_id,
                    e
                );
                continue;
            }
            applied_rooms += 1;
        }

        if !imported_rooms.is_empty() {
            persist_rooms(state);
        }
    } else {
        skipped_rooms = imported_rooms.len();
    }

    (applied_rooms, skipped_rooms)
}

pub fn do_profile_bundle_import(
    state: &SharedState,
    payload: ProfileBundleImportPayload,
) -> Result<String> {
    let bundle = payload.into_bundle();
    if bundle.schema_version != PROFILE_BUNDLE_SCHEMA_VERSION {
        return Err(anyhow::anyhow!(
            "Unsupported profile bundle schema version: {}",
            bundle.schema_version
        ));
    }

    let profile = bundle.profile;

    let imported_profiles = profile.profiles;
    let imported_scenes = normalized_scene_map(profile.scenes)?;
    let imported_power_save = profile.power_save;
    let imported_mode_transitions = profile.mode_transitions;

    let (profiles_to_apply, runtimes) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.replace_light_profile_configs(imported_profiles);
        s.scenes = imported_scenes;
        persist_light_profiles_locked(&s);
        persist_scenes_locked(&s);
        (
            s.light_profile_configs
                .values()
                .cloned()
                .collect::<Vec<_>>(),
            s.hubs
                .values()
                .filter_map(|hub| hub.runtime.clone())
                .collect::<Vec<_>>(),
        )
    };

    for runtime in &runtimes {
        for profile in &profiles_to_apply {
            if let Err(e) = runtime.set_light_profile_config(profile.clone()) {
                warn!(
                    target: "cmd",
                    "profile_bundle_import: failed to update runtime profile '{}': {}",
                    profile.id,
                    e
                );
            }
        }
    }

    do_settings_set_internal(
        state,
        Some(imported_power_save),
        None,
        None,
        Some(imported_mode_transitions),
        None,
        false,
        None,
        None,
    )?;

    info!(
        target: "cmd",
        "profile_bundle_import: profiles={} scenes={} transitions={}",
        profiles_to_apply.len(),
        state.lock().ok().map(|s| s.scenes.len()).unwrap_or(0),
        state
            .lock()
            .ok()
            .map(|s| s.mode_transition_configs().len())
            .unwrap_or(0)
    );

    crate::state::emit_server_event(state, crate::server_event::ServerEvent::ConfigChanged);

    build_profile_bundle(state)
}

fn apply_backup_configuration(
    state: &SharedState,
    configuration: BackupConfiguration,
) -> Result<()> {
    validate_imported_backup_configuration(&configuration)?;

    let imported_profiles = configuration.profiles;
    let imported_power_save = configuration.power_save;
    let imported_light_breaker_enabled = configuration.light_breaker_enabled;
    let imported_active_mode = configuration.active_mode;
    let imported_mode_configs = configuration.mode_configs;
    let imported_mode_transitions = configuration.mode_transitions;
    let imported_scenes = normalized_scene_map(configuration.scenes)?;
    let imported_rooms = configuration.rooms;

    let (profiles_to_apply, runtimes) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.replace_light_profile_configs(imported_profiles);
        s.scenes = imported_scenes;
        persist_light_profiles_locked(&s);
        persist_scenes_locked(&s);
        (
            s.light_profile_configs
                .values()
                .cloned()
                .collect::<Vec<_>>(),
            s.hubs
                .values()
                .filter_map(|hub| hub.runtime.clone())
                .collect::<Vec<_>>(),
        )
    };

    for runtime in &runtimes {
        for profile in &profiles_to_apply {
            if let Err(e) = runtime.set_light_profile_config(profile.clone()) {
                warn!(
                    target: "cmd",
                    "backup_configuration_import: failed to update runtime profile '{}': {}",
                    profile.id,
                    e
                );
            }
        }
    }

    do_light_breaker_set(state, imported_light_breaker_enabled)?;

    do_settings_set_internal(
        state,
        Some(imported_power_save),
        Some(imported_active_mode),
        Some(imported_mode_configs),
        Some(imported_mode_transitions),
        Some(ModeChangeContext::new(ModeChangeCause::Manual, None)),
        true,
        None,
        None,
    )?;

    let (applied_rooms, skipped_rooms) =
        apply_backup_configuration_room_preferences(state, &imported_rooms);

    info!(
        target: "cmd",
        "backup_configuration_import: profiles={} scenes={} modes={} transitions={} rooms_applied={} rooms_skipped={}",
        profiles_to_apply.len(),
        state.lock().ok().map(|s| s.scenes.len()).unwrap_or(0),
        state.lock().ok().map(|s| s.mode_configs().len()).unwrap_or(0),
        state
            .lock()
            .ok()
            .map(|s| s.mode_transition_configs().len())
            .unwrap_or(0),
        applied_rooms,
        skipped_rooms
    );

    Ok(())
}

pub fn do_backup_restore(state: &SharedState, bundle: BackupBundle) -> Result<String> {
    if !matches!(
        bundle.schema_version,
        LEGACY_BACKUP_SCHEMA_VERSION
            | MOTION_ADMISSION_BACKUP_SCHEMA_VERSION
            | BACKUP_BUNDLE_SCHEMA_VERSION
    ) {
        return Err(anyhow::anyhow!(
            "Unsupported backup schema version: {}",
            bundle.schema_version
        ));
    }
    if bundle.kind != crate::bundle::BundleKind::BackupBundle {
        return Err(anyhow::anyhow!(
            "Backup restore requires kind=backup_bundle"
        ));
    }

    validate_imported_backup_configuration(&bundle.configuration)?;
    let mut installation = bundle.installation.clone();
    sanitize_nonportable_backup_installation(&mut installation);
    // Backup restore bypasses startup's persisted-state migration and commits
    // the imported topology directly. Migrate the imported graph while its
    // original configured-hub set is still available, before either the
    // authority-state commit or stored-hub bootstrap can observe it.
    migrate_legacy_backup_external_room_automation_policy(&mut installation);
    let valid_profile_ids = valid_import_profile_ids(&bundle.configuration.profiles);
    let scene_ids =
        valid_scene_ids_from_map(&normalized_scene_map(bundle.configuration.scenes.clone())?);
    for room in installation.rooms.iter() {
        validate_room_profile_settings(
            &room.id,
            &room.profile_settings,
            &valid_profile_ids,
            Some(&scene_ids),
        )?;
    }

    let require_hue_authority = preflight_backup_integration_files(state, &installation)?;

    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let should_bootstrap = (|| {
        disconnect_hubs_with_reason_under_transaction(
            state,
            crate::hub::ExternalControllerReleaseReason::BackupRestore,
        )?;
        stage_pending_hue_backup_credentials(
            state,
            &installation.hub_credentials,
            require_hue_authority,
        )?;
        restore_backup_integration_files(state, &installation.integration_files)?;
        save_backup_hub_registries_to_storage(state, &installation.hub_registries)?;

        let mut configuration = bundle.configuration.clone();
        configuration.active_mode = bundle.runtime_state.active_mode;
        apply_backup_configuration(state, configuration)?;

        restore_backup_location(state, installation.location.clone())?;
        restore_backup_installation_metadata(state, &installation)?;
        restore_backup_room_manager(state, &installation.rooms)?;
        restore_backup_runtime_state(state, &bundle.runtime_state)?;
        stage_backup_hub_credentials(state, &installation.hub_credentials, require_hue_authority)
    })();
    drop(transaction);
    let should_bootstrap = should_bootstrap?;

    // Connecting and authoritative discovery acquire the same transaction.
    // Start the ordinary stored-credential worker only after the complete
    // imported installation has crossed its durability boundary and the
    // outer lease is released.
    request_restored_hub_bootstrap(state, should_bootstrap)?;

    crate::state::emit_server_event(state, crate::server_event::ServerEvent::ConfigChanged);

    build_backup_bundle(state, false)
}

pub fn do_set_active_mode(state: &SharedState, mode: RhythmMode) -> Result<()> {
    do_set_active_mode_with_trigger(state, mode, ModeTransitionTrigger::Manual)
}

pub fn do_set_active_mode_with_trigger(
    state: &SharedState,
    mode: RhythmMode,
    trigger: ModeTransitionTrigger,
) -> Result<()> {
    let previous_mode = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .active_mode;
    let transition = matching_mode_transition(state, previous_mode, mode, trigger);
    let mode_change = ModeChangeContext::new(mode_change_cause_from_trigger(trigger), transition);
    do_settings_set_internal(
        state,
        None,
        Some(mode),
        None,
        None,
        Some(mode_change),
        false,
        None,
        None,
    )
    .map(|_| ())
}

pub fn do_trigger_transition(state: &SharedState, transition_id: &str) -> Result<String> {
    let transition = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.mode_transition_configs()
            .into_iter()
            .find(|config| config.id == transition_id)
    }
    .ok_or_else(|| anyhow::anyhow!("Unknown transition '{}'", transition_id))?;

    let mode_change = ModeChangeContext::new(ModeChangeCause::Manual, Some(transition.clone()));
    do_settings_set_internal(
        state,
        None,
        Some(transition.to_mode),
        None,
        None,
        Some(mode_change),
        true,
        None,
        None,
    )?;
    build_mode(state)
}

// ============================================================================
// Room commands
// ============================================================================

/// Parsed room data from a JSON value.
pub struct RoomParams {
    pub id: String,
    pub name: String,
    pub grouped_light_id: String,
    pub rhythm_enabled: bool,
    pub disabled: bool,
    /// Explicit room state from client. `None` preserves the existing state.
    pub state: Option<RoomModeState>,
    pub device_ids: Vec<String>,
}

impl RoomParams {
    /// Parse room parameters from a JSON value (the room object itself).
    pub fn from_json(room: &Value) -> Result<Self> {
        let id = room
            .get("id")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Missing room.id"))?
            .to_string();
        let name = room
            .get("name")
            .and_then(|v| v.as_str())
            .unwrap_or(&id)
            .to_string();
        let grouped_light_id = room
            .get("grouped_light_id")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let rhythm_enabled = room
            .get("rhythm_enabled")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let disabled = room
            .get("disabled")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let state = room
            .get("state")
            .cloned()
            .map(serde_json::from_value::<RoomModeState>)
            .transpose()
            .map_err(|_| anyhow::anyhow!("Invalid room.state"))?;
        let device_ids: Vec<String> = room
            .get("device_ids")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();

        Ok(RoomParams {
            id,
            name,
            grouped_light_id,
            rhythm_enabled,
            disabled,
            state,
            device_ids,
        })
    }
}

/// Upsert a room in registry + engine, optionally persist.
///
/// When `persist` is `false` the caller is responsible for triggering
/// persistence (e.g. via `DeferredPersistState` on the worker thread).
/// This avoids stack-heavy serde on the 12KB HTTP handler stack during
/// batch room updates.
/// Returns the room's rhythm state JSON snippet.
pub fn do_room_set(
    state: &SharedState,
    params: &RoomParams,
    hub_key: &HubKey,
    persist: bool,
    apply_runtime: bool,
) -> Result<String> {
    info!(target: "cmd", "room_set: {} '{}' gl={}", params.id, params.name, params.grouped_light_id);

    let registry = state
        .lock()
        .ok()
        .and_then(|s| s.hub_registry_for(hub_key))
        .ok_or_else(|| anyhow::anyhow!("No hub registry available for {}", hub_key))?;

    // Dedup: skip write if the targeted registry already matches.
    let (room_unchanged, room_has_new_light_device_ids) = registry
        .lock()
        .ok()
        .map(|reg| {
            let room_unchanged = reg.room_matches(
                &params.id,
                &params.name,
                &params.grouped_light_id,
                &params.device_ids,
            );
            let existing_device_ids: HashSet<String> =
                reg.devices_for_room(&params.id).into_iter().collect();
            let room_has_new_light_device_ids = params
                .device_ids
                .iter()
                .any(|device_id| !existing_device_ids.contains(device_id));
            (room_unchanged, room_has_new_light_device_ids)
        })
        .unwrap_or((false, false));
    // A restored per-hub registry can already contain this native room while
    // the canonical topology is absent (for example, a credentials/registry-
    // only legacy backup). Treat it as unchanged only after the topology
    // binding also exists; otherwise this sync is the one chance to recreate
    // the room and make its migrated automation policy effective.
    let topology_binding_exists = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .topology
        .find_by_hub_room(hub_key, &params.id)
        .is_some();
    if room_unchanged && topology_binding_exists {
        if apply_runtime {
            if let Ok(room_state) = build_room_rhythm_state(state, &params.id) {
                info!(target: "cmd", "room_set: {} unchanged, skipping persist", params.id);
                return serde_json::to_string(&room_state)
                    .map_err(|e| anyhow::anyhow!("serialize: {}", e));
            }
        } else {
            debug!(
                target: "cmd",
                "room_set: {} unchanged, skipping runtime apply during sync",
                params.id
            );
            return Ok(String::new());
        }
        // Room is in registry but not yet in engine — fall through to add it
    }

    {
        let mut reg = registry
            .lock()
            .map_err(|_| anyhow::anyhow!("hub registry lock poisoned for {}", hub_key))?;
        reg.upsert_room(
            &params.id,
            &params.name,
            &params.grouped_light_id,
            &params.device_ids,
        );
    }

    // Determine engine room ID: always use topology room IDs for the engine.
    let (engine_room_id, topology_room_created) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.topology.translate_or_create_with_status(
            hub_key,
            &params.id,
            &params.name,
            &params.grouped_light_id,
            &params.device_ids,
        )
    };
    if topology_room_created || room_has_new_light_device_ids {
        ensure_sleep_mode_hard_off_default(state, &engine_room_id);
    }

    if !apply_runtime {
        if persist {
            persist_state(state);
        }
        return Ok(String::new());
    }

    // Ensure runtime exists after topology translation so bootstrap sees the
    // latest topology-first room graph, not only hub registry state.
    let needs_runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let has_runtime = s.hubs.values().any(|h| h.runtime.is_some());
        !has_runtime && s.has_any_hub()
    };

    if needs_runtime {
        try_ensure_runtime(state)?;
    }

    // Always apply params (whether runtime was just created or pre-existing)
    let (runtime, power_save) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (s.hub_runtime(), s.power_save)
    };
    if runtime.is_none() {
        let has_any_hub = state
            .lock()
            .map_err(|_| anyhow::anyhow!("lock"))?
            .has_any_hub();
        if has_any_hub {
            return Err(anyhow::anyhow!(
                "Runtime initialization completed without installing a runtime"
            ));
        }
    }
    if let Some(runtime) = runtime {
        let existing = runtime.engine_room_snapshot(&engine_room_id);
        let had_existing = existing.is_some();
        runtime.add_room(&engine_room_id, &params.name);
        let settings_for_state = existing
            .as_ref()
            .map(|snap| snap.profile_settings.clone())
            .unwrap_or_default();
        let state_flags = params
            .state
            .map(|state| {
                room_flags_for_target_state(room_state_for_mood_setting(
                    power_save,
                    &settings_for_state,
                    state,
                ))
            })
            .transpose()?;
        let (
            rhythm_enabled,
            time_offset,
            bri_offset,
            soft_off,
            mood_active,
            standby_enabled,
            hard_off,
            profile_settings,
        ) = existing
            .map(|snap| {
                let (soft_off, mood_active, hard_off) =
                    state_flags.unwrap_or((snap.soft_off, snap.mood_active, snap.hard_off));
                (
                    params.rhythm_enabled,
                    snap.time_offset_minutes,
                    snap.brightness_offset,
                    soft_off,
                    mood_active,
                    snap.standby_enabled,
                    hard_off,
                    snap.profile_settings,
                )
            })
            .unwrap_or((
                params.rhythm_enabled,
                0.0,
                0.0,
                state_flags.unwrap_or((false, false, false)).0,
                state_flags.unwrap_or((false, false, false)).1,
                false,
                state_flags.unwrap_or((false, false, false)).2,
                RoomProfileSettings::default(),
            ));
        // Mood and Standby need rhythm enabled when present.
        let rhythm_enabled = if soft_off || mood_active {
            true
        } else {
            rhythm_enabled
        };
        debug!(
            target: "cmd",
            "room_set: engine='{}' existing={} rhythm={} disabled={} soft_off={} hard_off={} room_profile={}",
            engine_room_id,
            had_existing,
            rhythm_enabled,
            params.disabled,
            soft_off,
            hard_off,
            !profile_settings.is_empty()
        );
        runtime.restore_room_state(
            &engine_room_id,
            RestoredRoomState {
                rhythm_enabled,
                disabled: params.disabled,
                time_offset_minutes: time_offset,
                brightness_offset: bri_offset,
                soft_off,
                mood_active,
                standby_enabled,
                hard_off,
                profile_settings,
            },
        );
    }

    if persist {
        persist_state(state);
    }

    crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);

    let room_state = build_room_rhythm_state(state, &engine_room_id)?;
    serde_json::to_string(&room_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
}

// ============================================================================
// Node action commands
// ============================================================================

/// Dispatch a button action to an addressable node via the runtime engine.
///
/// Actions: on, off, toggle, rhythm_on, rhythm_off, rhythm_toggle,
/// step_up, step_down, dim_up, dim_down, reset, lights_off.
///
/// Returns the updated node state JSON, or an error.
pub fn do_node_action(
    state: &SharedState,
    node_id: &str,
    action_str: &str,
    persist: bool,
) -> Result<String> {
    let action = parse_node_action(action_str)?;

    // The neutral plan/apply path below must retain the same per-node
    // transaction boundary as RuntimeHandle::handle_event. Without this gate,
    // concurrent actions can mutate the engine in one order and dispatch I/O
    // in another. Share the preference-write gate so settings changes cannot
    // interleave with an action for the same node either.
    let node_action_lock = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.node_preference_write_locks
            .entry(node_id.to_string())
            .or_insert_with(|| Arc::new(std::sync::Mutex::new(())))
            .clone()
    };
    let _node_action_guard = node_action_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("node action lock"))?;

    let activate_direct_children =
        crate::light_runtime::button_action_activates_direct_children(action);

    info!(target: "cmd", "node_action: {} -> {:?}", node_id, action);

    let runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.hub_runtime()
    };

    let runtime = match runtime {
        Some(runtime) => runtime,
        None => {
            try_ensure_runtime(state)?;
            state
                .lock()
                .ok()
                .and_then(|s| s.hub_runtime())
                .ok_or_else(|| {
                    anyhow::anyhow!(
                        "Runtime initialization reported success but no runtime is available"
                    )
                })?
        }
    };

    let event = InputEvent::new(node_id, action);
    let outcome = match runtime.plan_input_event(&event, None)? {
        RhythmInputPlanOutcome::RequiresLightCheck => {
            let lights_on = runtime.any_lights_on(node_id)?;
            runtime.plan_input_event(&event, Some(lights_on))?
        }
        outcome => outcome,
    };
    let RhythmInputPlanOutcome::Plan {
        plan,
        turned_on,
        dispatch_records,
    } = outcome
    else {
        return Err(anyhow::anyhow!(
            "node action still required a light-state check after retry"
        ));
    };
    crate::light_runtime::apply_runtime_plan_to_handle_with_child_activation(
        state,
        crate::light_runtime::RHYTHM_ADAPTIVE_RUNTIME_ID,
        runtime.as_ref(),
        &plan,
        activate_direct_children,
    )?;
    runtime.record_rhythm_dispatches(&dispatch_records)?;
    sync_active_mode_from_runtime(state, &runtime);
    clear_room_mode_transition(state, node_id);

    update_lights_on_cache_for_runtime_node(state, &runtime, node_id, turned_on);

    {
        emit_node_state_event_after_apply(state, &runtime, node_id);
    }

    if persist {
        persist_rooms(state);
    }

    build_node_state(state, node_id).and_then(|node_state| {
        serde_json::to_string(&node_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
    })
}

fn parse_node_action(action_str: &str) -> Result<ButtonAction> {
    match action_str {
        "on" => Ok(ButtonAction::OnPress),
        "off" => Ok(ButtonAction::OffPress),
        "toggle" => Ok(ButtonAction::Toggle),
        other => ButtonAction::from_service_name(other)
            .ok_or_else(|| anyhow::anyhow!("Unknown action: {}", other)),
    }
}

pub fn queue_node_action(
    state: &SharedState,
    node_id: &str,
    action_str: &str,
    persist_after: bool,
    dispatch_spacing: Duration,
) -> Result<()> {
    let action = parse_node_action(action_str)?;
    let (runtime, tx) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (s.hub_runtime(), s.work_tx.clone())
    };
    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;
    let snapshot = runtime
        .engine_node_snapshot(node_id)
        .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;
    if !snapshot.kind.is_light_addressable() {
        return Err(anyhow::anyhow!(
            "Curve modifiers can only be set on light-addressable nodes"
        ));
    }
    let tx = tx.ok_or_else(|| anyhow::anyhow!("Node dispatch queue unavailable"))?;

    try_send_work_item_with_pending(
        state,
        &tx,
        WorkItem::QueuedNodeAction {
            command_id: crate::logging::next_command_id("node-action"),
            node_id: node_id.to_string(),
            action,
            device_id: None,
            dispatch_spacing,
            persist_after,
        },
    )
    .map_err(|e| anyhow::anyhow!("Node dispatch queue unavailable: {}", e))
}

pub fn queue_node_action_batch(
    state: &SharedState,
    actions: Vec<(String, String)>,
    persist_after: bool,
    dispatch_spacing: Duration,
) -> Result<()> {
    let runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if s.work_tx.is_none() {
            return Err(anyhow::anyhow!("Node dispatch queue unavailable"));
        }
        s.hub_runtime()
    };
    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;

    let mut work_items = Vec::with_capacity(actions.len() + usize::from(persist_after));
    for (node_id, action_str) in actions {
        let action = parse_node_action(&action_str)?;
        runtime
            .engine_node_snapshot(&node_id)
            .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;
        work_items.push(WorkItem::QueuedNodeAction {
            command_id: crate::logging::next_command_id("node-action"),
            node_id,
            action,
            device_id: None,
            dispatch_spacing,
            persist_after: false,
        });
    }

    queue_node_dispatch_batch(
        state,
        "node_action_batch",
        work_items,
        persist_after,
        dispatch_spacing,
    )
}

/// Set absolute brightness for a node (1-100).
///
/// Computes the offset so effective brightness equals the target.
/// Rhythm stays enabled — only brightness is overridden.
pub fn do_set_node_brightness(
    state: &SharedState,
    node_id: &str,
    brightness: u8,
    persist: bool,
) -> Result<String> {
    let brightness = brightness.clamp(1, 100);
    info!(target: "cmd", "set_node_brightness: {} -> {}", node_id, brightness);

    let runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.hub_runtime()
    };

    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;

    let snapshot = runtime
        .engine_node_snapshot(node_id)
        .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;
    if snapshot.mood_active && !snapshot.hard_off {
        if snapshot.profile_settings.mood_scene_id.is_some() {
            info!(
                target: "cmd",
                "set_node_brightness: {} updating mood scene brightness",
                node_id
            );
            update_node_mood_scene_brightness(
                state, &runtime, node_id, &snapshot, brightness, persist,
            )?;
            return build_node_state(state, node_id).and_then(|node_state| {
                serde_json::to_string(&node_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
            });
        }
        info!(
            target: "cmd",
            "set_node_brightness: {} updating mood profile brightness",
            node_id
        );
        return do_set_node_mood_brightness(
            state, &runtime, node_id, &snapshot, brightness, persist,
        );
    }

    runtime.set_room_brightness(node_id, brightness)?;
    clear_room_mode_transition(state, node_id);

    update_lights_on_cache_for_runtime_node(state, &runtime, node_id, true);

    {
        emit_node_state_event_after_apply(state, &runtime, node_id);
    }

    if persist {
        persist_rooms(state);
    }

    build_node_state(state, node_id).and_then(|node_state| {
        serde_json::to_string(&node_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
    })
}

