/// Set the time offset for a node directly (not additive).
///
/// Does NOT change observed power tracking — offset doesn't imply lights-on state change.
pub fn do_set_node_time_offset(
    state: &SharedState,
    node_id: &str,
    offset_minutes: f32,
    persist: bool,
) -> Result<String> {
    do_set_node_time_offset_with_spacing(
        state,
        node_id,
        offset_minutes,
        persist,
        default_http_batch_dispatch_spacing(),
    )
}

pub fn do_set_node_time_offset_with_spacing(
    state: &SharedState,
    node_id: &str,
    offset_minutes: f32,
    persist: bool,
    dispatch_spacing: Duration,
) -> Result<String> {
    info!(
        target: "cmd",
        "set_node_time_offset: {} -> {}",
        node_id,
        offset_minutes
    );

    let runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.hub_runtime()
    };

    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;

    let snap = time_offset_target_node_snapshot(runtime.as_ref(), node_id)?;
    let mut restored = RestoredNodeState::from(&snap);
    restored.time_offset_minutes = offset_minutes;
    runtime.restore_node_state(node_id, restored);

    clear_room_mode_transition(state, node_id);
    enqueue_time_offset_preview_ticks(state, &runtime, node_id, dispatch_spacing)?;

    {
        emit_node_state_event_after_apply(state, &runtime, node_id);
    }

    if persist {
        persist_rooms(state);
    }

    build_node_state(state, node_id).and_then(|node_state| {
        serde_json::to_string(&node_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
    })
}

pub fn do_set_node_time_offsets_batch_with_spacing(
    state: &SharedState,
    updates: &[(String, f32)],
    persist: bool,
    dispatch_spacing: Duration,
) -> Result<usize> {
    let runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.hub_runtime()
    };
    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;

    let mut update_snaps = Vec::with_capacity(updates.len());
    for (node_id, _) in updates {
        update_snaps.push(time_offset_target_node_snapshot(runtime.as_ref(), node_id)?);
    }

    let top_level_update_ids = time_offset_top_level_update_ids(&update_snaps);
    let mut emitted_node_ids = HashSet::new();
    for ((node_id, offset_minutes), snap) in updates.iter().zip(update_snaps.iter()) {
        if time_offset_batch_parent_covers_node(snap, &top_level_update_ids) {
            continue;
        }

        let mut restored = RestoredNodeState::from(snap);
        restored.time_offset_minutes = *offset_minutes;
        runtime.restore_node_state(node_id, restored);

        clear_room_mode_transition(state, node_id);
        if emitted_node_ids.insert(node_id.clone()) {
            emit_node_state_event_after_apply(state, &runtime, node_id);
        }
    }

    let dispatch_count = enqueue_time_offset_batch_preview_ticks(
        state,
        &runtime,
        &update_snaps,
        &top_level_update_ids,
        dispatch_spacing,
    )?;

    if persist {
        persist_rooms(state);
    }

    Ok(dispatch_count)
}

pub fn default_node_time_offset_updates(
    state: &SharedState,
    offset_minutes: f32,
) -> Result<Vec<(String, f32)>> {
    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let runtime = s
        .hub_runtime()
        .ok_or_else(|| anyhow::anyhow!("No runtime available"))?;
    let snapshots = runtime.engine_all_effective_node_snapshots();
    let mut seen = HashSet::new();
    let mut updates = Vec::new();
    for snap in snapshots {
        if !snap.kind.is_light_addressable() || snap.parent_id.is_some() {
            continue;
        }
        if !time_offset_preview_node_is_on(&s, &snap) {
            continue;
        }
        if seen.insert(snap.id.clone()) {
            updates.push((snap.id, offset_minutes));
        }
    }
    Ok(updates)
}

fn time_offset_target_node_snapshot(
    runtime: &dyn RuntimeHandle,
    node_id: &str,
) -> Result<rhythm_core::NodeSnapshot> {
    let snap = runtime
        .engine_node_snapshot(node_id)
        .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;

    if !snap.kind.is_light_addressable() {
        return Err(anyhow::anyhow!(
            "Time offsets can only be set on light-addressable nodes"
        ));
    }

    Ok(snap)
}

fn enqueue_time_offset_preview_ticks(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    node_id: &str,
    dispatch_spacing: Duration,
) -> Result<usize> {
    let target_snap = runtime
        .engine_effective_node_snapshot(node_id)
        .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;
    let dispatch_node = crate::periodic::preview_dispatch_node_for_target(&target_snap);
    enqueue_time_offset_preview_dispatch_nodes(state, runtime, dispatch_node, dispatch_spacing)
}

fn enqueue_time_offset_batch_preview_ticks(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    update_snaps: &[rhythm_core::NodeSnapshot],
    top_level_update_ids: &HashSet<String>,
    dispatch_spacing: Duration,
) -> Result<usize> {
    let dispatch_nodes = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let mut source_snaps = Vec::new();
        let mut direct_nodes = Vec::new();
        let mut seen_source = HashSet::new();
        let mut seen_direct = HashSet::new();
        for snap in update_snaps {
            if !snap.kind.is_light_addressable() {
                continue;
            }
            if time_offset_batch_parent_covers_node(snap, top_level_update_ids) {
                continue;
            }
            if snap.parent_id.is_some() {
                if seen_direct.insert(snap.id.clone()) {
                    if let Some(node) = crate::periodic::preview_dispatch_node_for_target(snap) {
                        direct_nodes.push(node);
                    }
                }
                continue;
            }
            if !time_offset_preview_node_is_on(&s, snap) {
                continue;
            }
            if seen_source.insert(snap.id.clone()) {
                source_snaps.push(snap.clone());
            }
        }
        let mut dispatch_nodes =
            crate::periodic::periodic_dispatch_nodes_from_state(&s, &source_snaps);
        dispatch_nodes.extend(direct_nodes);
        dispatch_nodes
    };

    enqueue_time_offset_preview_dispatch_nodes(state, runtime, dispatch_nodes, dispatch_spacing)
}

fn time_offset_top_level_update_ids(update_snaps: &[rhythm_core::NodeSnapshot]) -> HashSet<String> {
    update_snaps
        .iter()
        .filter(|snap| snap.parent_id.is_none() && snap.kind.is_light_addressable())
        .map(|snap| snap.id.clone())
        .collect()
}

fn time_offset_batch_parent_covers_node(
    snap: &rhythm_core::NodeSnapshot,
    top_level_update_ids: &HashSet<String>,
) -> bool {
    snap.parent_id
        .as_deref()
        .is_some_and(|parent_id| top_level_update_ids.contains(parent_id))
}

fn time_offset_preview_node_is_on(s: &AppState, snap: &rhythm_core::NodeSnapshot) -> bool {
    lights_on_from_observed_cache(
        s,
        &s.room_observed_power,
        &snap.id,
        snap.kind,
        snap.parent_id.as_deref(),
        semantic_lights_on_override(
            s.power_save,
            &snap.profile_settings,
            snap.hard_off,
            snap.mood_active,
            snap.soft_off,
        ),
    )
}

fn enqueue_time_offset_preview_dispatch_nodes<I>(
    state: &SharedState,
    runtime: &Arc<dyn RuntimeHandle>,
    dispatch_nodes: I,
    dispatch_spacing: Duration,
) -> Result<usize>
where
    I: IntoIterator<Item = crate::periodic::PeriodicDispatchNode>,
{
    let dispatch_nodes: Vec<_> = dispatch_nodes.into_iter().collect();
    if dispatch_nodes.is_empty() {
        return Ok(0);
    }

    let (dispatch_tx, dispatch_generation) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (
            s.periodic_work_tx.clone().or_else(|| s.work_tx.clone()),
            s.light_dispatch_generation,
        )
    };

    let command_id = crate::logging::next_command_id("manual-preview");
    let current_hour = runtime.current_hour();
    let mut last_node_index_by_emit_target = HashMap::new();
    for (idx, node) in dispatch_nodes.iter().enumerate() {
        last_node_index_by_emit_target.insert(node.emit_node_id.clone(), idx);
    }
    let dispatch_count = dispatch_nodes.len();

    if let Some(tx) = dispatch_tx {
        for (idx, node) in dispatch_nodes.iter().enumerate() {
            let emit_parent_node_id = last_node_index_by_emit_target
                .get(&node.emit_node_id)
                .is_some_and(|last_idx| *last_idx == idx)
                .then_some(node.emit_node_id.as_str())
                .filter(|emit_id| *emit_id != node.settings_node_id);
            if !crate::periodic::enqueue_periodic_tick(
                state,
                &tx,
                crate::periodic::PeriodicTickEnqueue {
                    command_id: &command_id,
                    node_id: &node.node_id,
                    settings_node_id: &node.settings_node_id,
                    dispatch_generation,
                    current_hour,
                    emit_parent_node_id,
                    dispatch_spacing,
                },
            ) {
                return Err(anyhow::anyhow!("Node dispatch queue full"));
            }
        }
        return Ok(dispatch_count);
    }

    for (idx, node) in dispatch_nodes.iter().enumerate() {
        runtime.periodic_tick_node(&node.node_id, &node.settings_node_id, current_hour)?;
        crate::periodic::post_tick_node(state, runtime, &node.settings_node_id);
        let emit_parent_node_id = last_node_index_by_emit_target
            .get(&node.emit_node_id)
            .is_some_and(|last_idx| *last_idx == idx)
            .then_some(node.emit_node_id.as_str())
            .filter(|emit_id| *emit_id != node.settings_node_id);
        if let Some(emit_parent_node_id) = emit_parent_node_id {
            crate::periodic::post_tick_node(state, runtime, emit_parent_node_id);
        }
    }

    Ok(dispatch_count)
}

// ============================================================================
// Device commands
// ============================================================================

/// Upsert a device with button mappings and type in the registry.
///
/// Updates only the specified hub's registry. `room_id == None` registers the
/// device as roomless (no room mapping); button/type mappings are still stored
/// so SSE events can resolve to a known device while awaiting user assignment.
pub fn do_device_set(
    state: &SharedState,
    device_id: &str,
    room_id: Option<&str>,
    buttons: &[(String, u8)],
    device_type: DeviceType,
    hub_key: &HubKey,
    persist: bool,
) -> Result<()> {
    match room_id {
        Some(rid) => {
            info!(target: "cmd", "device_set: {} ({:?}) -> room {} ({} buttons)", device_id, device_type, rid, buttons.len())
        }
        None => {
            info!(target: "cmd", "device_set: {} ({:?}) -> roomless ({} buttons)", device_id, device_type, buttons.len())
        }
    }

    let registry = state
        .lock()
        .ok()
        .and_then(|s| s.hub_registry_for(hub_key))
        .ok_or_else(|| anyhow::anyhow!("No hub registry available for {}", hub_key))?;

    // Dedup
    let device_unchanged = registry
        .lock()
        .ok()
        .map(|reg| reg.device_matches(device_id, room_id, buttons, &device_type))
        .unwrap_or(false);
    if device_unchanged {
        info!(target: "cmd", "device_set: {} unchanged, skipping persist", device_id);
        return Ok(());
    }

    registry
        .lock()
        .map_err(|_| anyhow::anyhow!("hub registry lock poisoned for {}", hub_key))?
        .upsert_device(device_id, room_id, buttons, device_type);

    if persist {
        persist_state(state);
    }
    Ok(())
}

/// Remove a device from the registry.
///
/// Removes from the specified hub's registry only.
pub fn do_device_remove(state: &SharedState, device_id: &str, hub_key: &HubKey) -> Result<()> {
    info!(target: "cmd", "device_remove: {}", device_id);

    let registry = state
        .lock()
        .ok()
        .and_then(|s| s.hub_registry_for(hub_key))
        .ok_or_else(|| anyhow::anyhow!("No hub registry available for {}", hub_key))?;
    registry
        .lock()
        .map_err(|_| anyhow::anyhow!("hub registry lock poisoned for {}", hub_key))?
        .remove_device(device_id);

    persist_state(state);
    Ok(())
}

/// Hard-remove a device from canonical state, topology, and hub registries.
///
/// This is the user-facing delete path. Unlike [`do_device_remove`], which
/// only drops a native registry entry, this removes the device's canonical
/// identity and topology wiring so it disappears fully from the app.
pub fn do_device_hard_remove(
    state: &SharedState,
    device_id: &str,
    hub_key: Option<&HubKey>,
) -> Result<()> {
    info!(target: "cmd", "device_hard_remove: {}", device_id);

    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;

    let (canonical_id, canonical_device, assignments, prepare_assignment, automatic_name_scope) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let canonical_id = if s.canonical_registry.get(device_id).is_some() {
            Some(device_id.to_string())
        } else if let Some(hub_key) = hub_key {
            s.canonical_registry
                .find_by_native_id(hub_key, device_id)
                .map(|device| device.id.clone())
        } else {
            s.hubs.keys().find_map(|key| {
                s.canonical_registry
                    .find_by_native_id(key, device_id)
                    .map(|device| device.id.clone())
            })
        };
        let canonical_device = canonical_id
            .as_ref()
            .and_then(|id| s.canonical_registry.get(id).cloned());
        let assignments = canonical_device
            .as_ref()
            .map(|device| build_hub_device_room_assignments(&s, device, None))
            .unwrap_or_default();
        let automatic_name_scope = canonical_device
            .as_ref()
            .filter(|device| device.device_type == DeviceType::Light)
            .map(|device| {
                let room_id = s
                    .topology
                    .device_parent_room_id(&device.id)
                    .map(str::to_string)
                    .or_else(|| device.room_id.clone());
                LightNameReconciliationScope::for_room(room_id)
            });
        (
            canonical_id,
            canonical_device,
            assignments,
            s.prepare_hub_device_room_assignment_fn.clone(),
            automatic_name_scope,
        )
    };
    let prepared_assignments =
        prepare_hub_device_room_assignments(state, &assignments, prepare_assignment.as_deref())?;

    let mut s = match state.lock() {
        Ok(state) => state,
        Err(_) => {
            return Err(rollback_prepared_hub_device_room_assignments(
                state,
                prepared_assignments,
                anyhow::anyhow!("lock"),
            ));
        }
    };
    if let Some(canonical_id) = canonical_id.as_deref() {
        let unchanged = s
            .canonical_registry
            .get(canonical_id)
            .is_some_and(|device| {
                build_hub_device_room_assignments(&s, device, None) == assignments
            });
        if !unchanged {
            drop(s);
            return Err(rollback_prepared_hub_device_room_assignments(
                state,
                prepared_assignments,
                anyhow::anyhow!("Device topology changed while native removal was in progress"),
            ));
        }
    }

    let topology_before = s.topology.clone();
    let canonical_before = s.canonical_registry.clone();
    if !mirror_prepared_hub_device_room_assignments(&mut s.topology, &prepared_assignments) {
        drop(s);
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            anyhow::anyhow!(
                "Native standalone assignment succeeded but could not be mirrored before removal"
            ),
        ));
    }

    let mut registry_removals: HashSet<(HubKey, String)> = HashSet::new();
    if let Some(device) = canonical_device.as_ref() {
        // `remove_device_everywhere` reports affected parent rooms. A
        // roomless/standalone node has no parent to report even though the
        // node itself is removed, so include its prior existence in the
        // persistence decision. Input bindings are separate topology records
        // and must not outlive their physical source device.
        s.topology.remove_device_everywhere(&device.id);
        s.topology.remove_input_bindings_for_source(&device.id);
        for endpoint in &device.endpoints {
            // A device ID is not a hub-room ID. Remove only this light's
            // membership from the room binding while preserving the group for
            // any remaining room lights.
            s.topology.reassign_hub_light_device(
                &endpoint.hub_key,
                &endpoint.native_id,
                None,
                None,
            );
            // Some non-group integrations model an individually routed light
            // as a device-scoped room binding whose room ID is the native
            // device ID. Remove that exact legacy binding as well; real Hue
            // room/group bindings have independent IDs and remain intact for
            // the room's other bulbs.
            s.topology
                .remove_hub_room_binding_everywhere(&endpoint.hub_key, &endpoint.native_id);
            registry_removals.insert((endpoint.hub_key.clone(), endpoint.native_id.clone()));
        }
        s.canonical_registry.remove_device(&device.id);
        if let Err(error) = save_authority_state(&s) {
            s.topology = topology_before;
            s.canonical_registry = canonical_before;
            let recovery_error = save_authority_state(&s).err();
            if recovery_error.is_some() {
                s.authority_state_recovery_required = true;
            }
            drop(s);
            let error = match recovery_error {
                None => error.context("Failed to durably remove canonical device"),
                Some(recovery_error) => anyhow::anyhow!(
                    "Failed to durably remove canonical device: {:#}; restoring prior persistence failed: {:#}",
                    error,
                    recovery_error
                ),
            };
            return Err(rollback_prepared_hub_device_room_assignments(
                state,
                prepared_assignments,
                error,
            ));
        }
    }

    if registry_removals.is_empty() {
        if let Some(hub_key) = hub_key {
            registry_removals.insert((hub_key.clone(), device_id.to_string()));
        } else {
            for key in s.hubs.keys() {
                registry_removals.insert((key.clone(), device_id.to_string()));
            }
        }
    }

    let mut mode_config_propagation = None;
    if let Some(canonical_id) = canonical_id.as_deref() {
        clear_removed_node_ephemeral_state(&mut s, canonical_id);
        if clear_removed_node_mode_defaults(&mut s, canonical_id) {
            let configs = s.mode_configs();
            let runtimes = s
                .hubs
                .values()
                .filter_map(|hub| hub.runtime.clone())
                .collect::<Vec<_>>();
            persist_settings_locked(&s);
            mode_config_propagation = Some((configs, runtimes));
        }
    }

    for (target_hub_key, native_id) in &registry_removals {
        if let Some(hub) = s.hubs.get(target_hub_key) {
            if let Some(reg) = &hub.registry {
                if let Ok(mut reg) = reg.lock() {
                    reg.remove_room(native_id);
                    reg.remove_device(native_id);
                }
            }
        }
    }

    drop(s);
    // The verified native standalone assignment is now backed by the durable
    // canonical deletion, so its rollback closures must not run.
    drop(prepared_assignments);

    if let Some((configs, runtimes)) = mode_config_propagation {
        propagate_mode_configs_to_runtimes(runtimes, configs);
    }

    if let Some(node_id) = canonical_id.as_deref() {
        queue_motion_timer_clear(state, node_id);
    }

    persist_registry(state);
    if let Some(name_scope) = automatic_name_scope.as_ref() {
        reconcile_automatic_light_names_best_effort(state, name_scope);
    }
    reconcile_runtime_from_state(state)?;

    {
        emit_triage_changed(state);
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    }

    Ok(())
}

/// Remove one hub-native endpoint after a protocol-level unpair.
///
/// A physical bulb may simultaneously have Hue Bridge and direct Hue BLE
/// endpoints. Removing one bond must not delete the other endpoint, its room
/// assignment, or the canonical device. If this was the final endpoint, this
/// delegates to the ordinary full removal path.
pub fn do_device_endpoint_remove(
    state: &SharedState,
    device_id: &str,
    hub_key: &HubKey,
) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let (canonical_id, native_id, endpoint_count, assignments, prepare_assignment) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let device = if let Some(device) = s.canonical_registry.get(device_id) {
            device
        } else if let Some(device) = s.canonical_registry.find_by_native_id(hub_key, device_id) {
            device
        } else {
            // The integration metadata/bond has already been removed and no
            // canonical projection remains. Treat the request as idempotent.
            return Ok(());
        };
        let native_id = device
            .endpoints
            .iter()
            .find(|endpoint| {
                &endpoint.hub_key == hub_key
                    && (endpoint.native_id == device_id || device.id == device_id)
            })
            .map(|endpoint| endpoint.native_id.clone())
            .ok_or_else(|| {
                anyhow::anyhow!("Device '{}' has no endpoint on {}", device_id, hub_key)
            })?;
        let assignments = build_hub_device_room_assignments(&s, device, None)
            .into_iter()
            .filter(|assignment| {
                assignment.hub_key == *hub_key && assignment.native_device_id == native_id
            })
            .collect::<Vec<_>>();
        (
            device.id.clone(),
            native_id,
            device.endpoints.len(),
            assignments,
            s.prepare_hub_device_room_assignment_fn.clone(),
        )
    };

    if endpoint_count <= 1 {
        drop(transaction);
        return do_device_hard_remove(state, &canonical_id, Some(hub_key));
    }

    let prepared_assignments =
        prepare_hub_device_room_assignments(state, &assignments, prepare_assignment.as_deref())?;

    let mut s = match state.lock() {
        Ok(state) => state,
        Err(_) => {
            return Err(rollback_prepared_hub_device_room_assignments(
                state,
                prepared_assignments,
                anyhow::anyhow!("lock"),
            ));
        }
    };
    info!(
        target: "cmd",
        "device_endpoint_remove: canonical={} endpoint={}/{}",
        canonical_id,
        hub_key,
        native_id
    );
    let endpoint_unchanged =
        s.canonical_registry
            .get(&canonical_id)
            .is_some_and(|device| {
                device.endpoints.len() == endpoint_count
                    && device.endpoints.iter().any(|endpoint| {
                        endpoint.hub_key == *hub_key && endpoint.native_id == native_id
                    })
            });
    if !endpoint_unchanged {
        drop(s);
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            anyhow::anyhow!("Device endpoint changed while native removal was in progress"),
        ));
    }

    let topology_before = s.topology.clone();
    let canonical_before = s.canonical_registry.clone();
    if !mirror_prepared_hub_device_room_assignments(&mut s.topology, &prepared_assignments) {
        drop(s);
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            anyhow::anyhow!(
                "Native standalone assignment succeeded but could not be mirrored before endpoint removal"
            ),
        ));
    }
    s.topology
        .reassign_hub_light_device(hub_key, &native_id, None, None);
    s.topology
        .remove_hub_room_binding_everywhere(hub_key, &native_id);
    if s.canonical_registry
        .remove_endpoint(hub_key, &native_id)
        .is_none()
    {
        s.topology = topology_before;
        s.canonical_registry = canonical_before;
        drop(s);
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            anyhow::anyhow!("Endpoint disappeared during removal"),
        ));
    }
    if let Err(error) = save_authority_state(&s) {
        s.topology = topology_before;
        s.canonical_registry = canonical_before;
        let recovery_error = save_authority_state(&s).err();
        if recovery_error.is_some() {
            s.authority_state_recovery_required = true;
        }
        drop(s);
        let error = match recovery_error {
            None => error.context("Failed to durably remove canonical endpoint"),
            Some(recovery_error) => anyhow::anyhow!(
                "Failed to durably remove canonical endpoint: {:#}; restoring prior persistence failed: {:#}",
                error,
                recovery_error
            ),
        };
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            error,
        ));
    }
    if let Some(hub) = s.hubs.get(hub_key) {
        if let Some(registry) = &hub.registry {
            if let Ok(mut registry) = registry.lock() {
                registry.remove_room(&native_id);
                registry.remove_device(&native_id);
            }
        }
    }
    drop(s);
    drop(prepared_assignments);

    persist_registry(state);
    reconcile_runtime_from_state(state)?;
    emit_triage_changed(state);
    crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    Ok(())
}

/// Soft-remove a device from the canonical registry by its native ID.
///
/// Looks up the canonical device via native ID + hub key, marks it as
/// soft-removed (preserves the tombstone for dedup), and persists.
pub fn do_canonical_soft_remove(state: &SharedState, device_id: &str, hub_key: &HubKey) {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let mut s = match state.lock() {
        Ok(s) => s,
        Err(_) => return,
    };

    // Find canonical ID by native ID
    let canonical_id = s
        .canonical_registry
        .find_by_native_id(hub_key, device_id)
        .map(|d| d.id.clone());

    if let Some(id) = canonical_id {
        if s.canonical_registry.soft_remove(&id, now) {
            info!(target: "cmd", "canonical_soft_remove: {} (native={})", id, device_id);
        }
        persist_canonical(&s);
    }
}

/// Resolve motion timeout defaults for controlled target nodes.
pub(crate) fn resolved_motion_timeout_map(
    state: &SharedState,
) -> (HashMap<String, u64>, HashSet<String>) {
    let (
        runtime,
        light_profile_configs,
        mode_configs,
        active_mode,
        solar_noon,
        latitude,
        longitude,
        utc_offset,
        timezone_name,
        control_targets,
    ) = {
        let Ok(s) = state.lock() else {
            return (HashMap::new(), HashSet::new());
        };
        (
            s.hub_runtime(),
            s.light_profile_configs.clone(),
            s.mode_configs(),
            s.active_mode,
            s.solar_noon_hour(),
            s.latitude,
            s.longitude,
            s.utc_offset_hours,
            s.timezone_name.clone(),
            s.motion_control_target_ids(),
        )
    };

    let current_hour = runtime.as_ref().map(|rt| rt.current_hour()).unwrap_or(12.0);
    let snapshots = runtime
        .as_ref()
        .map(|rt| rt.engine_all_effective_node_snapshots())
        .unwrap_or_default();

    let mut timeouts = HashMap::new();
    for snap in &snapshots {
        timeouts.insert(
            snap.id.clone(),
            resolved_room_motion_timeout_secs_from_parts(
                RoomLightingContext {
                    light_profile_configs: &light_profile_configs,
                    mode_configs: &mode_configs,
                    mode: active_mode,
                    solar_noon,
                    latitude,
                    longitude,
                    timezone_name: timezone_name.as_deref(),
                    utc_offset,
                },
                &snap.profile_settings,
                current_hour,
            ),
        );
    }
    (timeouts, control_targets)
}

fn resolved_motion_timeout_for_node_settings(
    state: &SharedState,
    settings: &RoomProfileSettings,
    current_hour: f32,
) -> Result<u64> {
    let (
        light_profile_configs,
        mode_configs,
        active_mode,
        solar_noon,
        latitude,
        longitude,
        utc_offset,
        timezone_name,
    ) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (
            s.light_profile_configs.clone(),
            s.mode_configs(),
            s.active_mode,
            s.solar_noon_hour(),
            s.latitude,
            s.longitude,
            s.utc_offset_hours,
            s.timezone_name.clone(),
        )
    };

    Ok(resolved_room_motion_timeout_secs_from_parts(
        RoomLightingContext {
            light_profile_configs: &light_profile_configs,
            mode_configs: &mode_configs,
            mode: active_mode,
            solar_noon,
            latitude,
            longitude,
            timezone_name: timezone_name.as_deref(),
            utc_offset,
        },
        settings,
        current_hour,
    ))
}

// ============================================================================
// Config commands
// ============================================================================

/// Update a light profile config, push it to the runtime, and persist it.
pub fn do_config_set(state: &SharedState, config: LightProfileConfig) -> Result<()> {
    do_config_set_with_options(state, config, false)
}

/// Update a light profile config, optionally reapplying active-mode outputs.
pub fn do_config_set_with_options(
    state: &SharedState,
    config: LightProfileConfig,
    apply_active_outputs: bool,
) -> Result<()> {
    do_config_set_with_options_if_matches(state, config, apply_active_outputs, None)
}

/// Update a light profile config only when optional live identity and content
/// preconditions still match inside the same state lock as the mutation.
pub fn do_config_set_with_options_if_matches(
    state: &SharedState,
    mut config: LightProfileConfig,
    apply_active_outputs: bool,
    precondition: Option<(&str, &str)>,
) -> Result<()> {
    rhythm_core::normalize_builtin_state_profile_config(&mut config);
    config.normalize_float_precision();

    let curve_desc = match &config.curve {
        rhythm_core::LightCurveShape::SuperGaussian { direct_color, .. } => {
            if let Some(dc) = direct_color {
                format!(
                    "super-gaussian+color(xy={:.3},{:.3} rgb={},{},{})",
                    dc.xy.x, dc.xy.y, dc.rgb.r, dc.rgb.g, dc.rgb.b
                )
            } else {
                "super-gaussian".to_string()
            }
        }
        rhythm_core::LightCurveShape::Palette { keyframes } => {
            format!("palette({}kf)", keyframes.len())
        }
        rhythm_core::LightCurveShape::InheritActive => "inherit-active".to_string(),
        rhythm_core::LightCurveShape::Constant {
            brightness,
            color_temp,
            ..
        } => format!("constant(bri={:.2}, cct={:.2})", brightness, color_temp),
    };
    info!(
        target: "cmd",
        "config_set: id='{}', curve={}, min_bri={}, max_bri={}, min_cct={}, max_cct={}, dim_steps={}, fade={:?}, motion={:?}, interval={:?}",
        config.id,
        curve_desc,
        config.min_brightness,
        config.max_brightness,
        config.min_color_temp,
        config.max_color_temp,
        config.max_dim_steps,
        config.fade_ms,
        config.motion_timeout_secs,
        config.rhythm_interval_secs,
    );

    let (runtime, should_apply_outputs, active_mode, dispatch_generation) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if let Some((expected_server_instance_id, expected_resource_sha256)) = precondition {
            if s.server_instance_id != expected_server_instance_id {
                return Err(anyhow::anyhow!(
                    "config precondition failed: live server identity changed"
                ));
            }
            let current = s
                .light_profile_config(&config.id)
                .ok_or_else(|| anyhow::anyhow!("Unknown light profile: {}", config.id))?;
            if light_profile_config_resource_sha256(current)? != expected_resource_sha256 {
                return Err(anyhow::anyhow!(
                    "config precondition failed: live config hash changed"
                ));
            }
        }
        if !s.light_profile_configs.contains_key(&config.id) {
            return Err(anyhow::anyhow!("Unknown light profile: {}", config.id));
        }
        let updates_active_profile = config.id == s.active_mode_profile_id();
        s.set_light_profile_config(config.clone());
        if updates_active_profile {
            s.sync_active_mode_runtime_overrides();
        }
        let should_apply_outputs = apply_active_outputs && updates_active_profile;
        let dispatch_generation = if should_apply_outputs {
            let dispatch_generation = s.invalidate_queued_light_dispatches();
            tracing::debug!(
                target: "cmd",
                event = "queued_light_dispatches_invalidated",
                active_mode = ?s.active_mode,
                profile_id = %config.id,
                dispatch_generation,
                "Invalidated queued generated light dispatches for active config apply"
            );
            dispatch_generation
        } else {
            s.light_dispatch_generation
        };
        let active_mode = s.active_mode;
        persist_light_profiles_locked(&s);
        (
            s.hub_runtime(),
            should_apply_outputs,
            active_mode,
            dispatch_generation,
        )
    };

    if let Some(runtime) = runtime.as_ref() {
        if let Err(e) = runtime.set_light_profile_config(config.clone()) {
            warn!(target: "cmd", "Failed to update runtime light profile config: {}", e);
        }
    }

    if should_apply_outputs {
        apply_active_mode_outputs(
            state,
            ActiveModeOutputApply {
                previous_mode: active_mode,
                target_mode: active_mode,
                transition: None,
                apply_scope: ModeOutputApplyScope::all_visible(),
                dispatch_generation,
                force_observed_off_outputs: false,
                reset_all_room_defaults: false,
                reassert_hard_off_defaults: false,
            },
        );
    }

    crate::state::emit_server_event(state, crate::server_event::ServerEvent::ConfigChanged);

    Ok(())
}

fn canonical_json_sha256(value: &Value) -> String {
    fn canonicalize(value: &Value) -> Value {
        match value {
            Value::Object(values) => {
                let mut keys = values.keys().collect::<Vec<_>>();
                keys.sort();
                Value::Object(
                    keys.into_iter()
                        .map(|key| (key.clone(), canonicalize(&values[key])))
                        .collect(),
                )
            }
            Value::Array(values) => Value::Array(values.iter().map(canonicalize).collect()),
            _ => value.clone(),
        }
    }

    let canonical = serde_json::to_vec(&canonicalize(value)).unwrap_or_default();
    Sha256::digest(canonical)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// Absorb a time offset into a light profile config by adjusting ramp widths.
///
/// Modifies the width parameters for the current side of the day (morning/evening)
/// so the curve naturally produces the offset's values at the current time, then
/// resets all room time offsets to 0.
pub fn do_absorb_time_offset(
    state: &SharedState,
    profile_id: Option<&str>,
    offset_minutes: f32,
) -> Result<()> {
    info!(target: "cmd", "absorb_time_offset: {}min", offset_minutes);

    let (resolved_profile_id, config, runtime, sunrise, sunset) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let resolved_profile_id = resolve_profile_id(&s, profile_id)?;
        let config = s
            .light_profile_config(&resolved_profile_id)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("Unknown light profile: {}", resolved_profile_id))?;
        let runtime = s.hub_runtime();

        // Compute sunrise/sunset from location, or use fallbacks
        let (sunrise, sunset) = if let (Some(lat), Some(lon)) = (s.latitude, s.longitude) {
            if let Some(ref tz_name) = s.timezone_name {
                let tz = rhythm_core::Timezone::new(tz_name);
                let (year, month, day) = tz.local_date_from_utc(chrono::Utc::now().naive_utc());
                let st = rhythm_core::solar::calculate_sun_times(lat, lon, year, month, day, &tz);
                (st.sunrise, st.sunset)
            } else {
                // Fallback: estimate from solar noon
                let half_day = 7.0; // rough approximation
                let noon = s.solar_noon_hour();
                (noon - half_day, noon + half_day)
            }
        } else {
            (
                rhythm_core::config::FALLBACK_SUNRISE_HOUR,
                rhythm_core::config::FALLBACK_SUNSET_HOUR,
            )
        };

        (resolved_profile_id, config, runtime, sunrise, sunset)
    };

    // Compute current local hour — prefer the runtime's time provider (which
    // may be mocked in tests) over the wall clock.
    let current_hour = if let Some(ref rt) = runtime {
        rt.current_hour()
    } else {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let local = current_local_datetime(s.utc_offset_hours);
        let t = local.time();
        t.hour() as f32 + t.minute() as f32 / 60.0 + t.second() as f32 / 3600.0
    };

    // Adjust config widths if offset is meaningful
    if let Some(mut new_config) =
        absorb_light_profile_time_offset(&config, current_hour, offset_minutes, sunrise, sunset)
    {
        new_config.normalize_float_precision();
        info!(target: "cmd", "absorb_time_offset: adjusted widths — bri L={:.3} R={:.3}, cct L={:.3} R={:.3}",
        match &new_config.curve {
            rhythm_core::LightCurveShape::SuperGaussian { width_left_bri, .. } => *width_left_bri,
            _ => 0.0,
        },
        match &new_config.curve {
            rhythm_core::LightCurveShape::SuperGaussian { width_right_bri, .. } => *width_right_bri,
            _ => 0.0,
        },
        match &new_config.curve {
            rhythm_core::LightCurveShape::SuperGaussian { width_left_cct, .. } => *width_left_cct,
            _ => 0.0,
        },
        match &new_config.curve {
            rhythm_core::LightCurveShape::SuperGaussian { width_right_cct, .. } => *width_right_cct,
            _ => 0.0,
        });

        // Update config in state + persist + push to engine
        {
            let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            if resolved_profile_id != new_config.id {
                return Err(anyhow::anyhow!(
                    "Profile ID mismatch while absorbing offset"
                ));
            }
            s.set_light_profile_config(new_config.clone());
            if resolved_profile_id == s.active_mode_profile_id() {
                s.sync_active_mode_runtime_overrides();
            }
            persist_light_profiles_locked(&s);
        }

        if let Some(ref rt) = runtime {
            if let Err(e) = rt.set_light_profile_config(new_config) {
                warn!(target: "cmd", "Failed to update runtime light profile config: {}", e);
            }
        }
    }

    // Reset all top-level light-addressable node time offsets to 0.
    if let Some(ref rt) = runtime {
        let snapshots: Vec<_> = rt
            .engine_all_effective_node_snapshots()
            .into_iter()
            .filter(|node| node.kind.is_light_addressable() && node.parent_id.is_none())
            .collect();
        let mut reset_node_ids = Vec::new();
        for snap in &snapshots {
            if snap.time_offset_minutes.abs() > 0.001 {
                let mut restored = RestoredNodeState::from(snap);
                restored.time_offset_minutes = 0.0;
                rt.restore_node_state(&snap.id, restored);
                reset_node_ids.push(snap.id.clone());
            }
        }

        for node_id in reset_node_ids {
            if let Err(e) = enqueue_time_offset_preview_ticks(
                state,
                rt,
                &node_id,
                default_http_batch_dispatch_spacing(),
            ) {
                warn!(
                    target: "cmd",
                    "Failed to enqueue offset reset refresh for node {}: {}",
                    node_id,
                    e
                );
            }
        }
    }

    persist_rooms(state);

    {
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::ConfigChanged);
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    }

    Ok(())
}

/// Update lat/lon/utc_offset, recalculate solar noon.
///
/// Solar noon is computed internally:
/// - If `timezone_name` is provided, uses DST-aware `calculate_solar_noon`
/// - Otherwise, falls back to `calculate_solar_noon_from_offset`
pub fn do_location_set(
    state: &SharedState,
    lat: f32,
    lon: f32,
    utc_offset: Option<f32>,
    timezone_name: Option<String>,
) -> Result<()> {
    info!(target: "cmd", "location_set: lat={}, lon={}, utc_offset={:?}, tz={:?}", lat, lon, utc_offset, timezone_name);

    {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;

        s.latitude = Some(lat);
        s.longitude = Some(lon);
        s.timezone_name = timezone_name.clone();

        if let Some(offset) = utc_offset {
            s.utc_offset_hours = offset;
        }

        // Compute solar noon: prefer timezone-aware calculation
        let now = chrono::Utc::now().naive_utc();
        let (solar_noon, day_of_year, sun_times) = if let Some(ref tz_name) = timezone_name {
            let tz = rhythm_core::Timezone::new(tz_name);
            let local_now = tz.local_datetime_from_utc(now);
            let (year, month, day) = (
                local_now.date().year(),
                local_now.date().month(),
                local_now.date().day(),
            );
            let day_of_year = rhythm_core::timezone::day_of_year(year, month, day);
            // Also refresh utc_offset from timezone
            s.utc_offset_hours = tz.utc_offset(year, month, day, local_now.time().hour());
            (
                rhythm_core::calculate_solar_noon(lon, year, month, day, &tz),
                day_of_year,
                Some(rhythm_core::calculate_sun_times(
                    lat, lon, year, month, day, &tz,
                )),
            )
        } else {
            let local_now = current_local_datetime(s.utc_offset_hours);
            let day_of_year = rhythm_core::timezone::day_of_year(
                local_now.date().year(),
                local_now.date().month(),
                local_now.date().day(),
            );
            (
                rhythm_core::calculate_solar_noon_from_offset(lon, s.utc_offset_hours, day_of_year),
                day_of_year,
                None,
            )
        };
        s.runtime_config.solar_noon_hour = solar_noon;
        crate::logging::update_log_clock_from_location(
            s.timezone_name.as_deref(),
            s.utc_offset_hours,
            true,
        );

        if let Some(runtime) = s.hub_runtime() {
            let solar_time = rhythm_core::SolarTime::new(solar_noon, lat, day_of_year);
            if let Err(e) = runtime.set_solar(solar_time) {
                warn!(target: "cmd", "Failed to update solar time: {}", e);
            }
            if let Some(sun_times) = sun_times {
                if let Err(e) = runtime.set_sun_times(sun_times) {
                    warn!(target: "cmd", "Failed to update sun times: {}", e);
                }
            } else if let Err(e) = runtime.clear_sun_times() {
                warn!(target: "cmd", "Failed to clear sun times: {}", e);
            }
        }

        if let Some(ref storage) = s.storage {
            let loc = StoredLocation {
                latitude: Some(lat),
                longitude: Some(lon),
                utc_offset_hours: s.utc_offset_hours,
                timezone_name,
            };
            if let Err(e) = storage.save_location(&loc) {
                warn!(target: "cmd", "Failed to save location: {}", e);
            }
        }
    }

    // No ConfigChanged broadcast — location is client→server fire-and-forget.
    // Broadcasting would cause a feedback loop when multiple apps connect.

    Ok(())
}

/// Save hub credentials and connect SSE.
///
/// After a successful configure, auto-syncs rooms from the hub if
/// the hub provides a `HubDiscovery` implementation.
pub fn do_hub_credentials(
    state: &SharedState,
    hub_type_str: &str,
    address: &str,
    credentials: &Value,
) -> Result<()> {
    info!(target: "cmd", "hub_credentials: type={}, address={}", hub_type_str, address);

    let hub_type = crate::hub::HubType::parse(hub_type_str)
        .ok_or_else(|| anyhow::anyhow!("Unknown hub type: {}", hub_type_str))?;
    let hub_key = crate::canonical::identity::HubKey::new(hub_type.clone(), address);

    let credentials_json = serde_json::to_string(credentials)?;

    let get_provider = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        // Reject unregistered hub types up front — get_hub_provider_fn
        // panics on unknown types, and hub_type is caller-supplied (e.g. a
        // backup with Matter credentials restored onto a build without the
        // Matter integration). Mirrors the check in do_retry_hub_connect.
        if !s.hub_capabilities.is_empty()
            && !s
                .hub_capabilities
                .iter()
                .any(|capability| capability.hub_type == hub_type_str)
        {
            return Err(anyhow::anyhow!(
                "Hub type '{}' is not supported on this runtime",
                hub_type_str
            ));
        }
        s.get_hub_provider_fn
            .clone()
            .ok_or_else(|| anyhow::anyhow!("No hub provider registered"))?
    };

    if let Ok(mut s) = state.lock() {
        s.clear_hub_startup_retry(&hub_key);
    }

    let provider = get_provider(hub_type.clone());
    provider.configure(address, &credentials_json, state)?;

    // Register the new hub's controller with the composite (if runtime already exists).
    register_hub_with_composite(state, &hub_key);

    let requires_authoritative_sync = {
        let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let required = state.external_controller_authority_is_required(&hub_key);
        if required {
            state.mark_external_controller_initial_sync_pending(&hub_key);
        }
        required
    };

    // Auto-sync rooms from the newly configured hub.
    // Uses platform config to decide whether to also discover devices/sensors
    // (desktop: full sync, constrained blocking path: rooms only — devices
    // arrive via SSE).
    let discover_devices = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.platform.full_device_discovery
    };
    // Auto-sync + poll must run on a dedicated thread — reqwest::blocking::Client
    // panics if used inside a tokio runtime context (spawn_blocking from HTTP handler).
    let sync_result: Result<()> = (|| {
        let sync_state = state.clone();
        let sync_hub_key = hub_key.clone();
        let worker = std::thread::Builder::new()
            .name("hub-sync".to_string())
            .spawn(move || -> Result<()> {
                if requires_authoritative_sync {
                    crate::room_sync::sync_from_hub_for_key_before_authority(
                        &sync_state,
                        &sync_hub_key,
                        discover_devices,
                    )?;
                } else {
                    crate::room_sync::sync_from_hub_for_key(
                        &sync_state,
                        &sync_hub_key,
                        discover_devices,
                    )?;
                }
                Ok(())
            })
            .map_err(|error| anyhow::anyhow!("Failed to start hub sync worker: {error}"))?;
        worker
            .join()
            .map_err(|_| anyhow::anyhow!("Hub sync worker panicked"))?
    })();
    if let Err(error) = sync_result {
        if requires_authoritative_sync {
            crate::hub::discard_active_hub_for_full_bootstrap_retry(state, &hub_key);
        }
        return Err(error).context("Hub configured but initial topology sync failed");
    }

    if requires_authoritative_sync {
        state
            .lock()
            .map_err(|_| anyhow::anyhow!("lock"))?
            .mark_external_controller_initial_sync_complete(&hub_key);
    }

    let authority_result = {
        let authority_state = state.clone();
        let authority_hub_key = hub_key.clone();
        std::thread::Builder::new()
            .name("hub-authority".to_string())
            .spawn(move || -> Result<()> {
                reconcile_external_controller_authority(&authority_state, &authority_hub_key)?;
                crate::room_sync::poll_initial_light_state(&authority_state);
                Ok(())
            })
            .map_err(|error| anyhow::anyhow!("Failed to start hub authority worker: {error}"))?
            .join()
            .map_err(|_| anyhow::anyhow!("Hub authority worker panicked"))?
    };
    authority_result.context("Hub configured but authoritative reconciliation failed")?;

    {
        let hub_connected = state
            .lock()
            .ok()
            .map(|s| s.hub_is_connected(&hub_key))
            .unwrap_or(false);
        crate::state::emit_server_event(
            state,
            crate::server_event::ServerEvent::HubStatus {
                hub_type: Some(hub_type_str.to_string()),
                address: Some(address.to_string()),
                connected: hub_connected,
            },
        );
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    }

    Ok(())
}

/// Build the privacy-bounded, per-room Hue automation ownership review.
pub fn build_hue_authority(state: &SharedState) -> Result<crate::api_types::HueAuthorityResponse> {
    use crate::api_types::{HueAuthorityResponse, HueBridgeAuthorityDto, HueRoomAuthorityDto};
    use crate::topology::ExternalRoomAutomationOwner;

    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let mut keys = s
        .hub_credentials
        .keys()
        .chain(s.hubs.keys())
        .chain(s.topology.referenced_hub_keys().iter())
        .filter(|key| key.hub_type.as_str() == crate::hub::HubType::HUE)
        .cloned()
        .collect::<Vec<_>>();
    keys.sort_by(|left, right| left.address.cmp(&right.address));
    keys.dedup();

    let bridges = keys
        .into_iter()
        .filter_map(|key| {
            let rooms = s.topology.external_automation_rooms_for_hub(&key);
            if rooms.is_empty() {
                return None;
            }
            Some(HueBridgeAuthorityDto {
                address: key.address.clone(),
                revision: s.topology.external_automation_revision(&key),
                takeover_scope: "bridge",
                bridge_takeover_requested: s.topology.external_hub_has_full_rhythm_consent(&key),
                rooms: rooms
                    .into_iter()
                    .map(|(room_id, name, owner)| HueRoomAuthorityDto {
                        rhythm_automation_enabled: s.rhythm_automation_allowed_for_node(&room_id),
                        room_id,
                        name,
                        owner: match owner {
                            None => "unreviewed",
                            Some(ExternalRoomAutomationOwner::External) => "hue",
                            Some(ExternalRoomAutomationOwner::Rhythm) => "rhythm",
                        }
                        .to_string(),
                    })
                    .collect(),
            })
        })
        .collect();

    Ok(HueAuthorityResponse {
        schema_version: 1,
        bridges,
    })
}

/// Atomically persist one complete Hue room review. A full-Rhythm review may
/// acquire the existing bridge-wide handoff; every other review freezes
/// unattended Rhythm output first and restores any prior handoff.
pub fn do_hue_authority_update(
    state: &SharedState,
    request: crate::api_types::HueAuthorityUpdateRequest,
) -> Result<crate::api_types::HueAuthorityResponse> {
    use crate::api_types::HueRoomAuthorityOwnerDto;
    use crate::topology::ExternalRoomAutomationOwner;

    if request.address.trim().is_empty() || request.address.len() > 255 {
        anyhow::bail!("A valid Hue bridge address is required");
    }
    if request.revision.len() != 16
        || !request
            .revision
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit())
    {
        anyhow::bail!("A valid Hue authority revision is required");
    }
    if request.correlation_id.trim().is_empty()
        || request.correlation_id.len() > 96
        || !request
            .correlation_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        anyhow::bail!("A valid Hue authority correlation ID is required");
    }
    let correlation_id = request.correlation_id.clone();
    let key = HubKey::new(
        crate::hub::HubType::new(crate::hub::HubType::HUE),
        request.address,
    );
    let (policy_transaction_lock, topology_transaction_lock) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (
            s.external_controller_policy_transaction_lock.clone(),
            s.external_topology_transaction_lock.clone(),
        )
    };
    let _policy_transaction = policy_transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External controller policy lock poisoned"))?;
    let full_rhythm_consent = {
        let _topology_transaction = topology_transaction_lock
            .lock()
            .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let known = s.hub_credentials.contains_key(&key)
            || s.hubs.contains_key(&key)
            || s.topology.references_hub_key(&key);
        if !known {
            anyhow::bail!("The selected Hue bridge is not configured");
        }
        let current_revision = s.topology.external_automation_revision(&key);
        if current_revision != request.revision {
            anyhow::bail!(
                "Hue rooms changed while they were being reviewed; refresh and try again"
            );
        }

        let decisions = request
            .rooms
            .into_iter()
            .map(|room| {
                (
                    room.room_id,
                    match room.owner {
                        HueRoomAuthorityOwnerDto::Hue => ExternalRoomAutomationOwner::External,
                        HueRoomAuthorityOwnerDto::Rhythm => ExternalRoomAutomationOwner::Rhythm,
                    },
                )
            })
            .collect::<Vec<_>>();
        let topology_before = s.topology.clone();
        let changed = s
            .topology
            .replace_external_room_automation_decisions(&key, &decisions)
            .map_err(anyhow::Error::msg)?;
        if changed {
            if let Err(error) = save_authority_state(&s) {
                s.topology = topology_before;
                return Err(error).context("Failed to persist Hue room authority choices");
            }
            // Any command queued under the previous admission policy must
            // fail its final generation check before it can reach a light.
            s.invalidate_queued_light_dispatches();
        }
        let full_rhythm_consent = s.topology.external_hub_has_full_rhythm_consent(&key);
        if full_rhythm_consent {
            // Publish the transition fence in the same state-lock epoch as
            // the desired policy, leaving no window where periodic work can
            // observe consent before controller suppression begins.
            s.mark_external_controller_authority_pending(&key);
        }
        full_rhythm_consent
    };

    if full_rhythm_consent {
        if let Err(acquire_error) = reconcile_external_controller_authority(state, &key) {
            // Never publish a Rhythm-owned policy after an incomplete bridge
            // handoff. Restore the previous fail-closed policy, then ask Hue
            // to undo any successfully journaled partial mutations.
            let _topology_transaction = topology_transaction_lock
                .lock()
                .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
            {
                let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
                let fail_closed_decisions = s
                    .topology
                    .external_automation_rooms_for_hub(&key)
                    .into_iter()
                    .map(|(room_id, _, _)| (room_id, ExternalRoomAutomationOwner::External))
                    .collect::<Vec<_>>();
                if !fail_closed_decisions.is_empty() {
                    s.topology
                        .replace_external_room_automation_decisions(&key, &fail_closed_decisions)
                        .map_err(anyhow::Error::msg)?;
                }
                save_authority_state(&s)
                    .context("Failed to roll back Hue room choices after takeover failure")?;
                s.invalidate_queued_light_dispatches();
            }
            prepare_external_controller_release(
                state,
                std::slice::from_ref(&key),
                crate::hub::ExternalControllerReleaseReason::RoomAuthorityChanged,
            )
            .context("Failed to restore Hue after an incomplete room handoff")?;
            state
                .lock()
                .map_err(|_| anyhow::anyhow!("lock"))?
                .mark_external_controller_authority_ready(&key);
            return Err(acquire_error)
                .context("Hue room choices were not applied because bridge authority failed");
        }
        state
            .lock()
            .map_err(|_| anyhow::anyhow!("lock"))?
            .mark_external_controller_authority_ready(&key);
    } else {
        let _topology_transaction = topology_transaction_lock
            .lock()
            .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
        prepare_external_controller_release(
            state,
            std::slice::from_ref(&key),
            crate::hub::ExternalControllerReleaseReason::RoomAuthorityChanged,
        )
        .context("Hue room choices were saved, but prior bridge changes could not be restored")?;
        state
            .lock()
            .map_err(|_| anyhow::anyhow!("lock"))?
            .mark_external_controller_authority_ready(&key);
    }
    info!(
        target: "hue_authority",
        "event=hue_room_authority_transition_completed correlation_id={} outcome=succeeded bridge_takeover={}",
        correlation_id,
        full_rhythm_consent
    );
    crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    build_hue_authority(state)
}

/// Reset startup retry state for one configured hub and request an immediate
/// stored-credentials bootstrap attempt.
pub fn do_retry_hub_connect(state: &SharedState, hub_type_str: &str, address: &str) -> Result<()> {
    let hub_type = crate::hub::HubType::parse(hub_type_str)
        .ok_or_else(|| anyhow::anyhow!("Unknown hub type: {}", hub_type_str))?;
    let hub_key = HubKey::new(hub_type, address);

    let (request_bootstrap, reconcile_pending) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;

        let creds = s
            .hub_credentials
            .get(&hub_key)
            .ok_or_else(|| anyhow::anyhow!("No stored credentials for {}", hub_key))?;
        if !creds.can_connect() {
            return Err(anyhow::anyhow!(
                "Stored credentials for {} are not connectable",
                hub_key
            ));
        }
        if !s
            .hub_capabilities
            .iter()
            .any(|capability| capability.hub_type == hub_type_str)
        {
            return Err(anyhow::anyhow!(
                "Hub type '{}' is not supported on this runtime",
                hub_type_str
            ));
        }
        if s.hubs.contains_key(&hub_key) {
            if s.external_controller_initial_sync_is_pending(&hub_key) {
                anyhow::bail!(
                    "Initial authoritative topology sync is still pending for {}",
                    hub_key
                );
            }
            if s.external_controller_authority_is_ready(&hub_key) {
                return Ok(());
            }
            (None, true)
        } else {
            s.clear_hub_startup_retry(&hub_key);
            (
                Some(
                    s.request_hub_bootstrap_fn
                        .clone()
                        .ok_or_else(|| anyhow::anyhow!("No hub bootstrap callback registered"))?,
                ),
                false,
            )
        }
    };

    let connected = if reconcile_pending {
        reconcile_external_controller_authority(state, &hub_key)?;
        state
            .lock()
            .map_err(|_| anyhow::anyhow!("lock"))?
            .hub_is_connected(&hub_key)
    } else if let Some(request_bootstrap) = request_bootstrap {
        request_bootstrap(state);
        false
    } else {
        false
    };
    crate::state::emit_server_event(
        state,
        crate::server_event::ServerEvent::HubStatus {
            hub_type: Some(hub_type_str.to_string()),
            address: Some(address.to_string()),
            connected,
        },
    );
    Ok(())
}

fn reconcile_external_controller_authority(state: &SharedState, key: &HubKey) -> Result<()> {
    let callback = {
        let state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if state.external_controller_initial_sync_is_pending(key) {
            anyhow::bail!("Initial authoritative topology sync is incomplete");
        }
        state.reconcile_external_controller_authority_fn.clone()
    };
    match callback {
        Some(callback) => callback(state, key),
        None => Ok(()),
    }
}

fn prepare_external_controller_release(
    state: &SharedState,
    keys: &[HubKey],
    reason: crate::hub::ExternalControllerReleaseReason,
) -> Result<()> {
    let callback = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .release_external_controller_authority_fn
        .clone();
    let Some(callback) = callback else {
        return Ok(());
    };
    // Callers hold the external-topology transaction across this release and
    // the subsequent credential commit, finalization, and local teardown.
    // Integrations that own external controller authority fence themselves in
    // the callback. The command layer must not fence unrelated hub types.
    for key in keys {
        callback(state, key, reason).with_context(|| {
            format!(
                "{} controller authority could not be released before local teardown",
                key.hub_type.as_str()
            )
        })?;
    }
    Ok(())
}

fn finalize_external_controller_release(state: &SharedState, keys: &[HubKey]) -> Result<()> {
    let callback = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .finalize_external_controller_release_fn
        .clone();
    let Some(callback) = callback else {
        return Ok(());
    };
    for key in keys {
        callback(state, key).with_context(|| {
            format!(
                "{} controller recovery state could not be finalized after credential removal",
                key.hub_type.as_str()
            )
        })?;
    }
    Ok(())
}

fn configured_or_active_hub_keys(state: &SharedState) -> Result<Vec<HubKey>> {
    let state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let mut keys = state
        .hub_credentials
        .keys()
        .chain(state.hubs.keys())
        .cloned()
        .collect::<Vec<_>>();
    keys.sort_by_key(|key| key.to_string());
    keys.dedup();
    Ok(keys)
}

/// Include Hue keys retained only by topology policy in the durable tombstone
/// set. They are intentionally not returned from `configured_or_active_hub_keys`:
/// a marker-only key has no live controller to release or finalize.
fn external_room_automation_policy_keys_for_disconnect(
    state: &SharedState,
    release_keys: &[HubKey],
) -> Result<Vec<HubKey>> {
    let mut keys = release_keys.to_vec();
    keys.extend(
        state
            .lock()
            .map_err(|_| anyhow::anyhow!("lock"))?
            .topology
            .referenced_hub_keys()
            .into_iter()
            .filter(|key| key.hub_type.as_str() == crate::hub::HubType::HUE),
    );
    keys.sort_by_key(|key| key.to_string());
    keys.dedup();
    Ok(keys)
}

/// Durably remove the selected credentials before an external controller's
/// retained snapshot can be finalized. In-memory credentials remain intact
/// until local teardown commits, so a persistence failure is retryable. A
/// crash before finalization sees `release_pending` and is fail-closed; a crash
/// after finalization sees an archival snapshot and no bootstrap credential.
fn stage_hub_credential_deletion(
    state: &SharedState,
    removed_keys: Option<&[HubKey]>,
) -> Result<()> {
    let (storage, remaining) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let remaining = s
            .hub_credentials
            .iter()
            .filter(|(key, _)| {
                removed_keys.is_some_and(|keys| !keys.iter().any(|removed| removed == *key))
            })
            .map(|(_, credentials)| credentials.clone())
            .collect::<Vec<_>>();
        (s.storage.clone(), remaining)
    };
    let Some(storage) = storage else {
        return Ok(());
    };
    storage
        .save_all_hub_credentials(&remaining)
        .context("Failed to durably delete hub credentials")?;
    Ok(())
}

/// Durably clear retained room-automation authority after successful controller
/// release and before credential removal or finalization becomes irreversible.
///
/// A failed coupled authority-state commit restores the exact in-memory
/// topology and leaves credentials untouched so the disconnect can be retried.
/// The integration's already-durable released phase continues to fence a new
/// takeover until that retry completes.
fn durably_forget_external_room_automation_policy(
    state: &SharedState,
    hub_keys: &[HubKey],
    reason: crate::hub::ExternalControllerReleaseReason,
) -> Result<()> {
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let topology_before = s.topology.clone();
    let mut changed = false;
    for key in hub_keys {
        changed |= s
            .topology
            .forget_external_room_automation_policy_for_hub(key);
    }
    if !changed {
        return Ok(());
    }
    // Backup restore and factory reset are the two explicit replacement
    // operations allowed to recover a corrupt combined authority snapshot.
    // Their intermediate tombstone must cross the same durability boundary,
    // but it deliberately leaves the recovery fence raised until the complete
    // replacement installation is committed below. Ordinary disconnects must
    // preserve corrupt evidence and therefore use the checked save path.
    let save_result = match reason {
        crate::hub::ExternalControllerReleaseReason::BackupRestore
        | crate::hub::ExternalControllerReleaseReason::FactoryReset => {
            save_authority_state_unchecked(&s)
        }
        _ => save_authority_state(&s),
    };
    if let Err(error) = save_result {
        s.topology = topology_before;
        return Err(error.context("Failed to durably forget external room automation policy"));
    }
    s.invalidate_queued_light_dispatches();
    Ok(())
}

/// Disconnect all hubs after integrations have restored any controller state
/// they replaced while authoritative.
pub fn do_hub_disconnect(state: &SharedState) -> Result<()> {
    do_hub_disconnect_with_reason(
        state,
        crate::hub::ExternalControllerReleaseReason::UserDisconnect,
    )
}

fn do_hub_disconnect_with_reason(
    state: &SharedState,
    reason: crate::hub::ExternalControllerReleaseReason,
) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    disconnect_hubs_with_reason_under_transaction(state, reason)
}

/// Disconnect all hubs while the caller holds the external-topology
/// transaction. Backup restore uses this entry point so its release and every
/// subsequent replacement write share one lease.
fn disconnect_hubs_with_reason_under_transaction(
    state: &SharedState,
    reason: crate::hub::ExternalControllerReleaseReason,
) -> Result<()> {
    info!(target: "cmd", "hub_disconnect: clearing all hubs, credentials, and rooms");

    preflight_current_hue_recovery_state(state, HueRecoveryPreflightMode::ControllerRelease)
        .context("hub disconnect Hue recovery preflight failed")?;
    let release_keys = configured_or_active_hub_keys(state)?;
    prepare_external_controller_release(state, &release_keys, reason)?;
    let policy_keys = external_room_automation_policy_keys_for_disconnect(state, &release_keys)?;
    durably_forget_external_room_automation_policy(state, &policy_keys, reason)?;

    disconnect_hubs_after_external_controller_release(state)
}

/// Tear down local hub state after every authoritative external controller
/// has already completed its release gate.
///
/// Factory reset calls this only after the separate platform safety barrier;
/// ordinary disconnect and backup restore continue to use
/// [`do_hub_disconnect_with_reason`], which performs release immediately
/// before entering this local teardown.
fn disconnect_hubs_after_external_controller_release(state: &SharedState) -> Result<()> {
    let release_keys = configured_or_active_hub_keys(state)?;
    let hub_keys = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .hubs
        .keys()
        .cloned()
        .collect::<Vec<_>>();
    let discovered_native_ids = HashSet::new();
    for hub_key in &hub_keys {
        let _ = reconcile_hub_endpoint_visibility(state, hub_key, &discovered_native_ids)?;
    }

    // Finish every fallible local visibility update before crossing the
    // credential/finalization boundary. The authority-policy tombstone became
    // durable after controller release, so any failure here remains fail-closed
    // while credentials stay retryable.
    stage_hub_credential_deletion(state, None)?;
    finalize_external_controller_release(state, &release_keys)?;

    // Capture hub keys before clearing for SSE notifications
    let old_hubs;
    let mut topology_changed = false;

    {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;

        old_hubs = std::mem::take(&mut s.hubs);
        // Signal event workers synchronously. ActiveHub::drop also signals,
        // but the actual drops happen on a helper thread and therefore cannot
        // be the lifecycle boundary for platform cleanup.
        for hub in old_hubs.values() {
            hub.shutdown
                .store(true, std::sync::atomic::Ordering::SeqCst);
        }
        for key in old_hubs.keys() {
            topology_changed |= !s.topology.remove_stale_bindings(key, &[]).is_empty();
        }
        s.hub_connection_status.clear();
        s.external_controller_authority_required.clear();
        s.hub_seen_connected_once.clear();
        s.hub_pending_disconnect_at.clear();
        s.hub_startup_retry.clear();

        s.hub_credentials.clear();

        s.room_observed_power.clear();
        s.motion_snapshots.clear();

        if let Some(ref storage) = s.storage {
            let empty = rhythm_core::room::RoomManager::new();
            let _ = storage.save_rooms(&empty);
        }

        if topology_changed {
            persist_topology(&s);
        }
    }

    persist_registry(state);

    // Capture keys before old_hubs is moved into the drop thread
    let old_hub_keys: Vec<_> = old_hubs.keys().cloned().collect();

    // Clear all controllers from the composite
    {
        let composite = state
            .lock()
            .ok()
            .and_then(|s| s.composite_controller.clone());
        if let Some(composite) = composite {
            for key in &old_hub_keys {
                composite.remove_controller(&key.to_string());
            }
        }
        rebuild_composite_routing(state);
    }

    // Drop old hubs on a dedicated thread (reqwest::blocking::Client panics in tokio context)
    if !old_hubs.is_empty() {
        std::thread::Builder::new()
            .name("hub-drop".to_string())
            .spawn(move || drop(old_hubs))
            .ok();
    }

    {
        for key in &old_hub_keys {
            crate::state::emit_server_event(
                state,
                crate::server_event::ServerEvent::HubStatus {
                    hub_type: Some(key.hub_type.as_str().to_string()),
                    address: Some(key.address.clone()),
                    connected: false,
                },
            );
        }
        // Also emit a generic disconnected if no specific keys (fresh state)
        if old_hub_keys.is_empty() {
            crate::state::emit_server_event(
                state,
                crate::server_event::ServerEvent::HubStatus {
                    hub_type: None,
                    address: None,
                    connected: false,
                },
            );
        }
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    }

    Ok(())
}

/// Disconnect a single hub by type and address.
///
/// Removes only the matching hub. Other hubs remain connected.
/// Rooms owned by this hub are removed from the engine.
pub fn do_hub_disconnect_one(state: &SharedState, hub_type_str: &str, address: &str) -> Result<()> {
    use crate::canonical::identity::HubKey;

    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;

    info!(target: "cmd", "hub_disconnect_one: type={}, address={}", hub_type_str, address);

    let hub_type = crate::hub::HubType::parse(hub_type_str)
        .ok_or_else(|| anyhow::anyhow!("Unknown hub type: {}", hub_type_str))?;
    let key = HubKey::new(hub_type, address);
    preflight_current_hue_recovery_state(state, HueRecoveryPreflightMode::ControllerRelease)
        .context("hub disconnect Hue recovery preflight failed")?;
    prepare_external_controller_release(
        state,
        std::slice::from_ref(&key),
        crate::hub::ExternalControllerReleaseReason::UserDisconnect,
    )?;
    durably_forget_external_room_automation_policy(
        state,
        std::slice::from_ref(&key),
        crate::hub::ExternalControllerReleaseReason::UserDisconnect,
    )?;
    let discovered_native_ids = HashSet::new();
    let _ = reconcile_hub_endpoint_visibility(state, &key, &discovered_native_ids)?;
    stage_hub_credential_deletion(state, Some(std::slice::from_ref(&key)))
        .with_context(|| format!("preparing to disconnect {key}"))?;
    finalize_external_controller_release(state, std::slice::from_ref(&key))?;

    let old_hub;
    let topology_changed;

    {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;

        old_hub = s.hubs.remove(&key);
        if let Some(hub) = old_hub.as_ref() {
            hub.shutdown
                .store(true, std::sync::atomic::Ordering::SeqCst);
        }
        topology_changed = !s.topology.remove_stale_bindings(&key, &[]).is_empty();
        s.clear_hub_connected(&key);
        s.set_external_controller_authority_required(&key, false);
        s.clear_hub_startup_retry(&key);
        s.hub_credentials.remove(&key);

        if topology_changed {
            persist_topology(&s);
        }
    }

    persist_state(state);

    // Remove the hub's controller from the composite and rebuild routing
    {
        let composite = state
            .lock()
            .ok()
            .and_then(|s| s.composite_controller.clone());
        if let Some(composite) = composite {
            composite.remove_controller(&key.to_string());
            info!(target: "cmd", "Removed {} controller from composite", key);
        }
        rebuild_composite_routing(state);
    }

    // Drop old hub on a dedicated thread
    if let Some(hub) = old_hub {
        std::thread::Builder::new()
            .name("hub-drop".to_string())
            .spawn(move || drop(hub))
            .ok();
    }

    {
        crate::state::emit_server_event(
            state,
            crate::server_event::ServerEvent::HubStatus {
                hub_type: Some(hub_type_str.to_string()),
                address: Some(address.to_string()),
                connected: false,
            },
        );
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    }

    Ok(())
}

/// Update user preferences for an addressable node.
///
/// Only modifies user state, not topology. Safe for app to call without
/// overwriting server-discovered rooms/devices.
#[allow(clippy::too_many_arguments)]
pub fn do_node_preferences_set(
    state: &SharedState,
    node_id: &str,
    rhythm_enabled: Option<bool>,
    disabled: Option<bool>,
    standby_enabled: Option<bool>,
    target_state: Option<RoomModeState>,
    room_profile: Option<&RoomProfileSettingsPatch>,
    persist: bool,
) -> Result<String> {
    let node_write_lock = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.node_preference_write_locks
            .entry(node_id.to_string())
            .or_insert_with(|| Arc::new(std::sync::Mutex::new(())))
            .clone()
    };
    let _node_write_guard = node_write_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("node preference write lock"))?;

    info!(
        target: "cmd",
        "node_preferences_set: {} rhythm={:?} disabled={:?} standby={:?} state={:?} profile_settings={}",
        node_id,
        rhythm_enabled,
        disabled,
        standby_enabled,
        target_state,
        room_profile.is_some()
    );

    let (runtime, valid_profile_ids, valid_scene_ids) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (
            s.hub_runtime(),
            s.light_profile_configs
                .keys()
                .cloned()
                .collect::<HashSet<_>>(),
            s.scenes.keys().cloned().collect::<HashSet<_>>(),
        )
    };

    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;

    if let Some(expected) =
        room_profile.and_then(|patch| patch.expected_effective_profile_overrides.as_ref())
    {
        let current = runtime
            .engine_effective_node_snapshot(node_id)
            .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;
        if current.profile_settings.profile_overrides != *expected {
            return Err(anyhow::anyhow!(
                "node profile override precondition failed: live effective overrides changed"
            ));
        }
    }

    let snap = runtime
        .engine_node_snapshot(node_id)
        .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;
    let (lights_on, power_save) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (
            lights_on_from_observed_cache(
                &s,
                &s.room_observed_power,
                &snap.id,
                snap.kind,
                snap.parent_id.as_deref(),
                semantic_lights_on_override(
                    s.power_save,
                    &snap.profile_settings,
                    snap.hard_off,
                    snap.mood_active,
                    snap.soft_off,
                ),
            ),
            s.power_save,
        )
    };

    let prev_soft_off = snap.soft_off;
    let prev_mood_active = snap.mood_active;
    let prev_hard_off = snap.hard_off;
    let requested_rhythm_enabled = rhythm_enabled;
    let requested_standby_enabled = standby_enabled;
    let rhythm_enabled = requested_rhythm_enabled.unwrap_or(snap.rhythm_enabled);
    let disabled = disabled.unwrap_or(snap.disabled);
    let standby_enabled = standby_enabled.unwrap_or(snap.standby_enabled);
    let explicit_state_request = target_state.is_some();
    let current_persistent_state = persistent_room_state_for_settings(
        power_save,
        &snap.profile_settings,
        snap.hard_off,
        snap.mood_active,
        snap.soft_off,
    );
    let profile_settings_touched =
        room_profile.is_some_and(|patch| patch.touches_profile_settings());
    let lighting_output_settings_touched =
        room_profile.is_some_and(|patch| patch.touches_lighting_output_settings());
    let requests_nonempty_lighting_output_settings =
        room_profile.is_some_and(|patch| patch.requests_nonempty_lighting_output_settings());
    if snap.kind == LightNodeKind::LightDevice
        && snap.parent_id.is_some()
        && requests_nonempty_lighting_output_settings
    {
        let uses_parent_group_route = {
            let app = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            app.topology
                .attached_light_uses_parent_dispatch(node_id, &app.canonical_registry)
        };
        if uses_parent_group_route {
            return Err(anyhow::anyhow!(
                "Individual light preferences are unavailable because this light is controlled by its room"
            ));
        }
    }
    let motion_activation_enabled_before = snap.profile_settings.motion_activation_enabled();
    let motion_timeout_before = if profile_settings_touched {
        Some(resolved_motion_timeout_for_node_settings(
            state,
            &snap.profile_settings,
            runtime.current_hour(),
        )?)
    } else {
        None
    };
    let mut standby_toggle_state_request = false;
    let requested_state = match target_state {
        Some(state) => state,
        None if requested_standby_enabled == Some(true) && !lights_on => {
            standby_toggle_state_request = true;
            RoomModeState::Standby
        }
        None if requested_standby_enabled == Some(false)
            && current_persistent_state == RoomModeState::Standby =>
        {
            standby_toggle_state_request = true;
            RoomModeState::HardOff
        }
        None => current_persistent_state,
    };
    let mut profile_settings = snap.profile_settings.clone();
    if let Some(patch) = room_profile {
        patch.apply_to(&mut profile_settings);
    }
    let motion_activation_enabled_after = profile_settings.motion_activation_enabled();
    let persistent_state =
        room_state_for_mood_setting(power_save, &profile_settings, requested_state);
    let (soft_off, mood_active, hard_off) = room_flags_for_target_state(persistent_state)?;

    if let Some(profile_id) = profile_settings.profile_id.as_deref() {
        if rhythm_core::is_builtin_state_profile_id(profile_id) {
            return Err(anyhow::anyhow!(
                "State profiles cannot be selected per-node"
            ));
        }
        if !valid_profile_ids.contains(profile_id) {
            return Err(anyhow::anyhow!("Unknown light profile: {}", profile_id));
        }
    }
    if let Some(profile_id) = profile_settings.mood_profile_id.as_deref() {
        if !valid_profile_ids.contains(profile_id) {
            return Err(anyhow::anyhow!(
                "Unknown mood light profile: {}",
                profile_id
            ));
        }
    }
    if let Some(scene_id) = profile_settings.mood_scene_id.as_deref() {
        if !valid_scene_ids.contains(scene_id) && !is_native_scene_id(scene_id) {
            return Err(anyhow::anyhow!("Unknown light scene: {}", scene_id));
        }
    }
    for profile_id in profile_settings.profile_overrides.keys() {
        if rhythm_core::is_builtin_state_profile_id(profile_id) {
            return Err(anyhow::anyhow!(
                "State profiles cannot be overridden per-node"
            ));
        }
        if !valid_profile_ids.contains(profile_id) {
            return Err(anyhow::anyhow!(
                "Unknown overridden light profile: {}",
                profile_id
            ));
        }
    }

    let motion_timeout_after = if motion_timeout_before.is_some() {
        Some(resolved_motion_timeout_for_node_settings(
            state,
            &profile_settings,
            runtime.current_hour(),
        )?)
    } else {
        None
    };

    // Mood and Standby need rhythm enabled unless the caller explicitly pauses it.
    let rhythm_enabled = if (soft_off || mood_active) && requested_rhythm_enabled != Some(false) {
        true
    } else {
        rhythm_enabled
    };

    runtime.restore_node_state(
        node_id,
        RestoredNodeState {
            rhythm_enabled,
            disabled,
            time_offset_minutes: snap.time_offset_minutes,
            brightness_offset: snap.brightness_offset,
            soft_off,
            mood_active,
            standby_enabled,
            hard_off,
            profile_settings: profile_settings.clone(),
        },
    );
    clear_room_mode_transition(state, node_id);
    if explicit_state_request || standby_toggle_state_request {
        queue_motion_timer_clear(state, node_id);
    }
    if motion_timeout_before != motion_timeout_after {
        if let Some(timeout_secs) = motion_timeout_after {
            queue_motion_timer_timeout_refresh(state, node_id);
            refresh_cached_motion_timeout_after_settings_change(state, node_id, timeout_secs);
        }
    }
    if motion_activation_enabled_before != motion_activation_enabled_after {
        queue_motion_timer_clear(state, node_id);
    }

    let entered_hard_off = hard_off && !prev_hard_off;
    let left_hard_off = !hard_off && prev_hard_off;

    // State-changing commands already tell us the intended power state. Do
    // not immediately read the integration after enqueueing the write: the
    // read can race session establishment, contend with the command, and
    // return the pre-command value while dispatch is still pending.
    let mut commanded_lights_on = None;

    if entered_hard_off {
        info!(target: "cmd", "node_preferences_set: {} entering hard_off", node_id);
        queue_motion_timer_clear(state, node_id);
        let event = InputEvent::new(node_id, ButtonAction::LightsOff);
        if let Err(e) = runtime.handle_event(&event) {
            warn!(target: "cmd", "lights_off for '{}' failed: {}", node_id, e);
        } else {
            commanded_lights_on = Some(false);
        }
    } else if mood_active && !prev_mood_active {
        info!(target: "cmd", "node_preferences_set: {} entering mood", node_id);
        if let Err(e) = apply_mood_scene_or_tick(
            state,
            &runtime,
            node_id,
            profile_settings.mood_scene_id.as_deref(),
            false,
        ) {
            warn!(target: "cmd", "mood apply for '{}' failed: {}", node_id, e);
        } else {
            commanded_lights_on = Some(true);
        }
    } else if soft_off && !prev_soft_off {
        info!(target: "cmd", "node_preferences_set: {} entering standby", node_id);
        if let Err(e) = runtime.soft_off_tick_room(node_id) {
            warn!(target: "cmd", "standby_tick for '{}' failed: {}", node_id, e);
        } else {
            commanded_lights_on = Some(true);
        }
    } else if (!soft_off && prev_soft_off) || (!mood_active && prev_mood_active) {
        info!(target: "cmd", "node_preferences_set: {} leaving mood/standby, turning on", node_id);
        if let Err(e) = runtime.turn_on_room(node_id) {
            warn!(target: "cmd", "turn_on for '{}' failed: {}", node_id, e);
        } else {
            commanded_lights_on = Some(true);
        }
    } else if left_hard_off {
        match persistent_state {
            RoomModeState::Active => {
                info!(target: "cmd", "node_preferences_set: {} leaving hard_off to active", node_id);
                if let Err(e) = runtime.turn_on_room(node_id) {
                    warn!(target: "cmd", "turn_on for '{}' failed: {}", node_id, e);
                } else {
                    commanded_lights_on = Some(true);
                }
            }
            RoomModeState::Mood => {
                info!(target: "cmd", "node_preferences_set: {} leaving hard_off to mood", node_id);
                if let Err(e) = apply_mood_scene_or_tick(
                    state,
                    &runtime,
                    node_id,
                    profile_settings.mood_scene_id.as_deref(),
                    false,
                ) {
                    warn!(target: "cmd", "mood apply for '{}' failed: {}", node_id, e);
                } else {
                    commanded_lights_on = Some(true);
                }
            }
            RoomModeState::Standby => {
                info!(target: "cmd", "node_preferences_set: {} leaving hard_off to standby", node_id);
                if let Err(e) = runtime.soft_off_tick_room(node_id) {
                    warn!(target: "cmd", "standby_tick for '{}' failed: {}", node_id, e);
                } else {
                    commanded_lights_on = Some(true);
                }
            }
            RoomModeState::HardOff | RoomModeState::Wake | RoomModeState::Warning => {}
        }
    } else if lighting_output_settings_touched {
        match persistent_state {
            RoomModeState::Mood => {
                info!(target: "cmd", "node_preferences_set: {} applying profile settings to mood", node_id);
                if let Err(e) = apply_mood_scene_or_tick(
                    state,
                    &runtime,
                    node_id,
                    profile_settings.mood_scene_id.as_deref(),
                    false,
                ) {
                    warn!(target: "cmd", "mood apply for '{}' failed: {}", node_id, e);
                } else {
                    commanded_lights_on = Some(true);
                }
            }
            RoomModeState::Standby => {
                info!(target: "cmd", "node_preferences_set: {} applying profile settings to standby", node_id);
                if let Err(e) = runtime.soft_off_tick_room(node_id) {
                    warn!(target: "cmd", "standby_tick for '{}' failed: {}", node_id, e);
                } else {
                    commanded_lights_on = Some(true);
                }
            }
            RoomModeState::Active if lights_on => {
                info!(target: "cmd", "node_preferences_set: {} applying profile settings to active lights", node_id);
                if let Err(e) = runtime.turn_on_room(node_id) {
                    warn!(target: "cmd", "turn_on for '{}' failed: {}", node_id, e);
                } else {
                    commanded_lights_on = Some(true);
                }
            }
            RoomModeState::HardOff
            | RoomModeState::Wake
            | RoomModeState::Warning
            | RoomModeState::Active => {}
        }
    }

    if let Some(lights_on) = commanded_lights_on {
        update_lights_on_cache_for_runtime_node(state, &runtime, node_id, lights_on);
    }

    {
        emit_node_state_event_after_apply(state, &runtime, node_id);
    }

    if persist {
        persist_rooms(state);
    }

    build_node_state(state, node_id).and_then(|node_state| {
        serde_json::to_string(&node_state).map_err(|e| anyhow::anyhow!("serialize: {}", e))
    })
}

#[derive(Clone)]
pub struct QueuedNodePreferencesPatch {
    pub node_id: String,
    pub rhythm_enabled: Option<bool>,
    pub disabled: Option<bool>,
    pub standby_enabled: Option<bool>,
    pub target_state: Option<RoomModeState>,
    pub room_profile: Option<RoomProfileSettingsPatch>,
}

fn validate_room_profile_settings_patch(
    room_profile: Option<&RoomProfileSettingsPatch>,
    valid_profile_ids: &HashSet<String>,
    valid_scene_ids: &HashSet<String>,
) -> Result<()> {
    if let Some(profile_id) = room_profile
        .and_then(|patch| patch.profile_id.as_ref())
        .and_then(|profile_id| profile_id.as_deref())
    {
        if rhythm_core::is_builtin_state_profile_id(profile_id) {
            return Err(anyhow::anyhow!(
                "State profiles cannot be selected per-node"
            ));
        }
        if !valid_profile_ids.contains(profile_id) {
            return Err(anyhow::anyhow!("Unknown light profile: {}", profile_id));
        }
    }
    if let Some(profile_id) = room_profile
        .and_then(|patch| patch.mood_profile_id.as_ref())
        .and_then(|profile_id| profile_id.as_deref())
    {
        if !valid_profile_ids.contains(profile_id) {
            return Err(anyhow::anyhow!(
                "Unknown mood light profile: {}",
                profile_id
            ));
        }
    }
    if let Some(scene_id) = room_profile
        .and_then(|patch| patch.mood_scene_id.as_ref())
        .and_then(|scene_id| scene_id.as_deref())
    {
        if !valid_scene_ids.contains(scene_id) && !is_native_scene_id(scene_id) {
            return Err(anyhow::anyhow!("Unknown light scene: {}", scene_id));
        }
    }
    if let Some(profile_overrides) = room_profile
        .and_then(|patch| patch.profile_overrides.as_ref())
        .and_then(|profile_overrides| profile_overrides.as_ref())
    {
        for profile_id in profile_overrides.keys() {
            if rhythm_core::is_builtin_state_profile_id(profile_id) {
                return Err(anyhow::anyhow!(
                    "State profiles cannot be overridden per-node"
                ));
            }
            if !valid_profile_ids.contains(profile_id) {
                return Err(anyhow::anyhow!(
                    "Unknown overridden light profile: {}",
                    profile_id
                ));
            }
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
pub fn queue_node_preferences_set(
    state: &SharedState,
    node_id: &str,
    rhythm_enabled: Option<bool>,
    disabled: Option<bool>,
    standby_enabled: Option<bool>,
    target_state: Option<RoomModeState>,
    room_profile: Option<RoomProfileSettingsPatch>,
    persist_after: bool,
    dispatch_spacing: Duration,
) -> Result<()> {
    let (runtime, tx) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        (s.hub_runtime(), s.work_tx.clone())
    };
    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;
    runtime
        .engine_node_snapshot(node_id)
        .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", node_id))?;
    let tx = tx.ok_or_else(|| anyhow::anyhow!("Node dispatch queue unavailable"))?;

    try_send_work_item_with_pending(
        state,
        &tx,
        WorkItem::SetNodePreferences {
            command_id: crate::logging::next_command_id("node-preferences"),
            node_id: node_id.to_string(),
            rhythm_enabled,
            disabled,
            standby_enabled,
            target_state,
            room_profile,
            dispatch_spacing,
            persist_after,
        },
    )
    .map_err(|e| anyhow::anyhow!("Node dispatch queue unavailable: {}", e))
}

pub fn queue_node_preferences_batch(
    state: &SharedState,
    updates: Vec<QueuedNodePreferencesPatch>,
    persist_after: bool,
    dispatch_spacing: Duration,
) -> Result<()> {
    let (runtime, valid_profile_ids, valid_scene_ids) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if s.work_tx.is_none() {
            return Err(anyhow::anyhow!("Node dispatch queue unavailable"));
        }
        (
            s.hub_runtime(),
            s.light_profile_configs
                .keys()
                .cloned()
                .collect::<HashSet<_>>(),
            s.scenes.keys().cloned().collect::<HashSet<_>>(),
        )
    };
    let runtime = runtime.ok_or_else(|| anyhow::anyhow!("No runtime available"))?;

    let mut work_items = Vec::with_capacity(updates.len() + usize::from(persist_after));
    for update in updates {
        runtime
            .engine_node_snapshot(&update.node_id)
            .ok_or_else(|| anyhow::anyhow!("Node '{}' not found in engine", update.node_id))?;
        validate_room_profile_settings_patch(
            update.room_profile.as_ref(),
            &valid_profile_ids,
            &valid_scene_ids,
        )?;
        work_items.push(WorkItem::SetNodePreferences {
            command_id: crate::logging::next_command_id("node-preferences"),
            node_id: update.node_id,
            rhythm_enabled: update.rhythm_enabled,
            disabled: update.disabled,
            standby_enabled: update.standby_enabled,
            target_state: update.target_state,
            room_profile: update.room_profile,
            dispatch_spacing,
            persist_after: false,
        });
    }

    queue_node_dispatch_batch(
        state,
        "node_preferences_batch",
        work_items,
        persist_after,
        dispatch_spacing,
    )
}

// ============================================================================
// Runtime initialization helper
// ============================================================================

/// Call the platform's ensure_runtime callback in a thread with adequate stack.
///
/// The callback is stored on AppState (as an `Arc`) and set by the platform
/// crate at startup. It handles creating the RhythmRuntime with platform-specific types.
pub fn ensure_runtime(state: &SharedState) {
    if let Err(e) = try_ensure_runtime(state) {
        warn!(target: "cmd", "Failed to start runtime: {}", e);
    }
}

/// Call the platform's ensure_runtime callback and surface bootstrap failures.
pub fn try_ensure_runtime(state: &SharedState) -> Result<()> {
    let ensure_fn = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.ensure_runtime_fn.clone()
    };

    let Some(ensure_fn) = ensure_fn else {
        return Err(anyhow::anyhow!("No runtime initializer configured"));
    };

    let rt_state = state.clone();
    let rt_result = std::thread::Builder::new()
        .name("rt-init".to_string())
        .spawn(move || ensure_fn(&rt_state))
        .and_then(|handle| handle.join().map_err(|_| std::io::Error::other("panicked")));

    match rt_result {
        Ok(Ok(())) => Ok(()),
        Ok(Err(e)) => Err(e),
        Err(e) => Err(anyhow::anyhow!("Runtime init thread error: {}", e)),
    }
}

/// Ensure the shared runtime exists and contains the given topology room.
///
/// Matter can route directly by device endpoint and discover zero hub rooms, so
/// runtime creation cannot rely solely on `do_room_set()` during room sync.
pub(crate) fn ensure_runtime_room_exists(
    state: &SharedState,
    room_id: &str,
    room_name: &str,
) -> Result<()> {
    let needs_runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let has_runtime = s.hubs.values().any(|h| h.runtime.is_some());
        !has_runtime && s.has_any_hub()
    };

    if needs_runtime {
        try_ensure_runtime(state)?;
    }

    if let Some(runtime) = state.lock().ok().and_then(|s| s.hub_runtime()) {
        let existed = runtime.engine_room_snapshot(room_id).is_some();
        runtime.add_room(room_id, room_name);
        if !existed {
            runtime.restore_room_state(
                room_id,
                RestoredRoomState {
                    rhythm_enabled: true,
                    disabled: false,
                    time_offset_minutes: 0.0,
                    brightness_offset: 0.0,
                    soft_off: false,
                    mood_active: false,
                    standby_enabled: false,
                    hard_off: false,
                    profile_settings: RoomProfileSettings::default(),
                },
            );
            debug!(
                target: "cmd",
                "Ensured runtime room '{}' exists as '{}'",
                room_id,
                room_name
            );
        }
    }

    let has_any_hub = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .has_any_hub();
    if has_any_hub && state.lock().ok().and_then(|s| s.hub_runtime()).is_none() {
        return Err(anyhow::anyhow!(
            "Runtime initialization completed without installing a runtime"
        ));
    }

    Ok(())
}

/// Reconcile the shared runtime from topology + canonical state.
///
/// This is the explicit topology-first runtime phase that runs after sync and
/// after topology/manual mutations so integrations that discover devices
/// without rooms do not depend on incidental room bootstrap paths.
pub fn reconcile_runtime_from_state(state: &SharedState) -> Result<()> {
    let (has_any_hub, has_runtime_initializer, rooms, nodes) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let rooms = s
            .topology
            .rooms()
            .map(|room| (room.id.clone(), room.name.clone()))
            .collect::<Vec<_>>();
        let nodes = s
            .topology
            .device_nodes()
            .filter_map(|node| {
                let device = s.canonical_registry.get(&node.canonical_device_id)?;
                (!canonical_device_is_quarantined(&s, &node.canonical_device_id)).then(|| {
                    (
                        node.id.clone(),
                        device.name.clone(),
                        device.device_type.clone(),
                        node.parent_id.clone(),
                    )
                })
            })
            .collect::<Vec<_>>();
        (s.has_any_hub(), s.ensure_runtime_fn.is_some(), rooms, nodes)
    };

    let existing_runtime = state.lock().ok().and_then(|s| s.hub_runtime());
    let persisted_node_states: HashMap<String, rhythm_core::Room> = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.storage
            .as_ref()
            .and_then(|storage| storage.load_rooms().ok())
            .filter(|rooms| !crate::lifecycle::persisted_rooms_look_corrupted(rooms))
            .map(|rooms| {
                rooms
                    .iter()
                    .filter(|room| !crate::topology::is_internal_light_node_id(&room.id))
                    .map(|room| (room.id.clone(), room.clone()))
                    .collect()
            })
            .unwrap_or_default()
    };
    let existing_room_states: HashMap<String, rhythm_core::RoomSnapshot> = existing_runtime
        .as_ref()
        .map(|runtime| {
            runtime
                .engine_all_room_snapshots()
                .into_iter()
                .filter(|snap| !crate::topology::is_internal_light_node_id(&snap.id))
                .map(|snap| (snap.id.clone(), snap))
                .collect()
        })
        .unwrap_or_default();
    let existing_node_states: HashMap<String, rhythm_core::NodeSnapshot> = existing_runtime
        .as_ref()
        .map(|runtime| {
            runtime
                .engine_all_node_snapshots()
                .into_iter()
                .filter(|snap| !crate::topology::is_internal_light_node_id(&snap.id))
                .map(|snap| (snap.id.clone(), snap))
                .collect()
        })
        .unwrap_or_default();

    let needs_runtime = has_any_hub && (!rooms.is_empty() || !nodes.is_empty());
    if needs_runtime
        && has_runtime_initializer
        && state.lock().ok().and_then(|s| s.hub_runtime()).is_none()
    {
        try_ensure_runtime(state)?;
    }

    let has_runtime = state.lock().ok().and_then(|s| s.hub_runtime()).is_some();
    if needs_runtime && has_runtime_initializer && !has_runtime {
        return Err(anyhow::anyhow!(
            "Runtime reconciliation completed without installing a runtime"
        ));
    }

    if !has_runtime {
        return Ok(());
    }

    let runtime = state
        .lock()
        .ok()
        .and_then(|s| s.hub_runtime())
        .ok_or_else(|| anyhow::anyhow!("Runtime reconciliation expected a live runtime"))?;

    let desired_room_ids = rooms
        .iter()
        .map(|(room_id, _)| room_id.clone())
        .collect::<HashSet<_>>();
    let desired_node_ids = nodes
        .iter()
        .map(|(node_id, _, _, _)| node_id.clone())
        .collect::<HashSet<_>>();

    for snapshot in runtime.engine_all_room_snapshots() {
        if !desired_room_ids.contains(&snapshot.id) {
            runtime.remove_room(&snapshot.id);
        }
    }

    for snapshot in runtime.engine_all_node_snapshots() {
        if !desired_node_ids.contains(&snapshot.id) {
            runtime.remove_node(&snapshot.id);
        }
    }

    for (room_id, room_name) in rooms {
        ensure_runtime_room_exists(state, &room_id, &room_name)?;
        if let Some(snap) = existing_room_states.get(&room_id) {
            runtime.restore_room_state(&room_id, restored_room_state_from_snapshot(snap));
        } else if let Some(room) = persisted_node_states.get(&room_id) {
            runtime.restore_room_state(&room_id, restored_room_state_from_room(room));
        }
    }

    for (node_id, node_name, device_type, parent_id) in nodes {
        ensure_runtime_device_node_exists(state, &node_id, &node_name, device_type, parent_id)?;
        if let Some(snap) = existing_node_states.get(&node_id) {
            runtime.restore_node_state(&node_id, restored_node_state_from_snapshot(snap));
        } else if let Some(node) = persisted_node_states.get(&node_id) {
            runtime.restore_node_state(&node_id, restored_node_state_from_room(node));
        }
    }

    rebuild_composite_routing(state);
    schedule_topology_group_sync_for_integrations(state);
    apply_pending_mode_outputs_if_ready(state);

    Ok(())
}

fn fence_all_active_required_group_authority_uncertainty(state: &SharedState) {
    let hub_keys = state
        .lock()
        .map(|state| {
            state
                .hubs
                .keys()
                .filter(|key| state.topology.grouped_room_control_is_required(key))
                .cloned()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    for hub_key in hub_keys {
        crate::hub::fence_required_group_authority_uncertainty(state, &hub_key);
    }
}

fn run_topology_group_sync_for_integrations(state: &SharedState) {
    let callback = state
        .lock()
        .ok()
        .and_then(|state| state.sync_topology_groups_fn.clone());
    let Some(callback) = callback else {
        return;
    };

    match callback(state) {
        Ok(()) => {
            persist_registry(state);
            if let Ok(state) = state.lock() {
                persist_topology(&state);
            }
            // The sync may have upserted new hub-native group bindings into
            // topology (e.g. a Matter group). The composite routing table was
            // built from the pre-sync topology, so without this rebuild
            // dispatch keeps fanning out per-device until some unrelated
            // topology mutation triggers a rebuild.
            rebuild_composite_routing(state);
        }
        Err(error) => {
            // Integration callbacks fence the exact required-group key before
            // returning an uncertain native reconciliation failure. Fence all
            // active required-group keys here as a platform/custom-callback
            // backstop so no alternate wiring can weaken that contract.
            warn!(target: "cmd", "Topology group sync failed: {}", error);
            fence_all_active_required_group_authority_uncertainty(state);
        }
    }
}

fn schedule_topology_group_sync_for_integrations(state: &SharedState) {
    let should_spawn = {
        let Ok(mut state) = state.lock() else {
            return;
        };
        if state.sync_topology_groups_fn.is_none() {
            return;
        }

        state.topology_group_sync_pending = true;
        if state.topology_group_sync_in_progress {
            false
        } else {
            state.topology_group_sync_in_progress = true;
            true
        }
    };

    if !should_spawn {
        return;
    }

    let worker_state = state.clone();
    let spawn_result = std::thread::Builder::new()
        .name("topology-group-sync".to_string())
        .spawn(move || loop {
            let should_run = {
                let Ok(mut state) = worker_state.lock() else {
                    return;
                };
                if state.sync_topology_groups_fn.is_none() {
                    state.topology_group_sync_pending = false;
                    state.topology_group_sync_in_progress = false;
                    return;
                }
                if !state.topology_group_sync_pending {
                    state.topology_group_sync_in_progress = false;
                    return;
                }
                state.topology_group_sync_pending = false;
                true
            };

            if should_run {
                run_topology_group_sync_for_integrations(&worker_state);
            }
        });

    if let Err(error) = spawn_result {
        if let Ok(mut state) = state.lock() {
            state.topology_group_sync_in_progress = false;
        }
        warn!(target: "cmd", "Failed to start topology group sync worker: {}", error);
        // The caller has already committed the local topology mutation.  If
        // the acknowledgement worker cannot even start, required native
        // groups are now uncertain in exactly the same way as a failed sync.
        // Fence grouped authority until the normal bootstrap/reconcile path
        // proves the bridge matches the committed Rhythm topology.
        fence_all_active_required_group_authority_uncertainty(state);
    }
}

fn clear_runtime_node_off_flags(state: &SharedState, node_id: &str) -> Result<()> {
    let runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.hub_runtime()
    };
    let Some(runtime) = runtime else {
        return Ok(());
    };
    let Some(snap) = runtime.engine_node_snapshot(node_id) else {
        return Ok(());
    };
    if !snap.soft_off && !snap.hard_off {
        return Ok(());
    }

    runtime.restore_node_state(
        node_id,
        RestoredNodeState {
            rhythm_enabled: snap.rhythm_enabled,
            disabled: snap.disabled,
            time_offset_minutes: snap.time_offset_minutes,
            brightness_offset: snap.brightness_offset,
            soft_off: false,
            mood_active: false,
            standby_enabled: snap.standby_enabled,
            hard_off: false,
            profile_settings: snap.profile_settings,
        },
    );
    Ok(())
}

/// Whether a canonical device must stay outside user-visible runtime control
/// until its unassigned-device review is resolved.
pub(crate) fn canonical_device_is_quarantined(state: &AppState, canonical_device_id: &str) -> bool {
    state
        .canonical_registry
        .get(canonical_device_id)
        .is_some_and(|device| {
            device.room_id.is_none()
                && state
                    .canonical_registry
                    .triage()
                    .quarantines_unassigned_device(canonical_device_id)
        })
}

pub(crate) fn runtime_node_kind_for_device_type(device_type: DeviceType) -> LightNodeKind {
    match device_type {
        DeviceType::Light => LightNodeKind::LightDevice,
        DeviceType::Motion => LightNodeKind::MotionSensor,
        DeviceType::Button => LightNodeKind::Button,
        DeviceType::Contact => LightNodeKind::Sensor,
    }
}

pub(crate) fn ensure_runtime_device_node_exists(
    state: &SharedState,
    node_id: &str,
    node_name: &str,
    device_type: DeviceType,
    parent_id: Option<String>,
) -> Result<()> {
    let needs_runtime = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let has_runtime = s.hubs.values().any(|h| h.runtime.is_some());
        !has_runtime && s.has_any_hub()
    };

    if needs_runtime {
        try_ensure_runtime(state)?;
    }

    if let Some(runtime) = state.lock().ok().and_then(|s| s.hub_runtime()) {
        let existed = runtime.engine_node_snapshot(node_id).is_some();
        runtime.add_node(
            node_id,
            node_name,
            runtime_node_kind_for_device_type(device_type),
            parent_id,
        );
        if !existed {
            runtime.restore_node_state(
                node_id,
                RestoredNodeState {
                    rhythm_enabled: true,
                    disabled: false,
                    time_offset_minutes: 0.0,
                    brightness_offset: 0.0,
                    soft_off: false,
                    mood_active: false,
                    standby_enabled: false,
                    hard_off: false,
                    profile_settings: RoomProfileSettings::default(),
                },
            );
            debug!(target: "cmd", "Ensured runtime device node '{}' exists", node_id);
        }
    }

    Ok(())
}

// ============================================================================
// Composite controller registration
// ============================================================================

/// Rebuild the composite controller's routing table from topology.
///
/// Call after any operation that changes room-to-hub mappings: room sync,
/// hub connect/disconnect, topology merge/split/device-move.
fn composite_node_labels(s: &AppState) -> HashMap<String, String> {
    let mut labels = HashMap::new();

    let mut room_ids: Vec<_> = s.topology.rooms().map(|room| room.id.clone()).collect();
    room_ids.sort();
    for room_id in room_ids {
        let Some(room) = s.topology.get(&room_id) else {
            continue;
        };
        labels.insert(room.id.clone(), room.name.clone());
    }

    let mut device_ids: Vec<_> = s
        .topology
        .device_nodes()
        .map(|node| node.id.clone())
        .collect();
    device_ids.sort();
    for device_id in device_ids {
        let Some(node) = s.topology.get_device_node(&device_id) else {
            continue;
        };
        let label = s
            .canonical_registry
            .get(&node.canonical_device_id)
            .map(|device| device.name.clone())
            .unwrap_or_else(|| node.id.clone());
        labels.insert(node.id.clone(), label.clone());
    }

    for light_node in s.topology.periodic_light_nodes(&s.canonical_registry) {
        let label = s
            .topology
            .get(&light_node.source_node_id)
            .map(|room| room.name.clone())
            .or_else(|| {
                s.topology
                    .get_device_node(&light_node.source_node_id)
                    .and_then(|node| {
                        s.canonical_registry
                            .get(&node.canonical_device_id)
                            .map(|device| device.name.clone())
                    })
            });
        if let Some(label) = label {
            labels.insert(light_node.id, label);
        }
    }

    labels
}

pub fn rebuild_composite_routing(state: &SharedState) {
    let (composite, routing, labels, room_count) = {
        let Ok(s) = state.lock() else { return };
        let composite = match s.composite_controller.clone() {
            Some(c) => c,
            None => return, // No composite yet — nothing to rebuild
        };
        let active_hubs: HashSet<String> = s.hubs.keys().map(ToString::to_string).collect();
        let mut routing = s.topology.composite_routing(&s.canonical_registry);
        routing.retain(|_, targets| {
            targets.retain(|(hub_key, _)| active_hubs.contains(hub_key));
            !targets.is_empty()
        });
        let labels = composite_node_labels(&s);
        let rooms = s.topology.room_count();
        (composite, routing, labels, rooms)
    };
    let route_count = routing.len();
    composite.update_routing(routing);
    composite.update_node_labels(labels);
    info!(target: "cmd", "Rebuilt composite routing: {} rooms, {} route entries",
        room_count, route_count);
}

/// Register a newly connected hub's controller with the composite controller.
///
/// Called after `configure_hub` when a hub is added via HTTP while the server
/// is already running. If the composite controller doesn't exist yet (runtime
/// not created), this is a no-op — the controller will be picked up when
/// `ensure_composite_runtime` runs on first room arrival.
pub fn register_hub_with_composite(
    state: &SharedState,
    hub_key: &crate::canonical::identity::HubKey,
) {
    let register_fn = {
        let Ok(s) = state.lock() else { return };
        s.register_controller_fn.clone()
    };
    let Some(register_fn) = register_fn else {
        return;
    };

    match register_fn(state, hub_key) {
        Ok(()) => {
            // Assign the shared runtime to the new hub so hub_runtime_for() works
            {
                let Ok(mut s) = state.lock() else { return };
                let runtime = s.hubs.values().find_map(|h| h.runtime.clone());
                if let (Some(runtime), Some(hub)) = (runtime, s.hubs.get_mut(hub_key)) {
                    if hub.runtime.is_none() {
                        hub.runtime = Some(runtime);
                    }
                }
            }
            // Rebuild routing so existing topology rooms are routable via the new controller.
            // sync_from_hub_for_key() will rebuild again after discovery, but this
            // closes the window between registration and sync completion.
            rebuild_composite_routing(state);
        }
        Err(e) => {
            warn!(target: "cmd", "Failed to register controller for {}: {}", hub_key, e);
        }
    }
}

// ============================================================================
// Parse helpers
// ============================================================================

/// Parse button mappings from a JSON array.
pub fn parse_buttons(msg: &Value) -> Vec<(String, u8)> {
    msg.get("buttons")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|btn| {
                    let button_id = btn.get("button_id").and_then(|v| v.as_str())?;
                    let control_id = btn.get("control_id").and_then(|v| v.as_u64())? as u8;
                    Some((button_id.to_string(), control_id))
                })
                .collect()
        })
        .unwrap_or_default()
}

// ============================================================================
// Persistence helpers
// ============================================================================

/// Persist registry snapshot + room state.
pub fn persist_state(state: &SharedState) {
    persist_registry(state);
    persist_rooms(state);
}

/// Persist registry snapshot for all connected hubs.
///
/// Three-phase lock per hub to avoid holding AppState during JSON serialization + disk I/O:
/// 1. Brief AppState lock — extract registry Arcs + hub keys + check storage exists
/// 2. Registry lock only — snapshot to JSON (no AppState held)
/// 3. Brief AppState lock — write to storage (no registry lock)
pub fn persist_registry(state: &SharedState) {
    // Phase 1: Extract all hub registry Arcs + check storage (brief AppState lock)
    let (hub_registries, has_storage) = {
        let s = match state.lock() {
            Ok(s) => s,
            Err(_) => return,
        };
        let regs: Vec<_> = s
            .hubs
            .iter()
            .filter_map(|(key, hub)| hub.registry.as_ref().map(|r| (key.clone(), r.clone())))
            .collect();
        (regs, s.storage.is_some())
    };
    if !has_storage || hub_registries.is_empty() {
        return;
    }

    // Phase 2+3: Snapshot + save each hub's registry
    for (hub_key, reg_arc) in &hub_registries {
        let value = reg_arc.lock().ok().map(|reg| reg.snapshot_json());

        if let Some(ref value) = value {
            let s = match state.lock() {
                Ok(s) => s,
                Err(_) => return,
            };
            if let Some(ref storage) = s.storage {
                if let Err(e) = storage.save_hub_registry_for(hub_key, value) {
                    warn!(target: "cmd", "Failed to save registry for {}: {}", hub_key, e);
                }
            }
        }
    }
}

/// Persist room state.
pub fn persist_rooms(state: &SharedState) {
    let (runtime, has_storage) = {
        let s = match state.lock() {
            Ok(s) => s,
            Err(_) => return,
        };
        (s.hub_runtime(), s.storage.is_some())
    };

    if let (Some(ref runtime), true) = (runtime, has_storage) {
        let rooms = rooms_from_engine(runtime.as_ref());
        let s = match state.lock() {
            Ok(s) => s,
            Err(_) => return,
        };
        if let Some(ref storage) = s.storage {
            if let Err(e) = storage.save_rooms(&rooms) {
                warn!(target: "cmd", "Failed to save rooms: {}", e);
            }
        }
    }
}

// ============================================================================
// Canonical device commands
// ============================================================================

fn reconcile_automatic_light_names_best_effort(
    state: &SharedState,
    scope: &LightNameReconciliationScope,
) {
    if let Err(error) = crate::device_naming::reconcile_automatic_light_names(state, scope) {
        warn!(
            target: "device_naming",
            "automatic_light_name_reconciliation_failed stage=planning error={}",
            error
        );
    }
}

/// Build JSON for all canonical devices.
pub fn build_canonical_devices(state: &SharedState) -> Result<String> {
    // Snapshot while holding the shared-state lock, then serialize outside it.
    // Canonical payloads can be large on established homes, and an HTTP client
    // should not prevent BLE/discovery work from updating shared state while
    // serde walks the complete registry.
    let devices: Vec<_> = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.canonical_registry.devices().cloned().collect()
    };
    serde_json::to_string(&devices).map_err(|e| anyhow::anyhow!(e))
}

/// Build JSON for a single canonical device.
pub fn build_canonical_device(state: &SharedState, id: &str) -> Result<String> {
    let device = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.canonical_registry.get(id).cloned()
    };
    match device {
        Some(device) => serde_json::to_string(&device).map_err(|e| anyhow::anyhow!(e)),
        None => Err(anyhow::anyhow!("Device not found: {}", id)),
    }
}

/// Rename a canonical device and refresh runtime/topology views.
pub fn do_canonical_rename_device(state: &SharedState, device_id: &str, name: &str) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let trimmed = name.trim();
    if trimmed.is_empty() {
        return Err(anyhow::anyhow!("Device name cannot be empty"));
    }

    {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if !s
            .canonical_registry
            .rename_device_by_user(device_id, trimmed)
        {
            return Err(anyhow::anyhow!("Device not found: {}", device_id));
        }
        persist_canonical(&s);
    }

    reconcile_runtime_from_state(state)?;
    crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    Ok(())
}

/// Flash a canonical light device for physical identification.
///
/// The operation dispatches directly to the device's preferred integration
/// endpoint and intentionally does not mutate Rhythm's runtime or persisted
/// node state.
pub fn do_flash_canonical_device(state: &SharedState, device_id: &str) -> Result<()> {
    let (device_name, hub_key, native_id) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let device = s
            .canonical_registry
            .get(device_id)
            .filter(|device| !device.is_removed())
            .ok_or_else(|| anyhow::anyhow!("Device not found: {}", device_id))?;

        if device.device_type != DeviceType::Light {
            return Err(anyhow::anyhow!(
                "Flash is only supported for light devices: {}",
                device_id
            ));
        }

        let endpoint = device
            .preferred_endpoint()
            .ok_or_else(|| anyhow::anyhow!("Device has no active endpoint: {}", device_id))?;

        (
            device.name.clone(),
            endpoint.hub_key.clone(),
            endpoint.native_id.clone(),
        )
    };

    let composite = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        s.composite_controller.clone()
    };

    let composite = match composite {
        Some(composite) => composite,
        None => {
            try_ensure_runtime(state)?;
            state
                .lock()
                .ok()
                .and_then(|s| s.composite_controller.clone())
                .ok_or_else(|| {
                    anyhow::anyhow!(
                        "Runtime initialization reported success but no composite controller is available"
                    )
                })?
        }
    };

    let target = HubDispatchTarget::Devices {
        native_ids: vec![native_id.clone()],
    };
    let hub_key_label = hub_key.to_string();

    info!(
        target: "cmd",
        "device_flash: {} ({}) via {}:{}",
        device_name,
        device_id,
        hub_key_label,
        native_id
    );

    futures::executor::block_on(composite.flash_target(&hub_key_label, target))
        .map_err(|e| anyhow::anyhow!("Failed to flash device {}: {}", device_id, e))
}

/// Per-device synthetic hub-registry rooms.
///
/// Light controllers address standalone (room-less) devices through
/// `get_grouped_light_id(native_id)`, which only returns a target if a
/// synthetic room keyed by the device's native_id exists. We keep this
/// behavior for light output addressing.
///
/// Event routing no longer depends on these synthetic rooms — buttons and
/// motion sensors resolve through canonical + topology directly — so this
/// helper is a no-op for non-Light device types.
fn ensure_synthetic_device_registry_rooms(
    s: &mut AppState,
    device_type: &rhythm_core::runtime::hub_registry::DeviceType,
    device_name: &str,
    endpoints: &[crate::canonical::identity::IntegrationEndpoint],
) {
    use rhythm_core::runtime::hub_registry::DeviceType;
    if !matches!(device_type, DeviceType::Light) {
        // Drop any stale synthetic room left over from older code that created
        // them for every device type. Topology owns event routing now.
        for endpoint in endpoints {
            if let Some(hub) = s.hubs.get(&endpoint.hub_key) {
                if let Some(reg) = &hub.registry {
                    if let Ok(mut registry) = reg.lock() {
                        registry.remove_room(&endpoint.native_id);
                    }
                }
            }
        }
        return;
    }

    for endpoint in endpoints {
        if let Some(hub) = s.hubs.get(&endpoint.hub_key) {
            if let Some(reg) = &hub.registry {
                if let Ok(mut registry) = reg.lock() {
                    registry.remove_room(&endpoint.native_id);
                    registry.upsert_room(
                        &endpoint.native_id,
                        device_name,
                        &endpoint.native_id,
                        std::slice::from_ref(&endpoint.native_id),
                    );
                }
            }
        }
    }
}

/// Propagate a Rhythm room assignment to each endpoint's hub-side
/// `device_rooms` map so button/motion events route correctly.
///
/// `room_id == None` clears the mapping (events go unrouted until a room is
/// assigned). The hub-native room IDs that arrived via discovery are
/// overridden with the Rhythm room ID — this is the routing source of truth
/// for typed devices.
fn sync_endpoint_device_rooms(
    s: &mut AppState,
    endpoints: &[crate::canonical::identity::IntegrationEndpoint],
    room_id: Option<&str>,
) {
    for endpoint in endpoints {
        if let Some(hub) = s.hubs.get(&endpoint.hub_key) {
            if let Some(reg) = &hub.registry {
                if let Ok(mut registry) = reg.lock() {
                    match room_id {
                        Some(rid) => registry.set_device_room(&endpoint.native_id, rid),
                        None => registry.clear_device_room(&endpoint.native_id),
                    }
                }
            }
        }
    }
}

fn build_hub_device_room_assignments(
    state: &AppState,
    device: &crate::canonical::identity::CanonicalDevice,
    room_id: Option<&str>,
) -> Vec<crate::hub::HubDeviceRoomAssignment> {
    let preferred_endpoint = device.preferred_endpoint();
    device
        .active_endpoints()
        .map(|endpoint| {
            let mut target_hub_room_ids = room_id
                .and_then(|target_room_id| state.topology.get(target_room_id))
                .map(|target_room| {
                    target_room
                        .hub_room_bindings
                        .iter()
                        .filter(|binding| binding.hub_key == endpoint.hub_key)
                        .map(|binding| binding.hub_room_id.clone())
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            target_hub_room_ids.sort();
            target_hub_room_ids.dedup();
            crate::hub::HubDeviceRoomAssignment {
                hub_key: endpoint.hub_key.clone(),
                native_device_id: endpoint.native_id.clone(),
                device_type: device.device_type.clone(),
                preferred_for_control: preferred_endpoint.is_some_and(|preferred| {
                    preferred.hub_key == endpoint.hub_key
                        && preferred.native_id == endpoint.native_id
                }),
                target_rhythm_room_id: room_id.map(str::to_string),
                target_hub_room_ids,
            }
        })
        .collect()
}

struct PreparedHubDeviceRoomAssignment {
    assignment: crate::hub::HubDeviceRoomAssignment,
    target: Option<PreparedHubDeviceRoomTarget>,
    rollback: Option<crate::hub::HubDeviceRoomAssignmentRollback>,
}

enum PreparedHubDeviceRoomTarget {
    Existing(Option<String>),
    Authoritative {
        target_binding: Option<crate::topology::HubRoomBinding>,
        managed_by_rhythm: bool,
    },
}

fn rollback_prepared_hub_device_room_assignments(
    state: &SharedState,
    prepared: Vec<PreparedHubDeviceRoomAssignment>,
    primary_error: anyhow::Error,
) -> anyhow::Error {
    let mut rollback_failure_count = 0usize;
    let mut uncertain_hub_keys = HashSet::new();
    for prepared in prepared.into_iter().rev() {
        let Some(rollback) = prepared.rollback else {
            continue;
        };
        if rollback().is_err() {
            log::error!(
                target: "hub_room_assignment",
                "A native room-assignment rollback failed; recovery state was retained"
            );
            rollback_failure_count += 1;
            uncertain_hub_keys.insert(prepared.assignment.hub_key);
        }
    }

    for hub_key in uncertain_hub_keys {
        crate::hub::fence_required_group_authority_uncertainty(state, &hub_key);
    }

    if rollback_failure_count == 0 {
        primary_error
    } else {
        anyhow::anyhow!(
            "{primary_error:#}; {} native rollback operation(s) also failed",
            rollback_failure_count
        )
    }
}

fn prepare_hub_device_room_assignments<F>(
    state: &SharedState,
    assignments: &[crate::hub::HubDeviceRoomAssignment],
    prepare: Option<&F>,
) -> Result<Vec<PreparedHubDeviceRoomAssignment>>
where
    F: Fn(
            &SharedState,
            &crate::hub::HubDeviceRoomAssignment,
        ) -> Result<crate::hub::HubDeviceRoomAssignmentOutcome>
        + ?Sized,
{
    let mut prepared_assignments = Vec::new();
    for assignment in assignments {
        let grouped_control_required = match state.lock() {
            Ok(state) => state
                .topology
                .grouped_room_control_is_required(&assignment.hub_key),
            Err(_) => {
                return Err(rollback_prepared_hub_device_room_assignments(
                    state,
                    prepared_assignments,
                    anyhow::anyhow!("lock"),
                ));
            }
        };
        let Some(prepare) = prepare else {
            if grouped_control_required && matches!(assignment.device_type, DeviceType::Light) {
                return Err(rollback_prepared_hub_device_room_assignments(
                    state,
                    prepared_assignments,
                    anyhow::anyhow!(
                        "Integration requires grouped room control but no authoritative assignment callback is installed"
                    ),
                ));
            }
            continue;
        };

        let outcome = match prepare(state, assignment) {
            Ok(outcome) => outcome,
            Err(error) => {
                return Err(rollback_prepared_hub_device_room_assignments(
                    state,
                    prepared_assignments,
                    error,
                ));
            }
        };
        match outcome {
            crate::hub::HubDeviceRoomAssignmentOutcome::Unchanged => {
                prepared_assignments.push(PreparedHubDeviceRoomAssignment {
                    assignment: assignment.clone(),
                    target: None,
                    rollback: None,
                });
            }
            crate::hub::HubDeviceRoomAssignmentOutcome::Reassigned {
                target_hub_room_id,
                rollback,
            } => {
                let valid_target = match assignment.target_rhythm_room_id.as_deref() {
                    Some(_) => match target_hub_room_id.as_ref() {
                        Some(target) => assignment.target_hub_room_ids.contains(target),
                        None => assignment.target_hub_room_ids.is_empty(),
                    },
                    None => target_hub_room_id.is_none(),
                };
                prepared_assignments.push(PreparedHubDeviceRoomAssignment {
                    assignment: assignment.clone(),
                    target: Some(PreparedHubDeviceRoomTarget::Existing(target_hub_room_id)),
                    rollback: Some(rollback),
                });
                if !valid_target {
                    return Err(rollback_prepared_hub_device_room_assignments(
                        state,
                        prepared_assignments,
                        anyhow::anyhow!(
                            "Integration returned a native room outside the requested Rhythm target"
                        ),
                    ));
                }
            }
            crate::hub::HubDeviceRoomAssignmentOutcome::ReassignedWithBinding {
                target_binding,
                managed_by_rhythm,
                rollback,
            } => {
                let valid_target = match (
                    assignment.target_rhythm_room_id.as_deref(),
                    target_binding.as_ref(),
                ) {
                    (Some(_), Some(binding)) => {
                        binding.hub_key == assignment.hub_key
                            && !binding.hub_room_id.is_empty()
                            && !binding.control_id.is_empty()
                            && binding
                                .light_device_ids
                                .iter()
                                .any(|device_id| device_id == &assignment.native_device_id)
                    }
                    (None, None) => true,
                    _ => false,
                };
                let valid_target = valid_target && managed_by_rhythm;
                prepared_assignments.push(PreparedHubDeviceRoomAssignment {
                    assignment: assignment.clone(),
                    target: Some(PreparedHubDeviceRoomTarget::Authoritative {
                        target_binding,
                        managed_by_rhythm,
                    }),
                    rollback: Some(rollback),
                });
                if !valid_target {
                    return Err(rollback_prepared_hub_device_room_assignments(
                        state,
                        prepared_assignments,
                        anyhow::anyhow!(
                            "Integration returned an invalid authoritative native room binding"
                        ),
                    ));
                }
            }
        }

        if grouped_control_required
            && matches!(assignment.device_type, DeviceType::Light)
            && !matches!(
                prepared_assignments
                    .last()
                    .and_then(|prepared| prepared.target.as_ref()),
                Some(PreparedHubDeviceRoomTarget::Authoritative { .. })
            )
        {
            return Err(rollback_prepared_hub_device_room_assignments(
                state,
                prepared_assignments,
                anyhow::anyhow!(
                    "Integration requires grouped room control but did not return an authoritative binding"
                ),
            ));
        }
    }
    Ok(prepared_assignments)
}

fn mirror_prepared_hub_device_room_assignments(
    topology: &mut crate::topology::RoomTopologyStore,
    prepared_assignments: &[PreparedHubDeviceRoomAssignment],
) -> bool {
    for prepared in prepared_assignments {
        if !matches!(prepared.assignment.device_type, DeviceType::Light) {
            continue;
        }
        let mirror_succeeded = match &prepared.target {
            None => true,
            Some(PreparedHubDeviceRoomTarget::Existing(target_hub_room_id)) => topology
                .reassign_hub_light_device(
                    &prepared.assignment.hub_key,
                    &prepared.assignment.native_device_id,
                    prepared.assignment.target_rhythm_room_id.as_deref(),
                    target_hub_room_id.as_deref(),
                ),
            Some(PreparedHubDeviceRoomTarget::Authoritative {
                target_binding,
                managed_by_rhythm,
            }) => topology.apply_authoritative_hub_light_binding(
                &prepared.assignment.hub_key,
                &prepared.assignment.native_device_id,
                prepared.assignment.target_rhythm_room_id.as_deref(),
                target_binding.clone(),
                *managed_by_rhythm,
            ),
        };
        if !mirror_succeeded {
            return false;
        }
    }
    true
}

/// Assign a canonical device to a Rhythm room (or unassign with None).
///
/// Updates the canonical registry AND the topology so the composite routing
/// includes hub targets for the device's endpoints in the assigned room.
pub fn do_canonical_assign_room(
    state: &SharedState,
    device_id: &str,
    room_id: Option<&str>,
) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let (assignments, source_room_id, prepare_hub_device_room_assignment_fn) = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let device = s
            .canonical_registry
            .get(device_id)
            .ok_or_else(|| anyhow::anyhow!("Device not found: {}", device_id))?;

        if let Some(target_room_id) = room_id {
            if s.topology.get(target_room_id).is_none() {
                return Err(anyhow::anyhow!("Room not found: {}", target_room_id));
            }
        }

        let assignments = build_hub_device_room_assignments(&s, device, room_id);
        let source_room_id = s
            .topology
            .device_parent_room_id(device_id)
            .map(str::to_string)
            .or_else(|| device.room_id.clone());
        (
            assignments,
            source_room_id,
            s.prepare_hub_device_room_assignment_fn.clone(),
        )
    };

    let prepared_assignments = prepare_hub_device_room_assignments(
        state,
        &assignments,
        prepare_hub_device_room_assignment_fn.as_deref(),
    )?;

    let mut s = match state.lock() {
        Ok(state) => state,
        Err(_) => {
            return Err(rollback_prepared_hub_device_room_assignments(
                state,
                prepared_assignments,
                anyhow::anyhow!("lock"),
            ));
        }
    };

    let state_is_unchanged = s.canonical_registry.get(device_id).is_some_and(|device| {
        let current_room_id = s
            .topology
            .device_parent_room_id(device_id)
            .map(str::to_string)
            .or_else(|| device.room_id.clone());
        current_room_id == source_room_id
            && build_hub_device_room_assignments(&s, device, room_id) == assignments
    });
    if !state_is_unchanged {
        drop(s);
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            anyhow::anyhow!(
                "Device or room topology changed while native room assignment was in progress"
            ),
        ));
    }

    // Snapshot endpoints and old room before mutating.
    let device = s
        .canonical_registry
        .get(device_id)
        .ok_or_else(|| anyhow::anyhow!("Device not found: {}", device_id))?;
    let active_endpoints: Vec<_> = device.active_endpoints().cloned().collect();
    let device_name = device.name.clone();
    let device_type = device.device_type.clone();
    let was_topology_standalone = s.topology.device_parent_room_id(device_id).is_none();
    let assigning_standalone_light_child =
        room_id.is_some() && was_topology_standalone && matches!(&device_type, DeviceType::Light);
    let sleep_default_node_to_seed =
        matches!(&device_type, DeviceType::Light).then(|| room_id.unwrap_or(device_id).to_string());
    let old_room_id = s
        .topology
        .device_parent_room_id(device_id)
        .map(|id| id.to_string())
        .or_else(|| device.room_id.clone());
    // Pre-mutation effective motion target so we can clear stale motion-timer
    // state on the room a motion sensor is leaving (and on the new room if
    // the effective target also changes there).
    let old_motion_target = if matches!(device_type, DeviceType::Motion) {
        Some(
            s.topology
                .effective_control_target(device_id, &NodeControlKind::Motion),
        )
    } else {
        None
    };

    if let Some(target_room_id) = room_id {
        if s.topology.get(target_room_id).is_none() {
            drop(s);
            return Err(rollback_prepared_hub_device_room_assignments(
                state,
                prepared_assignments,
                anyhow::anyhow!("Room not found: {}", target_room_id),
            ));
        }
    }

    let topology_before_assignment = s.topology.clone();
    let canonical_before_assignment = s.canonical_registry.clone();
    if !mirror_prepared_hub_device_room_assignments(&mut s.topology, &prepared_assignments) {
        s.topology = topology_before_assignment;
        drop(s);
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            anyhow::anyhow!(
                "Native room reassignment succeeded but its target-room binding could not be mirrored"
            ),
        ));
    }

    if !s.canonical_registry.assign_room(device_id, room_id) {
        s.topology = topology_before_assignment;
        drop(s);
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            anyhow::anyhow!("Device not found: {}", device_id),
        ));
    }

    if let Some(target_room_id) = room_id {
        if !s.topology.assign_device(
            device_id,
            Some(target_room_id),
            crate::topology::DevicePlacement::UserOverride,
        ) {
            s.topology.ensure_standalone_device(device_id);
            if !s.topology.assign_device(
                device_id,
                Some(target_room_id),
                crate::topology::DevicePlacement::UserOverride,
            ) {
                s.topology = topology_before_assignment;
                s.canonical_registry = canonical_before_assignment;
                drop(s);
                return Err(rollback_prepared_hub_device_room_assignments(
                    state,
                    prepared_assignments,
                    anyhow::anyhow!("Failed to assign device to target room"),
                ));
            }
        }
        if let Some(old_id) = &old_room_id {
            if let Some(room) = s.topology.get_mut(old_id) {
                room.user_customized = true;
            }
        }
        if let Some(room) = s.topology.get_mut(target_room_id) {
            room.user_customized = true;
        }

        ensure_synthetic_device_registry_rooms(
            &mut s,
            &device_type,
            &device_name,
            &active_endpoints,
        );
    } else {
        // Unassignment is an explicit user action, so mark the topology node
        // as UserOverride with no parent. This keeps a follow-up hub sync
        // from silently re-attaching the device under whatever room the hub
        // still reports it in (issue #43).
        s.topology.ensure_standalone_device(device_id);
        s.topology.assign_device(
            device_id,
            None,
            crate::topology::DevicePlacement::UserOverride,
        );
        if let Some(old_id) = &old_room_id {
            if let Some(room) = s.topology.get_mut(old_id) {
                room.user_customized = true;
            }
        }
        ensure_synthetic_device_registry_rooms(
            &mut s,
            &device_type,
            &device_name,
            &active_endpoints,
        );
    }

    // Propagate the assignment to each endpoint's hub-side device_rooms map so
    // typed-device routing (button/motion) follows the Rhythm room assignment.
    // Lights are handled via `ensure_synthetic_device_registry_rooms` above —
    // their device_rooms entries are managed by synthetic-room scaffolding.
    if !matches!(
        device_type,
        rhythm_core::runtime::hub_registry::DeviceType::Light
    ) {
        sync_endpoint_device_rooms(&mut s, &active_endpoints, room_id);
    }

    let new_motion_target = old_motion_target.as_ref().map(|_| {
        s.topology
            .effective_control_target(device_id, &NodeControlKind::Motion)
    });

    if let Err(error) = save_authority_state(&s) {
        s.topology = topology_before_assignment;
        s.canonical_registry = canonical_before_assignment;
        let recovery_error = save_authority_state(&s).err();
        drop(s);
        let error = match recovery_error {
            None => error.context("Failed to durably commit device room assignment"),
            Some(recovery_error) => anyhow::anyhow!(
                "Failed to durably commit device room assignment: {:#}; restoring the prior persisted topology also failed: {:#}",
                error,
                recovery_error
            ),
        };
        return Err(rollback_prepared_hub_device_room_assignments(
            state,
            prepared_assignments,
            error,
        ));
    }
    drop(s);

    if let (Some(old), Some(new)) = (old_motion_target, new_motion_target) {
        if old != new {
            if let Some(old_target) = old {
                queue_motion_timer_clear(state, &old_target);
            }
            if let Some(new_target) = new {
                queue_motion_timer_clear(state, &new_target);
            }
        }
    }

    persist_registry(state);
    if let Some(node_id) = sleep_default_node_to_seed.as_deref() {
        ensure_sleep_mode_hard_off_default(state, node_id);
    }
    if matches!(device_type, DeviceType::Light) {
        let mut name_scope = LightNameReconciliationScope::for_device(device_id.to_string());
        if source_room_id.as_deref() != room_id {
            name_scope.include_room(source_room_id.clone());
            name_scope.include_room(room_id.map(str::to_string));
        }
        reconcile_automatic_light_names_best_effort(state, &name_scope);
    }
    reconcile_runtime_from_state(state)?;
    if assigning_standalone_light_child {
        clear_runtime_node_off_flags(state, device_id)?;
        persist_rooms(state);
    }
    if matches!(device_type, DeviceType::Light)
        && room_id.is_some()
        && source_room_id.as_deref() != room_id
    {
        let target_room_id = room_id.expect("checked above");
        if let Err(error) = apply_parent_room_output_to_light(state, device_id, target_room_id) {
            // The topology assignment and its persisted canonical registry update are already
            // committed at this point. Treat the immediate output refresh as best effort so a
            // transient runtime failure cannot report a durable move as failed (and make a retry
            // skip the refresh because the light is already in the destination room).
            warn!(
                "Failed to apply destination room '{}' output to moved light '{}': {:#}",
                target_room_id, device_id, error
            );
        }
    }

    {
        emit_triage_changed(state);
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    }
    Ok(())
}

/// Set the preferred endpoint for a canonical device.
pub fn do_canonical_set_preferred(
    state: &SharedState,
    device_id: &str,
    hub_type: &str,
    hub_address: &str,
    native_id: &str,
) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    use crate::canonical::identity::HubKey;
    use crate::hub::HubType;

    let hub_key = HubKey::new(HubType::new(hub_type), hub_address);
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    if s.canonical_registry
        .set_preferred_endpoint(device_id, &hub_key, native_id)
    {
        persist_canonical(&s);
        Ok(())
    } else {
        Err(anyhow::anyhow!("Device or endpoint not found"))
    }
}

// ============================================================================
// Triage commands
// ============================================================================

/// Build JSON for the triage queue (pending entries).
pub fn build_triage_queue(state: &SharedState) -> Result<String> {
    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let pending = s.canonical_registry.triage().pending();
    serde_json::to_string(&pending).map_err(|e| anyhow::anyhow!(e))
}

fn commit_triage_authority_mutation(
    state: &SharedState,
    topology_before: crate::topology::RoomTopologyStore,
    canonical_before: crate::canonical::registry::CanonicalRegistry,
    operation: &str,
) -> Result<()> {
    if let Err(error) = sync_required_topology_groups(state) {
        {
            let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            state.topology = topology_before;
            state.canonical_registry = canonical_before;
        }
        return Err(required_topology_group_sync_error(state, operation, error));
    }

    if let Err(error) = {
        let state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        save_authority_state(&state)
    } {
        let recovery_error = {
            let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            state.topology = topology_before;
            state.canonical_registry = canonical_before;
            save_authority_state(&state).err()
        };
        let error = match recovery_error {
            None => error.context(format!("Failed to durably commit triage {operation}")),
            Some(recovery_error) => anyhow::anyhow!(
                "Failed to durably commit triage {operation}: {:#}; restoring prior persistence failed: {:#}",
                error,
                recovery_error
            ),
        };
        let rollback_operation = format!("{operation} persistence");
        return Err(required_topology_group_sync_error(
            state,
            &rollback_operation,
            error,
        ));
    }

    Ok(())
}

/// Confirm a triage device merge.
///
/// Merges the discovered device's endpoint into the chosen canonical device
/// and removes the silo device that was created during Phase 4 of resolve().
pub fn do_triage_merge(state: &SharedState, entry_id: &str, canonical_id: &str) -> Result<()> {
    use crate::canonical::triage::TriageKind;

    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let entry = match s.canonical_registry.triage().get(entry_id) {
        Some(entry) => entry.clone(),
        None => return Err(anyhow::anyhow!("Triage entry not found: {}", entry_id)),
    };
    if entry.kind != TriageKind::DeviceMerge {
        return Err(anyhow::anyhow!(
            "Triage entry '{}' is not a device merge",
            entry_id
        ));
    }
    let hub_key = entry.hub_key.clone();
    let native_id = entry.discovered.native_id.clone();
    let hub_room_id = entry.discovered.room_id.clone();
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    // Find the silo device BEFORE complete_merge updates native_index.
    // The silo device has the same native_id on the same hub but a different canonical ID.
    let silo_id = s
        .canonical_registry
        .find_by_native_id(&hub_key, &native_id)
        .filter(|d| d.id != canonical_id)
        .map(|d| d.id.clone());
    let topology_before = s.topology.clone();
    let canonical_before = s.canonical_registry.clone();

    if s.canonical_registry
        .complete_merge(entry_id, canonical_id, &hub_key, now)
    {
        // Remove the silo device that was created during resolve() Phase 4.
        if let Some(silo_id) = silo_id {
            s.canonical_registry.remove_device(&silo_id);
            log::debug!(target: "triage", "Removed silo device '{}' after merge", silo_id);
        }

        // Update topology: add device to the correct room
        if !hub_room_id.is_empty() {
            if let Some(rhythm_room_id) = s
                .topology
                .translate_room_id(&hub_key, &hub_room_id)
                .map(|s| s.to_string())
            {
                s.topology.ensure_standalone_device(canonical_id);
                let _ = s.topology.assign_device(
                    canonical_id,
                    Some(&rhythm_room_id),
                    crate::topology::DevicePlacement::HubDefault,
                );
                s.canonical_registry
                    .assign_room(canonical_id, Some(&rhythm_room_id));
            }
        } else {
            s.topology.ensure_standalone_device(canonical_id);
        }
        drop(s);
        commit_triage_authority_mutation(state, topology_before, canonical_before, "device merge")?;
        let name_scope = LightNameReconciliationScope::for_device(canonical_id.to_string());
        reconcile_automatic_light_names_best_effort(state, &name_scope);
        reconcile_runtime_from_state(state)?;
        {
            emit_triage_changed(state);
            crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
        }
        Ok(())
    } else {
        Err(anyhow::anyhow!("Failed to merge"))
    }
}

/// Resolve a triage entry by keeping the discovered device separate.
///
/// For an unassigned device, this is the explicit opt-in that enables it as a
/// standalone runtime node.
pub fn do_triage_new_device(state: &SharedState, entry_id: &str) -> Result<String> {
    use crate::canonical::triage::TriageKind;

    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let entry = match s.canonical_registry.triage().get(entry_id) {
        Some(entry) => entry.clone(),
        None => return Err(anyhow::anyhow!("Triage entry not found: {}", entry_id)),
    };
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    match entry.kind {
        TriageKind::DeviceMerge => {
            let hub_key = entry.hub_key.clone();
            let hub_room_id = entry.discovered.room_id.clone();
            let topology_before = s.topology.clone();
            let canonical_before = s.canonical_registry.clone();
            match s
                .canonical_registry
                .complete_new_device(entry_id, &hub_key, now)
            {
                Some(canonical_id) => {
                    if !hub_room_id.is_empty() {
                        if let Some(rhythm_room_id) = s
                            .topology
                            .translate_room_id(&hub_key, &hub_room_id)
                            .map(|s| s.to_string())
                        {
                            s.topology.ensure_standalone_device(&canonical_id);
                            let _ = s.topology.assign_device(
                                &canonical_id,
                                Some(&rhythm_room_id),
                                crate::topology::DevicePlacement::HubDefault,
                            );
                            s.canonical_registry
                                .assign_room(&canonical_id, Some(&rhythm_room_id));
                        }
                    } else {
                        s.topology.ensure_standalone_device(&canonical_id);
                    }
                    drop(s);
                    commit_triage_authority_mutation(
                        state,
                        topology_before,
                        canonical_before,
                        "new device",
                    )?;
                    let name_scope = LightNameReconciliationScope::for_device(canonical_id.clone());
                    reconcile_automatic_light_names_best_effort(state, &name_scope);
                    reconcile_runtime_from_state(state)?;
                    {
                        emit_triage_changed(state);
                        crate::state::emit_server_event(
                            state,
                            crate::server_event::ServerEvent::NodesChanged,
                        );
                    }
                    Ok(format!(r#"{{"canonical_id":"{}"}}"#, canonical_id))
                }
                None => Err(anyhow::anyhow!("Failed to create new device")),
            }
        }
        TriageKind::RoomBinding => {
            if s.canonical_registry
                .triage_mut()
                .resolve_keep_separate(entry_id, now)
            {
                persist_canonical(&s);
                drop(s);
                emit_triage_changed(state);
                Ok(r#"{"status":"kept_separate"}"#.to_string())
            } else {
                Err(anyhow::anyhow!("Failed to keep room binding separate"))
            }
        }
        TriageKind::UnassignedDevice => {
            let canonical_id = entry.canonical_id.clone().ok_or_else(|| {
                anyhow::anyhow!("Triage entry '{}' is missing canonical_id", entry_id)
            })?;
            if s.canonical_registry.triage_mut().resolve(
                entry_id,
                crate::canonical::triage::TriageStatus::KeptSeparate,
                "api",
                now,
            ) {
                persist_canonical(&s);
                drop(s);
                let name_scope = LightNameReconciliationScope::for_device(canonical_id.clone());
                reconcile_automatic_light_names_best_effort(state, &name_scope);
                reconcile_runtime_from_state(state)?;
                emit_triage_changed(state);
                crate::state::emit_server_event(
                    state,
                    crate::server_event::ServerEvent::NodesChanged,
                );
                Ok(format!(
                    r#"{{"status":"standalone","canonical_id":"{}"}}"#,
                    canonical_id
                ))
            } else {
                Err(anyhow::anyhow!("Failed to keep device standalone"))
            }
        }
        _ => Err(anyhow::anyhow!(
            "Triage entry '{}' does not support /new",
            entry_id
        )),
    }
}

/// Assign an unassigned-device triage entry to a room.
pub fn do_triage_assign_room(state: &SharedState, entry_id: &str, room_id: &str) -> Result<()> {
    use crate::canonical::triage::TriageKind;

    let resolved_room_id = resolve_node_id(state, room_id);
    let canonical_id = {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let entry = s
            .canonical_registry
            .triage()
            .get(entry_id)
            .ok_or_else(|| anyhow::anyhow!("Triage entry not found: {}", entry_id))?;
        if entry.kind != TriageKind::UnassignedDevice {
            return Err(anyhow::anyhow!(
                "Triage entry '{}' is not an unassigned device",
                entry_id
            ));
        }
        entry
            .canonical_id
            .clone()
            .ok_or_else(|| anyhow::anyhow!("Triage entry '{}' is missing canonical_id", entry_id))?
    };

    do_canonical_assign_room(state, &canonical_id, Some(&resolved_room_id))
}

/// Dismiss a triage entry.
pub fn do_triage_dismiss(state: &SharedState, entry_id: &str) -> Result<()> {
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let kind = s
        .canonical_registry
        .triage()
        .get(entry_id)
        .map(|entry| entry.kind.clone())
        .ok_or_else(|| anyhow::anyhow!("Triage entry not found: {}", entry_id))?;
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    if s.canonical_registry.triage_mut().dismiss(entry_id, now) {
        persist_canonical(&s);
        drop(s);
        if kind == crate::canonical::triage::TriageKind::UnassignedDevice {
            reconcile_runtime_from_state(state)?;
            crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
        }
        emit_triage_changed(state);
        Ok(())
    } else {
        Err(anyhow::anyhow!("Triage entry not found: {}", entry_id))
    }
}

/// Approve a room binding triage entry — merge two rooms.
///
/// Merges the silo room (created for the new hub) into the target Rhythm room,
/// records an approved binding so it re-applies on re-sync, rebuilds composite
/// routing, and emits SSE events.
pub fn do_triage_bind_room(state: &SharedState, entry_id: &str) -> Result<()> {
    do_triage_bind_room_to(state, entry_id, None)
}

/// Approve a room binding triage entry — optionally binding to a specific target
/// (for the 3+ hub case where the user picks from candidate rooms).
pub fn do_triage_bind_room_to(
    state: &SharedState,
    entry_id: &str,
    target_override: Option<&str>,
) -> Result<()> {
    use crate::canonical::triage::TriageKind;

    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let resolved_target_override = target_override.map(|id| resolve_node_id(state, id));
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    // Get the room binding proposal
    let entry = s
        .canonical_registry
        .triage()
        .get(entry_id)
        .ok_or_else(|| anyhow::anyhow!("Triage entry not found: {}", entry_id))?
        .clone();
    if entry.kind != TriageKind::RoomBinding {
        return Err(anyhow::anyhow!(
            "Triage entry '{}' is not a room binding",
            entry_id
        ));
    }

    let binding = entry
        .room_binding
        .ok_or_else(|| anyhow::anyhow!("Not a room binding entry: {}", entry_id))?;

    let target_id = resolved_target_override.unwrap_or(binding.target_rhythm_room_id.clone());

    // Validate target room exists
    if s.topology.get(&target_id).is_none() {
        return Err(anyhow::anyhow!("Target room '{}' not found", target_id));
    }

    // Find the silo room (the one created for this hub's room)
    let source_id = s
        .topology
        .translate_room_id(&entry.hub_key, &binding.hub_room_id)
        .map(|s| s.to_string())
        .ok_or_else(|| {
            anyhow::anyhow!("Silo room not found for hub room: {}", binding.hub_room_id)
        })?;
    let source_device_ids: Vec<String> = s
        .topology
        .get(&source_id)
        .map(|room| {
            room.devices
                .iter()
                .map(|device| device.device_id.clone())
                .collect()
        })
        .unwrap_or_default();
    let topology_before = s.topology.clone();
    let canonical_before = s.canonical_registry.clone();

    // Merge the silo room into the target room
    if !s.topology.merge_rooms(&target_id, &source_id) {
        return Err(anyhow::anyhow!(
            "Failed to merge rooms: {} → {}",
            source_id,
            target_id
        ));
    }
    for device_id in &source_device_ids {
        s.canonical_registry
            .assign_room(device_id, Some(&target_id));
    }

    // Record the approved binding so it re-applies on re-sync
    s.topology.approve_binding(
        entry.hub_key.clone(),
        binding.hub_room_id.clone(),
        target_id.clone(),
        now,
    );

    // Resolve the triage entry
    s.canonical_registry.triage_mut().resolve(
        entry_id,
        crate::canonical::triage::TriageStatus::Confirmed,
        "api",
        now,
    );

    drop(s);
    commit_triage_authority_mutation(state, topology_before, canonical_before, "room binding")?;
    let name_scope = LightNameReconciliationScope::for_room(Some(target_id));
    reconcile_automatic_light_names_best_effort(state, &name_scope);
    reconcile_runtime_from_state(state)?;

    // Emit SSE events
    {
        emit_triage_changed(state);
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    }

    Ok(())
}

/// Build JSON with triage count summary.
pub fn build_triage_count(state: &SharedState) -> Result<String> {
    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let triage = s.canonical_registry.triage();
    let json = format!(
        r#"{{"devices":{},"rooms":{},"unassigned":{},"hub_configured":{},"total":{}}}"#,
        triage.pending_device_count(),
        triage.pending_room_count(),
        triage.pending_unassigned_count(),
        triage.pending_hub_configured_count(),
        triage.pending_count(),
    );
    Ok(json)
}

/// Emit a TriageChanged SSE event with current counts.
pub fn emit_triage_changed(state: &SharedState) {
    // Read counts under lock, then drop before emitting (emit_server_event locks too)
    let counts = state.lock().ok().map(|s| {
        let triage = s.canonical_registry.triage();
        (
            triage.pending_count(),
            triage.pending_device_count(),
            triage.pending_room_count(),
            triage.pending_unassigned_count(),
            triage.pending_hub_configured_count(),
        )
    });
    if let Some((total, devices, rooms, unassigned, hub_configured)) = counts {
        crate::state::emit_server_event(
            state,
            crate::server_event::ServerEvent::TriageChanged {
                pending_count: total,
                pending_devices: devices,
                pending_rooms: rooms,
                pending_unassigned: unassigned,
                pending_hub_configured: hub_configured,
            },
        );
    }
}

// ============================================================================
// Topology commands
// ============================================================================

fn sync_required_topology_groups(state: &SharedState) -> Result<()> {
    let callback = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .sync_required_topology_groups_fn
        .clone();
    match callback {
        Some(callback) => callback(state),
        None => Ok(()),
    }
}

fn required_topology_group_sync_error(
    state: &SharedState,
    operation: &str,
    error: anyhow::Error,
) -> anyhow::Error {
    match sync_required_topology_groups(state) {
        Ok(()) => error.context(format!(
            "Required native room {} acknowledgement failed",
            operation
        )),
        Err(rollback_error) => {
            fence_all_active_required_group_authority_uncertainty(state);
            anyhow::anyhow!(
                "Required native room {} acknowledgement failed: {:#}; compensating native sync failed: {:#}",
                operation,
                error,
                rollback_error
            )
        }
    }
}

/// Build JSON for all topology rooms.
pub fn build_topology_rooms(state: &SharedState) -> Result<String> {
    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let rooms: Vec<_> = s.topology.rooms().collect();
    serde_json::to_string(&rooms).map_err(|e| anyhow::anyhow!(e))
}

/// Build JSON for the full public topology graph.
pub fn build_topology_nodes(state: &SharedState) -> Result<String> {
    let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let mut nodes = Vec::new();

    let mut room_ids: Vec<_> = s.topology.rooms().map(|room| room.id.clone()).collect();
    room_ids.sort();
    for room_id in room_ids {
        let room = s.topology.get(&room_id).unwrap();
        nodes.push(TopologyNodeDto {
            id: room.id.clone(),
            name: room.name.clone(),
            kind: LightNodeKind::Room,
            parent_id: None,
            placement: None,
            controls: s
                .topology
                .effective_node_controls(&room.id, &s.canonical_registry)
                .into_iter()
                .map(|(kind, target_id, inherited)| TopologyNodeControlDto {
                    kind,
                    target_id,
                    inherited,
                })
                .collect(),
            hub_room_bindings: room.hub_room_bindings.clone(),
            manufacturer: None,
            model: None,
            user_customized: Some(room.user_customized),
            bootstrap_name: room.bootstrap_name.clone(),
        });
    }

    let mut device_ids: Vec<_> = s
        .topology
        .device_nodes()
        .map(|node| node.id.clone())
        .collect();
    device_ids.sort();
    for device_id in device_ids {
        let node = s.topology.get_device_node(&device_id).unwrap();
        let canonical = s.canonical_registry.get(&node.canonical_device_id);
        nodes.push(TopologyNodeDto {
            id: node.id.clone(),
            name: canonical
                .map(|device| device.name.clone())
                .unwrap_or_else(|| node.id.clone()),
            kind: canonical
                .map(|device| runtime_node_kind_for_device_type(device.device_type.clone()))
                .unwrap_or(LightNodeKind::OtherDevice),
            parent_id: node.parent_id.clone(),
            placement: Some(node.placement.clone()),
            controls: s
                .topology
                .effective_node_controls(&node.id, &s.canonical_registry)
                .into_iter()
                .map(|(kind, target_id, inherited)| TopologyNodeControlDto {
                    kind,
                    target_id,
                    inherited,
                })
                .collect(),
            hub_room_bindings: Vec::new(),
            manufacturer: canonical.and_then(|device| device.manufacturer.clone()),
            model: canonical.and_then(|device| device.model.clone()),
            user_customized: None,
            bootstrap_name: None,
        });
    }

    serde_json::to_string(&nodes).map_err(|e| anyhow::anyhow!(e))
}

/// Set or clear an explicit topology control target for a source node.
pub fn do_topology_set_control_target(
    state: &SharedState,
    source_id: &str,
    kind: NodeControlKind,
    target_id: Option<&str>,
) -> Result<()> {
    let target_ids: Vec<&str> = target_id.into_iter().collect();
    do_topology_set_control_targets(state, source_id, kind, &target_ids)
}

/// Set or clear explicit topology control targets for a source node.
pub fn do_topology_set_control_targets(
    state: &SharedState,
    source_id: &str,
    kind: NodeControlKind,
    target_ids: &[&str],
) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let resolved_source_id = resolve_node_id(state, source_id);
    let mut resolved_target_ids: Vec<String> = target_ids
        .iter()
        .map(|id| resolve_node_id(state, id))
        .collect();
    resolved_target_ids.sort();
    resolved_target_ids.dedup();

    let (old_targets, new_targets) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if !s.topology.has_public_node(&resolved_source_id) {
            return Err(anyhow::anyhow!(
                "Source node '{}' not found",
                resolved_source_id
            ));
        }
        for target_id in &resolved_target_ids {
            if !s.topology.has_public_node(target_id) {
                return Err(anyhow::anyhow!("Target node '{}' not found", target_id));
            }
        }

        let old_targets: HashSet<String> = s
            .topology
            .effective_control_targets(&resolved_source_id, &kind)
            .into_iter()
            .collect();
        let resolved_target_refs: Vec<&str> =
            resolved_target_ids.iter().map(String::as_str).collect();
        s.topology
            .set_control_targets(&resolved_source_id, kind.clone(), &resolved_target_refs);
        let new_targets: HashSet<String> = s
            .topology
            .effective_control_targets(&resolved_source_id, &kind)
            .into_iter()
            .collect();
        persist_topology(&s);
        (old_targets, new_targets)
    };

    if kind == NodeControlKind::Motion {
        for target in old_targets.union(&new_targets) {
            queue_motion_timer_clear(state, target);
        }
    }

    crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);

    Ok(())
}

/// Create a new empty Rhythm room.
pub fn do_topology_create_room(state: &SharedState, name: &str) -> Result<String> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    let id = s.topology.create_room(name);
    persist_topology(&s);
    drop(s);
    ensure_sleep_mode_hard_off_default(state, &id);
    reconcile_runtime_from_state(state)?;
    Ok(format!(r#"{{"id":"{}","name":"{}"}}"#, id, name))
}

/// Rename a Rhythm room and reconcile integration-managed native groups.
pub fn do_topology_rename_room(state: &SharedState, room_id: &str, name: &str) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let topology_before = {
        let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let topology_before = state.topology.clone();
        if !state.topology.rename_room(room_id, name) {
            return Err(anyhow::anyhow!("Room not found: {}", room_id));
        }
        topology_before
    };

    if let Err(error) = sync_required_topology_groups(state) {
        {
            let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            state.topology = topology_before;
        }
        return Err(required_topology_group_sync_error(state, "rename", error));
    }

    if let Err(error) = {
        let state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        save_topology(&state)
    } {
        let recovery_error = {
            let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            state.topology = topology_before;
            save_topology(&state).err()
        };
        let error = match recovery_error {
            None => error.context("Failed to durably commit Rhythm room rename"),
            Some(recovery_error) => anyhow::anyhow!(
                "Failed to durably commit Rhythm room rename: {:#}; restoring prior persistence failed: {:#}",
                error,
                recovery_error
            ),
        };
        return Err(required_topology_group_sync_error(
            state,
            "rename persistence",
            error,
        ));
    }
    let name_scope = LightNameReconciliationScope::for_room(Some(room_id.to_string()));
    reconcile_automatic_light_names_best_effort(state, &name_scope);
    reconcile_runtime_from_state(state)?;
    crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    Ok(())
}

/// Delete a topology room and unassign any attached devices.
pub fn do_topology_delete_room(state: &SharedState, room_id: &str) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let (topology_before, canonical_before, detached_devices, source_bindings, delete_source_room) = {
        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        let room = s
            .topology
            .get(room_id)
            .ok_or_else(|| anyhow::anyhow!("Room not found: {}", room_id))?;
        let source_bindings = room
            .hub_room_bindings
            .iter()
            .filter(|binding| {
                !s.topology
                    .room_binding_is_managed(room_id, &binding.hub_key, &binding.hub_room_id)
            })
            .cloned()
            .collect::<Vec<_>>();
        if source_bindings.len() > 1 {
            anyhow::bail!("Source-backed room deletion requires exactly one authoritative source");
        }
        let delete_source_room = s.delete_source_room_fn.clone();
        if !source_bindings.is_empty() && delete_source_room.is_none() {
            anyhow::bail!("Source-backed room deletion is unavailable");
        }
        let topology_before = s.topology.clone();
        let canonical_before = s.canonical_registry.clone();
        let detached_device_ids = s
            .topology
            .remove_room(room_id)
            .ok_or_else(|| anyhow::anyhow!("Room not found: {}", room_id))?;

        let mut detached_devices = Vec::new();
        for device_id in detached_device_ids {
            let Some(device) = s.canonical_registry.get(&device_id).cloned() else {
                continue;
            };
            let active_endpoints: Vec<_> = device.active_endpoints().cloned().collect();

            s.canonical_registry.assign_room(&device_id, None);
            detached_devices.push((device, active_endpoints));
        }
        (
            topology_before,
            canonical_before,
            detached_devices,
            source_bindings,
            delete_source_room,
        )
    };

    if let Err(error) = sync_required_topology_groups(state) {
        {
            let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            state.topology = topology_before;
            state.canonical_registry = canonical_before;
        }
        return Err(required_topology_group_sync_error(state, "delete", error));
    }

    if let Err(error) = {
        let state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        save_authority_state(&state)
    } {
        let recovery_error = {
            let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            state.topology = topology_before;
            state.canonical_registry = canonical_before;
            save_authority_state(&state).err()
        };
        let error = match recovery_error {
            None => error.context("Failed to durably commit Rhythm room delete"),
            Some(recovery_error) => anyhow::anyhow!(
                "Failed to durably commit Rhythm room delete: {:#}; restoring prior persistence failed: {:#}",
                error,
                recovery_error
            ),
        };
        return Err(required_topology_group_sync_error(
            state,
            "delete persistence",
            error,
        ));
    }

    if let Some(delete_source_room) = delete_source_room {
        for binding in &source_bindings {
            if let Err(error) = delete_source_room(state, binding) {
                let recovery_error = {
                    let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
                    state.topology = topology_before;
                    state.canonical_registry = canonical_before;
                    save_authority_state(&state).err()
                };
                let error = match recovery_error {
                    None => error.context("Source-backed room deletion failed"),
                    Some(recovery_error) => anyhow::anyhow!(
                        "Source-backed room deletion failed: {:#}; restoring prior persistence failed: {:#}",
                        error,
                        recovery_error
                    ),
                };
                return Err(required_topology_group_sync_error(
                    state,
                    "delete rollback",
                    error,
                ));
            }
        }
    }

    {
        let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        for (device, active_endpoints) in &detached_devices {
            ensure_synthetic_device_registry_rooms(
                &mut state,
                &device.device_type,
                &device.name,
                active_endpoints,
            );
        }
        state.room_observed_power.remove(room_id);
        state.motion_snapshots.remove(room_id);
        state.room_mode_transitions.remove(room_id);
        state
            .pending_motion_clear
            .retain(|pending| pending != room_id);
    }

    if !detached_devices.is_empty() {
        persist_registry(state);
    }

    queue_motion_timer_clear(state, room_id);
    let name_scope = LightNameReconciliationScope::for_room(None);
    reconcile_automatic_light_names_best_effort(state, &name_scope);
    reconcile_runtime_from_state(state)?;

    {
        emit_triage_changed(state);
        crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
    }

    Ok(())
}

/// Merge two rooms.
pub fn do_topology_merge_rooms(
    state: &SharedState,
    target_id: &str,
    source_id: &str,
) -> Result<()> {
    let transaction_lock = state
        .lock()
        .map_err(|_| anyhow::anyhow!("lock"))?
        .external_topology_transaction_lock
        .clone();
    let _transaction = transaction_lock
        .lock()
        .map_err(|_| anyhow::anyhow!("External topology transaction lock poisoned"))?;
    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
    if s.topology.get(target_id).is_none() {
        return Err(anyhow::anyhow!("Target room not found"));
    }
    let source_device_ids: Vec<String> = s
        .topology
        .get(source_id)
        .map(|room| {
            room.devices
                .iter()
                .map(|device| device.device_id.clone())
                .collect()
        })
        .unwrap_or_default();
    let topology_before = s.topology.clone();
    let canonical_before = s.canonical_registry.clone();
    if s.topology.merge_rooms(target_id, source_id) {
        for device_id in &source_device_ids {
            s.canonical_registry.assign_room(device_id, Some(target_id));
        }
        drop(s);

        if let Err(error) = sync_required_topology_groups(state) {
            {
                let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
                state.topology = topology_before;
                state.canonical_registry = canonical_before;
            }
            return Err(required_topology_group_sync_error(state, "merge", error));
        }

        if let Err(error) = {
            let state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
            save_authority_state(&state)
        } {
            let recovery_error = {
                let mut state = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
                state.topology = topology_before;
                state.canonical_registry = canonical_before;
                save_authority_state(&state).err()
            };
            let error = match recovery_error {
                None => error.context("Failed to durably commit Rhythm room merge"),
                Some(recovery_error) => anyhow::anyhow!(
                    "Failed to durably commit Rhythm room merge: {:#}; restoring prior persistence failed: {:#}",
                    error,
                    recovery_error
                ),
            };
            return Err(required_topology_group_sync_error(
                state,
                "merge persistence",
                error,
            ));
        }
        let name_scope = LightNameReconciliationScope::for_room(Some(target_id.to_string()));
        reconcile_automatic_light_names_best_effort(state, &name_scope);
        reconcile_runtime_from_state(state)?;

        {
            crate::state::emit_server_event(state, crate::server_event::ServerEvent::NodesChanged);
        }

        Ok(())
    } else {
        Err(anyhow::anyhow!("Failed to merge rooms"))
    }
}

/// Move a device between rooms.
pub fn do_topology_move_device(
    state: &SharedState,
    device_id: &str,
    from_room: &str,
    to_room: &str,
) -> Result<()> {
    {
        let s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
        if s.topology.device_parent_room_id(device_id) != Some(from_room) {
            return Err(anyhow::anyhow!(
                "Failed to move device: source room mismatch"
            ));
        }
    }
    do_canonical_assign_room(state, device_id, Some(to_room))
}

// ============================================================================
// Canonical + Topology persistence helpers
// ============================================================================

/// Durably commit the coupled canonical registry and topology authority state.
pub fn save_authority_state(s: &AppState) -> Result<()> {
    if s.authority_state_recovery_required {
        anyhow::bail!(
            "Authoritative topology state requires recovery before it can be overwritten"
        );
    }
    save_authority_state_unchecked(s)
}

fn save_authority_state_unchecked(s: &AppState) -> Result<()> {
    let Some(storage) = s.storage.as_ref() else {
        return Ok(());
    };
    let canonical_registry = serde_json::to_value(&s.canonical_registry)
        .context("Failed to serialize canonical registry")?;
    let topology =
        serde_json::to_value(&s.topology).context("Failed to serialize topology store")?;
    let state = crate::storage::StoredAuthorityState::new(canonical_registry, topology);
    storage
        .save_authority_state(&state)
        .context("Failed to save canonical registry + topology authority state")
}

/// Persist the canonical registry together with its coupled topology state.
pub(crate) fn save_canonical(s: &AppState) -> Result<()> {
    save_authority_state(s)
}

pub(crate) fn persist_canonical(s: &AppState) {
    if let Err(error) = save_canonical(s) {
        warn!(target: "cmd", "Failed to persist canonical registry: {}", error);
    }
}

/// Persist the topology store together with its coupled canonical registry.
pub(crate) fn save_topology(s: &AppState) -> Result<()> {
    save_authority_state(s)
}

pub(crate) fn persist_topology(s: &AppState) {
    if let Err(error) = save_topology(s) {
        warn!(target: "cmd", "Failed to persist topology: {}", error);
    }
}

