    struct RecordingDispatchController {
        turn_on_calls: Mutex<Vec<String>>,
    }

    impl RecordingDispatchController {
        fn new() -> Self {
            Self {
                turn_on_calls: Mutex::new(Vec::new()),
            }
        }

        fn turn_on_calls(&self) -> Vec<String> {
            self.turn_on_calls.lock().unwrap().clone()
        }

        fn clear_turn_on_calls(&self) {
            self.turn_on_calls.lock().unwrap().clear();
        }

        fn wait_for_turn_on_calls(&self, expected: usize) -> Vec<String> {
            let deadline = std::time::Instant::now() + Duration::from_secs(2);
            loop {
                let calls = self.turn_on_calls();
                if calls.len() >= expected || std::time::Instant::now() >= deadline {
                    return calls;
                }
                std::thread::sleep(Duration::from_millis(10));
            }
        }
    }

