    fn setup_state_with_registry(snapshots: Vec<RoomSnapshot>) -> (SharedState, Arc<MockRuntime>) {
        let (state, runtime) = setup_state(snapshots);
        let mut registry = crate::registry::HubDeviceRegistry::new();
        let device_ids: Vec<String> = Vec::new();
        for snap in runtime.engine_all_room_snapshots() {
            registry.upsert_room(&snap.id, &snap.name, "", &device_ids);
        }
        let registry: Arc<Mutex<dyn HubRegistry>> = Arc::new(Mutex::new(registry));

        let mut app = state.lock().unwrap();
        let hub_key = app.hubs.keys().next().cloned().unwrap();
        app.hubs.get_mut(&hub_key).unwrap().registry = Some(registry);
        drop(app);

        (state, runtime)
    }

    fn setup_state_with_empty_registry() -> (SharedState, Arc<MockRuntime>, HubKey) {
        let (state, runtime) = setup_state(Vec::new());
        let registry: Arc<Mutex<dyn HubRegistry>> =
            Arc::new(Mutex::new(crate::registry::HubDeviceRegistry::new()));

        let hub_key = {
            let mut app = state.lock().unwrap();
            let hub_key = app.hubs.keys().next().cloned().unwrap();
            app.hubs.get_mut(&hub_key).unwrap().registry = Some(registry);
            hub_key
        };

        (state, runtime, hub_key)
    }

    fn add_button_device_node(state: &SharedState, native_id: &str) -> String {
        let hub_key = state.lock().unwrap().hubs.keys().next().cloned().unwrap();
        let identity = crate::canonical::identity::DiscoveredIdentity {
            native_id: native_id.to_string(),
            room_id: None,
            room_name: None,
            name: native_id.to_string(),
            device_type: DeviceType::Button,
            hardware_ids: vec![crate::canonical::identity::HardwareId::serial(native_id)],
            manufacturer: None,
            model: None,
        };

        let mut s = state.lock().unwrap();
        let canonical_id = match s.canonical_registry.resolve(&identity, &hub_key, 1000) {
            crate::canonical::registry::ResolveResult::Created { canonical_id }
            | crate::canonical::registry::ResolveResult::AlreadyKnown { canonical_id } => {
                canonical_id
            }
            other => panic!("unexpected resolve result: {:?}", other),
        };
        s.topology.ensure_standalone_device(&canonical_id);
        canonical_id
    }

    #[test]
    fn pure_room_state_helpers_normalize_legacy_flags_and_validate_targets() {
        let settings = RoomProfileSettings::default();

        assert_eq!(
            room_mode_state_for_settings(false, &settings, true, true, true, true),
            RoomModeState::HardOff
        );
        assert_eq!(
            room_mode_state_for_settings(false, &settings, false, false, false, true),
            RoomModeState::Warning
        );
        assert_eq!(
            room_mode_state_for_settings(false, &settings, false, true, true, false),
            RoomModeState::Mood
        );
        assert_eq!(
            persistent_room_state_for_settings(false, &settings, false, false, true),
            RoomModeState::Standby
        );
        assert_eq!(
            room_state_for_mood_setting(false, &settings, RoomModeState::Wake),
            RoomModeState::Wake
        );
        assert!(room_mood_enabled(false, &settings));
        assert!(room_mood_active(false, &settings, false, true, true));
        assert!(!room_mood_active(false, &settings, true, true, false));

        assert_eq!(
            normalize_legacy_state_flags(true, false, false),
            (true, false, false)
        );
        assert_eq!(
            normalize_legacy_state_flags(true, true, false),
            (false, true, false)
        );
        assert_eq!(
            normalize_legacy_state_flags(true, true, true),
            (false, false, true)
        );

        assert_eq!(
            room_flags_for_target_state(RoomModeState::Active).unwrap(),
            (false, false, false)
        );
        assert_eq!(
            room_flags_for_target_state(RoomModeState::Mood).unwrap(),
            (false, true, false)
        );
        assert_eq!(
            room_flags_for_target_state(RoomModeState::Standby).unwrap(),
            (true, false, false)
        );
        assert_eq!(
            room_flags_for_target_state(RoomModeState::HardOff).unwrap(),
            (false, false, true)
        );
        assert!(room_flags_for_target_state(RoomModeState::Wake)
            .unwrap_err()
            .to_string()
            .contains("cannot be set directly"));
        assert!(room_flags_for_target_state(RoomModeState::Warning)
            .unwrap_err()
            .to_string()
            .contains("cannot be set directly"));
    }

    #[test]
    fn room_display_and_restore_helpers_cover_user_visible_light_states() {
        let mut app = AppState {
            latitude: Some(35.0),
            longitude: Some(-120.0),
            utc_offset_hours: -8.0,
            ..Default::default()
        };
        app.light_profile_configs.insert(
            rhythm_core::RHYTHM_PROFILE_ID.to_string(),
            rhythm_core::default_rhythm_profile(),
        );
        app.light_profile_configs.insert(
            rhythm_core::DAY_IDLE_PROFILE_ID.to_string(),
            rhythm_core::default_day_idle_profile(),
        );
        app.set_mode_configs(rhythm_core::default_mode_configs());

        let settings = RoomProfileSettings::default();
        assert_eq!(
            compute_room_display_values_for_settings(
                &app,
                &settings,
                RoomModeState::HardOff,
                0.0,
                0.0,
            ),
            (0, 0)
        );

        let active = compute_room_display_values_for_settings(
            &app,
            &settings,
            RoomModeState::Active,
            0.0,
            10.0,
        );
        let warning = compute_room_display_values_for_settings(
            &app,
            &settings,
            RoomModeState::Warning,
            0.0,
            10.0,
        );
        let standby = compute_room_display_values_for_settings(
            &app,
            &settings,
            RoomModeState::Standby,
            0.0,
            40.0,
        );
        assert!(active.0 > 0, "active rooms should show visible brightness");
        assert!(
            warning.0 <= active.0,
            "warning state should not render brighter than active output"
        );
        assert_eq!(
            standby.0, 1,
            "standby display ignores user brightness offset and renders idle profile"
        );

        let mut room = Room::new("room-restore", "Room Restore");
        room.rhythm_enabled = true;
        room.disabled = true;
        room.time_offset_minutes = -15.0;
        room.brightness_offset = 12.0;
        room.soft_off = true;
        room.mood_active = true;
        room.hard_off = false;
        room.standby_enabled = true;
        let normalized = normalize_legacy_soft_off_room(room.clone());
        assert!(!normalized.soft_off);
        assert!(normalized.mood_active);

        let restored_room = restored_room_state_from_room(&room);
        assert!(restored_room.rhythm_enabled);
        assert!(restored_room.disabled);
        assert_eq!(restored_room.time_offset_minutes, -15.0);
        assert_eq!(restored_room.brightness_offset, 12.0);
        assert!(!restored_room.soft_off);
        assert!(restored_room.mood_active);
        assert!(!restored_room.hard_off);

        let restored_node = restored_node_state_from_room(&room);
        assert!(restored_node.standby_enabled);
        assert_eq!(restored_node.profile_settings, room.profile_settings);
    }

    #[test]
    fn transition_and_motion_queue_helpers_dedupe_visible_runtime_work() {
        let state: SharedState = Arc::new(Mutex::new(AppState::default()));
        {
            let mut s = state.lock().unwrap();
            s.room_mode_transitions.insert(
                "room-active".to_string(),
                crate::state::RoomModeTransition {
                    ends_at: std::time::Instant::now() + Duration::from_secs(60),
                    periodic_resume_at: std::time::Instant::now() + Duration::from_secs(90),
                },
            );
            s.room_mode_transitions.insert(
                "room-expired".to_string(),
                crate::state::RoomModeTransition {
                    ends_at: std::time::Instant::now() - Duration::from_secs(1),
                    periodic_resume_at: std::time::Instant::now(),
                },
            );
        }

        let now = std::time::Instant::now();
        {
            let s = state.lock().unwrap();
            assert!(room_mode_transition_active(
                &s.room_mode_transitions,
                "room-active",
                now
            ));
            assert!(!room_mode_transition_active(
                &s.room_mode_transitions,
                "room-expired",
                now
            ));
            let active = active_transition_room_ids(&s.room_mode_transitions, now);
            assert!(active.contains("room-active"));
            assert!(!active.contains("room-expired"));
        }

        clear_room_mode_transition(&state, "room-active");
        queue_motion_timer_clear(&state, "room-active");
        queue_motion_timer_clear(&state, "room-active");
        queue_motion_timer_timeout_refresh(&state, "room-active");
        queue_motion_timer_timeout_refresh(&state, "room-active");

        let s = state.lock().unwrap();
        assert!(!s.room_mode_transitions.contains_key("room-active"));
        assert_eq!(s.pending_motion_clear, vec!["room-active".to_string()]);
        assert_eq!(
            s.pending_motion_timeout_refresh,
            vec!["room-active".to_string()]
        );
    }

    #[test]
    fn motion_timeout_refresh_recalculates_warning_and_emits_snapshot() {
        let (event_tx, mut event_rx) = tokio::sync::broadcast::channel(8);
        let state: SharedState = Arc::new(Mutex::new(AppState {
            event_tx: Some(event_tx),
            ..Default::default()
        }));
        {
            let mut s = state.lock().unwrap();
            s.motion_snapshots.insert(
                "room-motion".to_string(),
                MotionSnapshot {
                    motion_active: false,
                    motion_owned: true,
                    remaining_secs: Some(20),
                    timeout_secs: 120,
                    warning_active: true,
                },
            );
        }

        assert!(refresh_cached_motion_timeout_after_settings_change(
            &state,
            "room-motion",
            240
        ));
        let snap = state
            .lock()
            .unwrap()
            .motion_snapshots
            .get("room-motion")
            .cloned()
            .unwrap();
        assert_eq!(snap.timeout_secs, 240);
        assert_eq!(snap.remaining_secs, Some(140));
        assert!(!snap.warning_active);

        let event = event_rx.try_recv().expect("motion timer event should emit");
        match event {
            crate::server_event::ServerEvent::MotionTimer { timers } => {
                assert_eq!(timers.len(), 1);
                assert_eq!(timers[0].node_id, "room-motion");
                assert_eq!(timers[0].timeout_secs, 240);
            }
            other => panic!("unexpected event: {:?}", other),
        }

        assert!(!refresh_cached_motion_timeout_after_settings_change(
            &state,
            "room-motion",
            240
        ));
        assert!(!refresh_cached_motion_timeout_after_settings_change(
            &state, "missing", 30
        ));
    }

