    #[test]
    fn build_backup_bundle_dto_prunes_runtime_drift_and_uses_topology_parenting() {
        let (state, runtime) = setup_state(vec![
            make_snapshot("room1", false, false),
            make_snapshot("stale-room", false, false),
        ]);
        let device_id = insert_canonical_device(
            &state,
            HubKey::new(HubType::new("matter"), "local"),
            "matter-light-1",
            "Desk Lamp",
            "",
            "",
        );
        add_topology_room(&state, "room1", &[]);
        {
            let mut s = state.lock().unwrap();
            assert!(s.topology.attach_device_user_override("room1", &device_id));
        }
        runtime.snapshots.lock().unwrap().extend([
            make_light_child_snapshot(&device_id, "stale-room"),
            make_light_child_snapshot("stale-node", "stale-room"),
        ]);

        let bundle = build_backup_bundle_dto(&state, false).unwrap();

        assert_eq!(
            bundle
                .configuration
                .rooms
                .iter()
                .map(|room| room.id.as_str())
                .collect::<Vec<_>>(),
            vec!["room1"],
            "backup configuration should follow topology rooms, not stale runtime rooms"
        );

        let mut exported_ids: Vec<_> = bundle
            .installation
            .rooms
            .iter()
            .map(|room| room.id.clone())
            .collect();
        exported_ids.sort();
        assert_eq!(
            exported_ids,
            vec![device_id.clone(), "room1".to_string()],
            "backup runtime export should exclude stale runtime-only rooms and nodes"
        );
        assert_eq!(
            bundle
                .installation
                .rooms
                .get(&device_id)
                .expect("exported device node should exist")
                .parent_id
                .as_deref(),
            Some("room1"),
            "topology parenting should override stale runtime parenting during export"
        );
        assert!(
            bundle.installation.rooms.get("stale-room").is_none(),
            "stale runtime room should not leak into backup export"
        );
        assert!(
            bundle.installation.rooms.get("stale-node").is_none(),
            "stale runtime node should not leak into backup export"
        );
    }

    #[test]
    fn legacy_hue_backup_restore_grandfathers_bound_rooms_before_bootstrap_and_restart() {
        let storage = TestStorage::default();
        let key = HubKey::new(HubType::new(HubType::HUE), "bridge.local");
        let (topology, room_id) = legacy_hue_topology(&key, true);
        let room_id = room_id.unwrap();
        let bootstrap_observed_admission = Arc::new(AtomicBool::new(false));
        let state = Arc::new(Mutex::new(AppState {
            storage: Some(Arc::new(storage.clone())),
            hub_capabilities: vec![HubIntegrationCapability::new(HubType::HUE)],
            get_hub_provider_fn: Some(Arc::new(|_| &ACCEPTING_HUE_BACKUP_HUB_PROVIDER)),
            ..Default::default()
        }));
        {
            let room_id = room_id.clone();
            let key = key.clone();
            let observed = bootstrap_observed_admission.clone();
            state.lock().unwrap().request_hub_bootstrap_fn = Some(Arc::new(move |state| {
                let s = state.lock().unwrap();
                assert_eq!(
                    s.topology.external_room_automation_owner(&room_id, &key),
                    Some(crate::topology::ExternalRoomAutomationOwner::Rhythm)
                );
                assert!(s.rhythm_automation_allowed_for_node(&room_id));
                observed.store(true, Ordering::SeqCst);
            }));
        }

        do_backup_restore(&state, legacy_hue_backup(topology, &key)).unwrap();

        assert!(bootstrap_observed_admission.load(Ordering::SeqCst));
        {
            let s = state.lock().unwrap();
            assert_eq!(
                s.topology.external_room_automation_owner(&room_id, &key),
                Some(crate::topology::ExternalRoomAutomationOwner::Rhythm)
            );
            assert!(s.rhythm_automation_allowed_for_node(&room_id));
        }

        let mut restarted = AppState {
            storage: Some(Arc::new(storage)),
            ..Default::default()
        };
        crate::storage::load_persisted_state(&mut restarted);
        assert_eq!(
            restarted
                .topology
                .external_room_automation_owner(&room_id, &key),
            Some(crate::topology::ExternalRoomAutomationOwner::Rhythm)
        );
        assert!(restarted.rhythm_automation_allowed_for_node(&room_id));
    }

