    #[test]
    fn profile_bundle_reset_restores_factory_default_profile_bundle() {
        let (state, _rt) = setup_state(vec![]);
        let focus = make_focus_profile();
        do_profile_bundle_import(
            &state,
            ProfileBundleImportPayload::Profile(ProfileBundleData {
                power_save: true,
                profiles: vec![focus],
                scenes: vec![],
                mode_transitions: vec![],
            }),
        )
        .unwrap();

        let json = do_profile_bundle_reset(&state).unwrap();
        let reset_bundle: ProfileBundle = serde_json::from_str(&json).unwrap();
        let expected = factory_default_profile_bundle();
        let mut reset_profiles = reset_bundle.profile.profiles.clone();
        reset_profiles.sort_by(|left, right| left.id.cmp(&right.id));
        let mut expected_profiles = expected.profile.profiles.clone();
        expected_profiles.sort_by(|left, right| left.id.cmp(&right.id));
        let mut reset_scenes = reset_bundle.profile.scenes.clone();
        reset_scenes.sort_by(|left, right| left.id.cmp(&right.id));
        let mut expected_scenes = expected.profile.scenes.clone();
        expected_scenes.sort_by(|left, right| left.id.cmp(&right.id));

        assert_eq!(reset_bundle.profile.power_save, expected.profile.power_save);
        assert_eq!(reset_profiles, expected_profiles);
        assert_eq!(
            reset_bundle.profile.mode_transitions,
            expected.profile.mode_transitions
        );
        assert_eq!(reset_scenes, expected_scenes);
    }

    #[test]
    fn factory_reset_releases_external_controller_before_platform_barrier_once() {
        let (state, _rt) = setup_state(vec![]);
        let hub_key = state.lock().unwrap().hubs.keys().next().unwrap().clone();
        let order = Arc::new(Mutex::new(Vec::new()));
        {
            let mut state_guard = state.lock().unwrap();
            state_guard.hub_credentials.insert(
                hub_key.clone(),
                HubCredentials::new("mock", "mock", serde_json::json!({"token": "keep-me"})),
            );
            let release_order = order.clone();
            let expected_key = hub_key.clone();
            state_guard.release_external_controller_authority_fn =
                Some(Arc::new(move |state, key, reason| {
                    assert_eq!(key, &expected_key);
                    assert_eq!(
                        reason,
                        crate::hub::ExternalControllerReleaseReason::FactoryReset
                    );
                    let transaction_lock = {
                        let state = state.lock().unwrap();
                        state.external_topology_transaction_lock.clone()
                    };
                    assert!(matches!(
                        transaction_lock.try_lock(),
                        Err(std::sync::TryLockError::WouldBlock)
                    ));
                    release_order.lock().unwrap().push("release");
                    Ok(())
                }));
            let barrier_order = order.clone();
            state_guard.before_factory_reset_fn = Some(Arc::new(move |_| {
                barrier_order.lock().unwrap().push("barrier");
                Ok(())
            }));
        }

        do_factory_reset(&state).unwrap();

        assert_eq!(*order.lock().unwrap(), vec!["release", "barrier"]);
    }

