    #[test]
    fn topology_delete_room_rejects_multiple_sources_before_external_mutation() {
        let (state, _runtime, hub_key) = setup_state_with_deferred_runtime();
        let created: serde_json::Value =
            serde_json::from_str(&do_topology_create_room(&state, "Shared Room").unwrap()).unwrap();
        let room_id = created["id"].as_str().unwrap().to_string();
        let other_hub_key = HubKey::new(HubType::new("homeassistant"), "other");
        let external_calls = Arc::new(Mutex::new(0usize));
        {
            let mut s = state.lock().unwrap();
            for (binding_hub_key, native_id) in
                [(hub_key, "source-room-1"), (other_hub_key, "source-room-2")]
            {
                assert!(s.topology.upsert_room_binding(
                    &room_id,
                    crate::topology::HubRoomBinding {
                        hub_key: binding_hub_key,
                        hub_room_id: native_id.to_string(),
                        control_id: native_id.to_string(),
                        light_device_ids: Vec::new(),
                    },
                ));
            }
            let external_calls = external_calls.clone();
            s.delete_source_room_fn = Some(Arc::new(move |_, _| {
                *external_calls.lock().unwrap() += 1;
                Ok(())
            }));
        }

        let error = do_topology_delete_room(&state, &room_id).unwrap_err();

        assert!(format!("{error:#}").contains("exactly one authoritative source"));
        assert_eq!(*external_calls.lock().unwrap(), 0);
        assert!(state.lock().unwrap().topology.get(&room_id).is_some());
    }

    #[test]
    fn topology_lifecycle_mutations_schedule_group_integrations() {
        let (state, _runtime, hub_key) = setup_state_with_deferred_runtime();

        let created: serde_json::Value =
            serde_json::from_str(&do_topology_create_room(&state, "Office").unwrap()).unwrap();
        let room_id = created["id"].as_str().unwrap().to_string();
        let device_one =
            insert_canonical_device(&state, hub_key.clone(), "matter-100", "Desk Lamp", "", "");
        let device_two =
            insert_canonical_device(&state, hub_key, "matter-101", "Table Lamp", "", "");

        let sync_count = Arc::new(AtomicUsize::new(0));
        {
            let sync_count = sync_count.clone();
            state.lock().unwrap().sync_topology_groups_fn = Some(Arc::new(move |_| {
                sync_count.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }));
        }

        do_canonical_assign_room(&state, &device_one, Some(&room_id)).unwrap();
        wait_for_sync_count(&sync_count, 1);

        do_canonical_assign_room(&state, &device_two, Some(&room_id)).unwrap();
        wait_for_sync_count(&sync_count, 2);

        do_canonical_assign_room(&state, &device_one, None).unwrap();
        wait_for_sync_count(&sync_count, 3);

        do_topology_delete_room(&state, &room_id).unwrap();
        wait_for_sync_count(&sync_count, 4);

        do_device_hard_remove(&state, &device_two, None).unwrap();
        wait_for_sync_count(&sync_count, 5);
    }

    #[test]
    fn canonical_assign_room_does_not_wait_for_topology_group_sync() {
        let (state, _runtime, hub_key) = setup_state_with_deferred_runtime();

        let created: serde_json::Value =
            serde_json::from_str(&do_topology_create_room(&state, "Office").unwrap()).unwrap();
        let room_id = created["id"].as_str().unwrap().to_string();
        let device_id = insert_canonical_device(&state, hub_key, "matter-100", "Desk Lamp", "", "");

        let sync_started = Arc::new(AtomicUsize::new(0));
        let sync_finished = Arc::new(AtomicUsize::new(0));
        {
            let sync_started = sync_started.clone();
            let sync_finished = sync_finished.clone();
            state.lock().unwrap().sync_topology_groups_fn = Some(Arc::new(move |_| {
                sync_started.fetch_add(1, Ordering::SeqCst);
                std::thread::sleep(Duration::from_millis(750));
                sync_finished.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }));
        }

        let started_at = std::time::Instant::now();
        do_canonical_assign_room(&state, &device_id, Some(&room_id)).unwrap();
        let elapsed = started_at.elapsed();

        assert!(
            elapsed < Duration::from_millis(300),
            "room assignment waited for topology group sync: {elapsed:?}"
        );
        wait_for_sync_count(&sync_started, 1);
        wait_for_sync_count(&sync_finished, 1);
    }

    #[test]
    fn topology_group_sync_rebuilds_composite_routing_for_new_group_binding() {
        let (state, _runtime, hub_key) = setup_state_with_deferred_runtime();

        let created: serde_json::Value =
            serde_json::from_str(&do_topology_create_room(&state, "Office").unwrap()).unwrap();
        let room_id = created["id"].as_str().unwrap().to_string();
        let device_one =
            insert_canonical_device(&state, hub_key.clone(), "matter-100", "Desk Lamp", "", "");
        let device_two =
            insert_canonical_device(&state, hub_key.clone(), "matter-101", "Table Lamp", "", "");

        let recording = Arc::new(RecordingDispatchController::new());
        let composite = Arc::new(rhythm_core::CompositeController::new());
        composite.register_controller(&hub_key.to_string(), recording.clone());
        state.lock().unwrap().composite_controller = Some(composite.clone());

        let control_id = "matter-group-40657".to_string();
        let sync_count = Arc::new(AtomicUsize::new(0));
        {
            let sync_count = sync_count.clone();
            let hub_key_for_callback = hub_key.clone();
            let room_id_for_callback = room_id.clone();
            let control_id_for_callback = control_id.clone();
            state.lock().unwrap().sync_topology_groups_fn =
                Some(Arc::new(move |state: &SharedState| {
                    {
                        let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
                        let member_device_ids: Vec<String> = s
                            .topology
                            .get(&room_id_for_callback)
                            .map(|room| {
                                room.devices
                                    .iter()
                                    .filter_map(|room_device| {
                                        s.canonical_registry.get(&room_device.device_id)
                                    })
                                    .filter_map(|device| device.preferred_endpoint())
                                    .map(|endpoint| endpoint.native_id.clone())
                                    .collect()
                            })
                            .unwrap_or_default();
                        if member_device_ids.len() >= 2 {
                            s.topology.upsert_room_binding(
                                &room_id_for_callback,
                                crate::topology::HubRoomBinding {
                                    hub_key: hub_key_for_callback.clone(),
                                    hub_room_id: room_id_for_callback.clone(),
                                    control_id: control_id_for_callback.clone(),
                                    light_device_ids: member_device_ids,
                                },
                            );
                        }
                    }
                    sync_count.fetch_add(1, Ordering::SeqCst);
                    Ok(())
                }));
        }

        do_canonical_assign_room(&state, &device_one, Some(&room_id)).unwrap();
        wait_for_sync_count(&sync_count, 1);
        do_canonical_assign_room(&state, &device_two, Some(&room_id)).unwrap();
        wait_for_sync_count(&sync_count, 2);
        wait_for_topology_group_sync_idle(&state);
        recording.clear_turn_on_calls();

        futures::executor::block_on(
            composite.turn_on(&room_id, rhythm_core::LightingCommand::new(80, 4000)),
        )
        .expect("turn_on should succeed");

        let calls = recording.wait_for_turn_on_calls(1);
        assert_eq!(
            calls.len(),
            1,
            "expected exactly one turn_on_target dispatch, got {calls:?}"
        );
        let label = &calls[0];
        assert!(
            label.contains(control_id.as_str()),
            "composite routing did not refresh after topology group sync: \
             got target={label:?}, expected groupcast via {control_id}"
        );
        assert!(
            !label.contains("matter-100,matter-101"),
            "composite routing still dispatching per-device after sync: target={label:?}"
        );
    }

    #[test]
    fn topology_group_sync_failure_recovers_on_later_topology_change() {
        let (state, _runtime, hub_key) = setup_state_with_deferred_runtime();

        let created: serde_json::Value =
            serde_json::from_str(&do_topology_create_room(&state, "Office").unwrap()).unwrap();
        let room_id = created["id"].as_str().unwrap().to_string();
        let device_one =
            insert_canonical_device(&state, hub_key.clone(), "matter-100", "Desk Lamp", "", "");
        let device_two =
            insert_canonical_device(&state, hub_key.clone(), "matter-101", "Table Lamp", "", "");

        let recording = Arc::new(RecordingDispatchController::new());
        let composite = Arc::new(rhythm_core::CompositeController::new());
        composite.register_controller(&hub_key.to_string(), recording.clone());
        state.lock().unwrap().composite_controller = Some(composite.clone());

        let control_id = "matter-group-recovered".to_string();
        let sync_attempts = Arc::new(AtomicUsize::new(0));
        {
            let sync_attempts = sync_attempts.clone();
            let hub_key_for_callback = hub_key.clone();
            let room_id_for_callback = room_id.clone();
            let control_id_for_callback = control_id.clone();
            state.lock().unwrap().sync_topology_groups_fn =
                Some(Arc::new(move |state: &SharedState| {
                    let attempt = sync_attempts.fetch_add(1, Ordering::SeqCst) + 1;
                    if attempt == 1 {
                        return Err(anyhow::anyhow!("simulated topology group sync timeout"));
                    }

                    let mut s = state.lock().map_err(|_| anyhow::anyhow!("lock"))?;
                    let member_device_ids: Vec<String> = s
                        .topology
                        .get(&room_id_for_callback)
                        .map(|room| {
                            room.devices
                                .iter()
                                .filter_map(|room_device| {
                                    s.canonical_registry.get(&room_device.device_id)
                                })
                                .filter_map(|device| device.preferred_endpoint())
                                .map(|endpoint| endpoint.native_id.clone())
                                .collect()
                        })
                        .unwrap_or_default();
                    if member_device_ids.len() >= 2 {
                        s.topology.upsert_room_binding(
                            &room_id_for_callback,
                            crate::topology::HubRoomBinding {
                                hub_key: hub_key_for_callback.clone(),
                                hub_room_id: room_id_for_callback.clone(),
                                control_id: control_id_for_callback.clone(),
                                light_device_ids: member_device_ids,
                            },
                        );
                    }
                    Ok(())
                }));
        }

        do_canonical_assign_room(&state, &device_one, Some(&room_id)).unwrap();
        wait_for_sync_count(&sync_attempts, 1);
        do_canonical_assign_room(&state, &device_two, Some(&room_id)).unwrap();
        wait_for_sync_count(&sync_attempts, 2);
        wait_for_topology_group_sync_idle(&state);
        recording.clear_turn_on_calls();

        futures::executor::block_on(
            composite.turn_on(&room_id, rhythm_core::LightingCommand::new(80, 4000)),
        )
        .expect("turn_on should succeed after recovered group sync");

        let calls = recording.wait_for_turn_on_calls(1);
        assert_eq!(calls.len(), 1);
        assert!(
            calls[0].contains(control_id.as_str()),
            "recovered topology group sync should rebuild routing to groupcast target, got {:?}",
            calls[0]
        );
    }

    #[test]
    fn async_required_group_sync_failure_fences_control_and_requests_recovery() {
        let (state, _runtime, hub_key) = setup_state_with_deferred_runtime();
        let recovery_requests = Arc::new(AtomicUsize::new(0));
        {
            let recovery_requests = recovery_requests.clone();
            let mut app = state.lock().unwrap();
            app.topology
                .set_grouped_room_control_required(&hub_key, true);
            app.set_hub_connected(&hub_key, true);
            app.sync_topology_groups_fn = Some(Arc::new(|_| {
                anyhow::bail!("simulated asynchronous native topology uncertainty")
            }));
            app.request_hub_bootstrap_fn = Some(Arc::new(move |state| {
                assert!(
                    state.try_lock().is_ok(),
                    "recovery callback ran while AppState remained locked"
                );
                recovery_requests.fetch_add(1, Ordering::SeqCst);
            }));
        }

        run_topology_group_sync_for_integrations(&state);

        assert_eq!(recovery_requests.load(Ordering::SeqCst), 1);
        let app = state.lock().unwrap();
        assert!(app.external_controller_authority_pending.contains(&hub_key));
        assert!(!app.external_controller_authority_is_ready(&hub_key));
        assert!(!app.hub_is_connected(&hub_key));
    }

    #[test]
    fn topology_merge_rooms_reconciles_runtime_room_and_device_parent() {
        let (state, runtime, hub_key) = setup_state_with_deferred_runtime();

        let office: serde_json::Value =
            serde_json::from_str(&do_topology_create_room(&state, "Office").unwrap()).unwrap();
        let den: serde_json::Value =
            serde_json::from_str(&do_topology_create_room(&state, "Den").unwrap()).unwrap();
        let target_id = office["id"].as_str().unwrap().to_string();
        let source_id = den["id"].as_str().unwrap().to_string();
        let device_id = insert_canonical_device(&state, hub_key, "matter-100", "Desk Lamp", "", "");

        do_canonical_assign_room(&state, &device_id, Some(&source_id)).unwrap();
        do_topology_merge_rooms(&state, &target_id, &source_id).unwrap();

        let s = state.lock().unwrap();
        assert!(s.topology.get(&source_id).is_none());
        assert_eq!(
            s.topology
                .get_device_node(&device_id)
                .unwrap()
                .parent_id
                .as_deref(),
            Some(target_id.as_str())
        );
        assert_eq!(
            s.canonical_registry
                .get(&device_id)
                .unwrap()
                .room_id
                .as_deref(),
            Some(target_id.as_str())
        );
        drop(s);

        assert!(
            runtime.engine_room_snapshot(&source_id).is_none(),
            "merged source room should be removed from runtime"
        );
        assert_eq!(
            runtime
                .engine_node_snapshot(&device_id)
                .unwrap()
                .parent_id
                .as_deref(),
            Some(target_id.as_str())
        );
    }

